    governanceLog = pgTable("governance_log", {
      id: serial("id").primaryKey(),
      seqNo: bigint("seq_no", { mode: "number" }).notNull().unique(),
      // Event classification
      eventType: varchar("event_type", { length: 64 }).notNull(),
      component: varchar("component", { length: 128 }).notNull(),
      // e.g., "sunam_thresholds", "escalation_thresholds", "pattern_decay_rules"
      scope: varchar("scope", { length: 256 }),
      // e.g., "signal_type:wage_theft", "pattern_type:entity_recurrence"
      // Before/after state (canonical JSON)
      previousState: text("previous_state"),
      // canonical JSON of previous state (null for creation)
      newState: text("new_state").notNull(),
      // canonical JSON of new state
      // Rationale (required, enforced — no empty strings)
      rationale: text("rationale").notNull(),
      // Actor (hashed for privacy, traceable for audit)
      actorHash: varchar("actor_hash", { length: 64 }).notNull(),
      // SHA-256 of actor identity
      actorRole: varchar("actor_role", { length: 32 }).notNull(),
      // "admin", "system", "engine"
      // Hash chain
      previousHash: varchar("previous_hash", { length: 64 }).notNull(),
      // SHA-256 of previous entry (genesis = "0".repeat(64))
      entryHash: varchar("entry_hash", { length: 64 }).notNull(),
      // SHA-256 of this entry's canonical content + previous_hash
      // Timestamp
      createdAt: bigint("created_at", { mode: "number" }).notNull()
    }, (table) => [
      index("idx_gov_log_event_type").on(table.eventType),
      index("idx_gov_log_component").on(table.component),
      index("idx_gov_log_created").on(table.createdAt),
      index("idx_gov_log_actor").on(table.actorHash),
      index("idx_gov_log_seq").on(table.seqNo)
    ]);
    governanceSnapshots = pgTable("governance_snapshots", {
      id: serial("id").primaryKey(),
      // Snapshot scope
      snapshotAt: bigint("snapshot_at", { mode: "number" }).notNull(),
      upToSeqNo: bigint("up_to_seq_no", { mode: "number" }).notNull(),
      // Chain verification
      hashChainRoot: varchar("hash_chain_root", { length: 128 }).notNull(),
      // hash of the chain up to seq_no
      entryCount: integer("entry_count").notNull(),
      // total entries in snapshot
      // Cryptographic signature
      signature: text("signature").notNull(),
      // detached Ed25519 signature
      signedBy: varchar("signed_by", { length: 64 }).notNull(),
      // key identifier / fingerprint
      signatureAlgorithm: varchar("signature_algorithm", { length: 32 }).notNull().default("Ed25519"),
      // Metadata
      createdAt: bigint("created_at", { mode: "number" }).notNull()
    }, (table) => [
      index("idx_gov_snap_seq").on(table.upToSeqNo),
      index("idx_gov_snap_created").on(table.createdAt)
    ]);
    sessionLog = pgTable("session_log", {
      id: serial("id").primaryKey(),
      // Session identity
      sessionId: varchar("session_id", { length: 36 }).notNull().unique(),
      // UUID
      // Timing
      startedAt: bigint("started_at", { mode: "number" }).notNull(),
      completedAt: bigint("completed_at", { mode: "number" }),
      // null if still running
      // Actor type
      actorType: varchar("actor_type", { length: 20 }).notNull(),
      // "tsunam" | "luminari"
      // Governance anchor — the verified seq_no this session started from
      governanceAnchor: integer("governance_anchor").notNull(),
      // last_verified_seq_no at session start
      // Actions and results
      actionsTaken: jsonb("actions_taken").$type().notNull().default([]),
      results: jsonb("results").$type().notNull().default({}),
      // Governance entries produced by this session
      // Range: [start_seq_no, end_seq_no] inclusive
      // Enables verification: all entries in this range were created by this session
      governanceEntriesStart: integer("governance_entries_start"),
      // null if no entries created
      governanceEntriesEnd: integer("governance_entries_end"),
      // null if no entries created
      // Next actions for the following session
      nextActions: jsonb("next_actions").$type().notNull().default([]),
      // State snapshot at end of session
      stateSnapshot: jsonb("state_snapshot").$type().notNull().default({}),
      // Metadata
      createdAt: bigint("created_at", { mode: "number" }).notNull()
    }, (table) => [
      index("idx_session_id").on(table.sessionId),
      index("idx_session_actor").on(table.actorType),
      index("idx_session_anchor").on(table.governanceAnchor),
      index("idx_session_created").on(table.createdAt),
      index("idx_session_gov_range").on(table.governanceEntriesStart, table.governanceEntriesEnd)
    ]);
