    pool_max: pool3?.options?.max ?? 5,
    connection_timeout_ms: pool3?.options?.connectionTimeoutMillis ?? 1e4,
    idle_timeout_ms: pool3?.options?.idleTimeoutMillis ?? 3e4,
    max_uses: pool3?.options?.maxUses ?? 7500,
    statement_timeout_ms: pool3?.options?.statement_timeout ?? null,
