function normalize_error_message(error) {
  return error instanceof Error ? error.message : String(error);
}
function is_query_timeout_error(error) {
  const err = error;
  const message = normalize_error_message(error).toLowerCase();
  return err?.code === "57014" || message.includes("statement timeout") || message.includes("query read timeout") || message.includes("query timeout");
}
function classify_db_error(error) {
  const err = error;
  const message = normalize_error_message(error).toLowerCase();
  if (err?.code === "pool_acquire_timeout") return "pool_acquire_timeout";
  if (err?.code === "query_timeout" || is_query_timeout_error(error)) return "query_timeout";
  if (message.includes("timeout exceeded when trying to connect")) return "pool_acquire_timeout";
  if (message.includes("connection terminated due to connection timeout")) return "pool_acquire_timeout";
  return "db_error";
}
async function connect_with_pool_timeout(timeout_ms, label = "db") {
  const pool3 = getPool();
  const wait_started_at = Date.now();
  let timed_out = false;
  let timeout;
  const connect_promise = pool3.connect().then((client) => {
    if (timed_out) {
      client.release();
      return Promise.reject(new DbTimeoutDiagnosticError("pool_acquire_timeout", `${label} pool acquire timed out after ${timeout_ms}ms`, timeout_ms));
    }
    const pool_wait_ms = Date.now() - wait_started_at;
    console.warn("[DB] pool_acquire_succeeded", { label, pool_wait_ms, acquisition_time_ms: pool_wait_ms, acquire_timeout_ms: timeout_ms, pool_total_count: pool3.totalCount, pool_idle_count: pool3.idleCount, pool_waiting_count: pool3.waitingCount });
    return client;
  });
  const timeout_promise = new Promise((_, reject) => {
    timeout = setTimeout(() => {
      timed_out = true;
      const pool_wait_ms = Date.now() - wait_started_at;
      console.warn("[DB] pool_acquire_timed_out", { label, pool_wait_ms, acquire_timeout_ms: timeout_ms, pool_total_count: pool3.totalCount, pool_idle_count: pool3.idleCount, pool_waiting_count: pool3.waitingCount });
      reject(new DbTimeoutDiagnosticError("pool_acquire_timeout", `${label} pool acquire timed out after ${timeout_ms}ms`, timeout_ms));
    }, timeout_ms);
  });
  try {
    return await Promise.race([connect_promise, timeout_promise]);
  } catch (error) {
    if (classify_db_error(error) === "pool_acquire_timeout") {
      throw error instanceof DbTimeoutDiagnosticError ? error : new DbTimeoutDiagnosticError("pool_acquire_timeout", `${label} pool acquire failed or timed out`, timeout_ms, normalize_error_message(error));
    }
    throw error;
  } finally {
    if (timeout) clearTimeout(timeout);
  }
}
async function query_with_diagnostics(text3, values = [], options = {}) {
  const label = options.label ?? "db_query";
  const pool_acquire_timeout_ms = options.pool_acquire_timeout_ms ?? 1e3;
  const query_timeout_ms = options.query_timeout_ms ?? 1e4;
  const client = await connect_with_pool_timeout(pool_acquire_timeout_ms, label);
  try {
    const query_started_at = Date.now();
    try {
      const result = await client.query({ text: text3, values, query_timeout: query_timeout_ms });
      console.warn("[DB] query_diagnostics", { label, query_execution_time_ms: Date.now() - query_started_at, query_timeout_ms, row_count: result.rowCount });
      return result;
    } catch (error) {
      console.warn("[DB] query_diagnostics", { label, query_execution_time_ms: Date.now() - query_started_at, query_timeout_ms, status: "failed", error: normalize_error_message(error) });
      throw error;
    }
  } catch (error) {
    if (is_query_timeout_error(error)) {
      throw new DbTimeoutDiagnosticError("query_timeout", `${label} query timed out after ${query_timeout_ms}ms`, query_timeout_ms, normalize_error_message(error));
    }
    throw error;
  } finally {
    client.release();
  }
}
