async function updateUploadSessionStatus(sessionId, status) {
  await db.update(uploadSessions).set({
    status,
    updatedAt: Date.now()
  }).where(eq(uploadSessions.id, sessionId));
}
async function finalizeUploadSession(sessionId) {
  const session = await getUploadSession(sessionId);
  if (!session) return;
  const processed = session.completedFiles + session.failedFiles + session.duplicateFiles;
  let finalStatus;
  if (session.failedFiles > 0 && session.completedFiles === 0) {
    finalStatus = "failed";
  } else if (processed >= session.totalFiles) {
    finalStatus = "complete";
  } else {
    finalStatus = "processing";
    return;
  }
  await updateUploadSessionStatus(sessionId, finalStatus);
}
async function expireStaleUploadSessions(thresholdMs = DEFAULT_STALE_THRESHOLD_MS) {
  const cutoff = Date.now() - thresholdMs;
  const result = await db.update(uploadSessions).set({
    status: "expired",
    updatedAt: Date.now()
  }).where(
    and(
      inArray(uploadSessions.status, ["uploading", "processing"]),
      lt(uploadSessions.updatedAt, cutoff)
    )
  );
  const expiredCount = result[0]?.affectedRows ?? 0;
  if (expiredCount > 0) {
    console.log(`[Upload Lifecycle] Expired ${expiredCount} stale upload session(s) (threshold: ${thresholdMs}ms)`);
  }
  return expiredCount;
}
async function getProvenanceDriftMetrics(caseId2) {
  const caseFilter = caseId2 ? eq(findings.caseId, caseId2) : void 0;
  const statusQuery = db.select({
    status: findings.provenanceStatus,
    count: sql2`count(*)`
  }).from(findings);
  const statusCounts = caseFilter ? await statusQuery.where(caseFilter).groupBy(findings.provenanceStatus) : await statusQuery.groupBy(findings.provenanceStatus);
  let linked = 0;
  let unsupported = 0;
  let total = 0;
  for (const row of statusCounts) {
    total += row.count;
    if (row.status === "linked") linked = row.count;
    else if (row.status === "unsupported") unsupported = row.count;
  }
  const avgQuery = db.select({
    avg: sql2`AVG(JSON_LENGTH(claimIds))`
  }).from(findings);
  const [avgClaims] = caseFilter ? await avgQuery.where(and(eq(findings.provenanceStatus, "linked"), caseFilter)) : await avgQuery.where(eq(findings.provenanceStatus, "linked"));
  const caseQuery = db.select({
    caseId: findings.caseId,
    caseName: cases.name,
    total: sql2`count(*)`,
    linked: sql2`SUM(CASE WHEN ${findings.provenanceStatus} = 'linked' THEN 1 ELSE 0 END)`,
    unsupported: sql2`SUM(CASE WHEN ${findings.provenanceStatus} = 'unsupported' THEN 1 ELSE 0 END)`
  }).from(findings).leftJoin(cases, eq(findings.caseId, cases.id));
  const caseCounts = caseFilter ? await caseQuery.where(caseFilter).groupBy(findings.caseId, cases.name) : await caseQuery.groupBy(findings.caseId, cases.name);
  return {
    totalFindings: total,
    linkedFindings: linked,
    unsupportedFindings: unsupported,
    provenanceCoverage: total > 0 ? Math.round(linked / total * 1e4) / 100 : 100,
    avgClaimsPerFinding: avgClaims?.avg ? Math.round(avgClaims.avg * 100) / 100 : 0,
    fallbackMatcherHitRate: 0,
    // Populated from pipeline runtime stats
    unsupportedRate: total > 0 ? Math.round(unsupported / total * 1e4) / 100 : 0,
    avgProcessingTimeMs: 0,
    // Populated from pipeline runtime stats
    findingsByCase: caseCounts.map((r) => ({
      caseId: r.caseId,
      caseName: r.caseName || "Unknown",
      total: r.total,
      linked: r.linked,
      unsupported: r.unsupported
    }))
  };
}
