init_db();
var SUPABASE_PROJECT = "wepxlinwbjrkqdzkqpar";
var CACHE_TTL_MS = 45e3;
var DIAGNOSTIC_POOL_ACQUIRE_TIMEOUT_MS = 750;
var DIAGNOSTIC_QUERY_TIMEOUT_MS = 4e3;
var cached_diagnostic = null;
function livenessPayload() {
  return {
    ok: true,
    runtime: "active",
    service: "luminari",
    supabase_project: SUPABASE_PROJECT,
    timestamp: (/* @__PURE__ */ new Date()).toISOString()
  };
}
function sanitizeError(error) {
  const raw_message = error instanceof Error ? error.message : String(error);
  const message = raw_message.replace(/password=[^\s&]+/g, "password=***").slice(0, 500);
  return { code: "database_unreachable", message };
}
async function buildDatabaseDiagnostic() {
  const timestamp3 = (/* @__PURE__ */ new Date()).toISOString();
  const database_url = process.env.DATABASE_URL ? "configured" : "missing";
  try {
    const { rows: rows2 } = await query_with_diagnostics(
      `
        select
          version() as version,
          (
            select count(*)::int
            from information_schema.tables
            where table_schema = 'public'
              and table_type = 'BASE TABLE'
          ) as public_tables,
          (
            select count(*)::int
            from information_schema.views
            where table_schema = 'public'
          ) as public_views,
          (
            select count(*)::int
            from information_schema.table_constraints
            where table_schema = 'public'
              and constraint_type = 'FOREIGN KEY'
          ) as foreign_keys
      `,
      [],
      {
        label: "db_diagnostic",
        pool_acquire_timeout_ms: DIAGNOSTIC_POOL_ACQUIRE_TIMEOUT_MS,
        query_timeout_ms: DIAGNOSTIC_QUERY_TIMEOUT_MS
      }
    );
    const row = rows2[0];
    const public_tables = Number(row?.public_tables ?? 0);
    const public_views = Number(row?.public_views ?? 0);
    const foreign_keys = Number(row?.foreign_keys ?? 0);
    return {
      ok: true,
      runtime: "active",
      database: "connected",
      database_url,
      database_version: String(row?.version ?? "unknown"),
      supabase_project: SUPABASE_PROJECT,
      public_tables,
      db_diagnostic: {
        tables: { total: public_tables },
        views: { total: public_views },
        foreign_keys: { total: foreign_keys },
        errors: []
      },
      timestamp: timestamp3
    };
  } catch (error) {
    const diagnostic_error = sanitizeError(error);
    return {
      ok: false,
      runtime: "active",
      database: "unreachable",
      database_url,
      database_version: null,
      supabase_project: SUPABASE_PROJECT,
      public_tables: null,
      db_diagnostic: {
        tables: { total: null },
        views: { total: null },
        foreign_keys: { total: null },
        errors: [diagnostic_error]
      },
      error: diagnostic_error,
      timestamp: timestamp3
    };
  }
}
async function getDatabaseDiagnostic() {
  const now3 = Date.now();
  if (cached_diagnostic && cached_diagnostic.expires_at > now3) return cached_diagnostic.payload;
  const payload = await buildDatabaseDiagnostic();
  cached_diagnostic = { expires_at: now3 + CACHE_TTL_MS, payload };
  return payload;
}
async function sendDatabaseDiagnostic(res) {
  res.setHeader("Cache-Control", "no-store, no-cache, must-revalidate");
  const payload = await getDatabaseDiagnostic();
  res.status(payload.ok ? 200 : 503).json(payload);
}

