// server/extraction-recovery.ts
init_db();
init_const();
var RECOVERY_MAX_RETRIES = 5;
var RECOVERY_BASE_DELAY_MS = 2e3;
var RECOVERY_MAX_CONCURRENT = 5;
var RETRYABLE_PATTERNS = [
  // Service temporarily unavailable
  "service temporarily",
  "temporarily unavailable",
  "temporarily at capacity",
  "503",
  "502",
  "500",
  // Rate limiting
  "too many requests",
  "rate limit",
  "429",
  "Too Many Requests",
  // Usage exhaustion (transient — may be restored)
  "412",
  "usage exhausted",
  "Precondition Failed",
  // Network / timeout
  "network",
  "timeout",
  "ETIMEDOUT",
  "ECONNRESET",
  "ECONNREFUSED",
  "ENOTFOUND",
  "socket hang up",
  // JSON parse errors from truncated responses
  "unexpected end of JSON",
  "Unexpected end of JSON",
  "JSON.parse"
];
var NON_RETRYABLE_PATTERNS = [
  "No text could be extracted",
  "no text extracted",
  "unsupported file type",
  "Unsupported file type",
  "corrupted file",
  "Empty archive",
  "zero extractable content",
  "invalid PDF",
  "Invalid PDF",
  "password protected",
  "Password protected",
  "encrypted file"
];
function classifyExtractionFailure(errorMessage) {
  if (!errorMessage || errorMessage.trim().length === 0) {
    return "non_retryable";
  }
  for (const pattern of NON_RETRYABLE_PATTERNS) {
    if (errorMessage.includes(pattern)) {
      return "non_retryable";
    }
  }
  for (const pattern of RETRYABLE_PATTERNS) {
    if (errorMessage.includes(pattern)) {
      return "retryable";
    }
  }
  return "non_retryable";
}
async function identifyRecoverableDocuments(caseId2, snapshotId, documentIds) {
  const allDocs = await listDocuments(caseId2);
  const failedStatuses = ["error", "failed_permanent", "retrying"];
  return allDocs.filter((d) => {
    if (d.snapshotId !== snapshotId) return false;
    if (!failedStatuses.includes(d.status)) return false;
    if (documentIds && documentIds.length > 0) {
      if (!documentIds.includes(d.id)) return false;
    }
    return true;
  }).map((d) => ({
    id: d.id,
    filename: d.filename,
    status: d.status,
    errorMessage: d.errorMessage,
    retryCount: d.retryCount ?? 0,
    snapshotId: d.snapshotId
  }));
}
async function executeExtractionRecovery(request, userId) {
  const { caseId: caseId2, snapshotId, documentIds, retryOnly = true } = request;
  const snapshot = await getSnapshot(snapshotId);
  if (!snapshot) {
    throw new Error(`Snapshot ${snapshotId} not found`);
  }
  if (snapshot.caseId !== caseId2) {
    throw new Error(`Snapshot ${snapshotId} does not belong to case ${caseId2}`);
  }
  const recoverableDocs = await identifyRecoverableDocuments(
    caseId2,
    snapshotId,
    documentIds
  );
  let newSnapshotId = null;
  let snapshotCreated = false;
  const isSealed = snapshot.status === "sealed";
  if (isSealed && recoverableDocs.length > 0) {
    const allSnapshotDocs = await listDocuments(caseId2);
    const docsInSnapshot = allSnapshotDocs.filter(
      (d) => d.snapshotId === snapshotId
    );
    const docIds = docsInSnapshot.map((d) => d.id);
    const docHashes = {};
    for (const d of docsInSnapshot) {
      if (d.sha256Hash) docHashes[String(d.id)] = d.sha256Hash;
    }
    const newSnapshot = await createCorpusSnapshot({
      caseId: caseId2,
      engineVersion: ENGINE_VERSION,
      documentIds: docIds,
      documentHashes: docHashes
    });
    newSnapshotId = newSnapshot.id;
    snapshotCreated = true;
    const { documents: documents4 } = await Promise.resolve().then(() => (init_schema(), schema_exports));
    const { eq: eq88 } = await import("drizzle-orm");
    for (const doc of docsInSnapshot) {
      await db.update(documents4).set({ snapshotId: newSnapshot.id }).where(eq88(documents4.id, doc.id));
    }
    await logAudit({
      caseId: caseId2,
      userId,
      action: "recovery_snapshot_created",
      targetType: "snapshot",
      targetId: newSnapshot.id,
      details: {
        sourceSnapshotId: snapshotId,
        sourceVersion: snapshot.version,
        newVersion: newSnapshot.version,
        documentCount: docIds.length,
        recoverableCount: recoverableDocs.length
      }
    });
  }
  const targetSnapshotId = newSnapshotId ?? snapshotId;
  const results = [];
  let totalQueued = 0;
  let totalSkipped = 0;
  for (const doc of recoverableDocs) {
    const classification = classifyExtractionFailure(doc.errorMessage || "");
    if (retryOnly && classification === "non_retryable") {
      results.push({
        documentId: doc.id,
        filename: doc.filename,
        previousStatus: doc.status,
        previousError: doc.errorMessage,
        classification,
        action: "skipped_non_retryable"
      });
      totalSkipped++;
      continue;
    }
    if (doc.retryCount >= RECOVERY_MAX_RETRIES) {
      results.push({
        documentId: doc.id,
        filename: doc.filename,
        previousStatus: doc.status,
        previousError: doc.errorMessage,
        classification,
        action: "skipped_max_retries"
      });
      totalSkipped++;
      continue;
    }
    await updateDocumentAnalysis(doc.id, {
      status: "uploaded",
      errorMessage: `Recovery queued (attempt ${doc.retryCount + 1}/${RECOVERY_MAX_RETRIES})`
    });
    await logAudit({
      caseId: caseId2,
      userId,
      action: "retry_extraction",
      targetType: "document",
      targetId: doc.id,
      details: {
        previousStatus: doc.status,
        previousError: doc.errorMessage,
        classification,
        retryAttempt: doc.retryCount + 1,
        maxRetries: RECOVERY_MAX_RETRIES,
        targetSnapshotId,
        snapshotCreated
      }
    });
    results.push({
      documentId: doc.id,
      filename: doc.filename,
      previousStatus: doc.status,
      previousError: doc.errorMessage,
      classification,
      action: "queued",
      newSnapshotId: snapshotCreated ? newSnapshotId : void 0
    });
    totalQueued++;
  }
  const queuedDocs = results.filter((r) => r.action === "queued");
  if (queuedDocs.length > 0) {
    const { enqueueDocument: enqueueDocument2 } = await Promise.resolve().then(() => (init_analysis_pipeline(), analysis_pipeline_exports));
    for (let i = 0; i < queuedDocs.length; i++) {
      const doc = queuedDocs[i];
      const currentDoc = await getDocument(doc.documentId);
      const attempt = currentDoc?.retryCount ?? 0;
      const delayMs = Math.pow(2, attempt) * RECOVERY_BASE_DELAY_MS;
      const batchIndex = Math.floor(i / RECOVERY_MAX_CONCURRENT);
      const totalDelay = delayMs + batchIndex * RECOVERY_BASE_DELAY_MS;
      setTimeout(() => {
        enqueueDocument2(doc.documentId, caseId2);
      }, totalDelay);
    }
  }
  await logAudit({
    caseId: caseId2,
    userId,
    action: "extraction_recovery_completed",
    targetType: "case",
    targetId: caseId2,
    details: {
      sourceSnapshotId: snapshotId,
      targetSnapshotId,
      snapshotCreated,
      totalEligible: recoverableDocs.length,
      totalQueued,
      totalSkipped,
      documentResults: results.map((r) => ({
        documentId: r.documentId,
        action: r.action,
        classification: r.classification
      }))
    }
  });
  return {
    caseId: caseId2,
    sourceSnapshotId: snapshotId,
    newSnapshotId,
    snapshotCreated,
    totalEligible: recoverableDocs.length,
    totalQueued,
    totalSkipped,
    documents: results
  };
}

