  let text3 = `Did you know? ${spotlight.headline}

${spotlight.explanation}`;
  if (spotlight.action_step) {
    text3 += `

${spotlight.action_step}`;
  }
  if (spotlight.action_contact) {
    text3 += `

Contact: ${spotlight.action_contact}`;
  }
