async function searchCoalitionEntities(params) {
  const { query, entityTypes, domains, jurisdiction, state, minInfluence = 0, limit = 50 } = params;
  const types = entityTypes?.length ? entityTypes : ["legislator", "agency", "advocacy_org", "media"];
  const results = [];
  const searchParams = { query, state, jurisdiction, minInfluence, limit };
  if (types.includes("legislator")) {
    const rows2 = await searchLegislators(searchParams);
    for (const r of rows2) {
      const iss = safeJsonParse(r.issue_alignment);
      if (domains?.length && !domainMatch(iss, domains)) continue;
      results.push({
        id: r.id,
        entityType: "legislator",
        name: r.name,
        subtitle: `${r.title} (${r.party}) - ${r.state}`,
        jurisdiction: r.jurisdiction_level,
        state: r.state,
        domains: iss,
        influenceScore: r.influence_score,
        contactEmail: r.contact_email,
        contactPhone: r.contact_phone,
        website: r.website
      });
    }
  }
  if (types.includes("agency")) {
    const rows2 = await searchAgencies(searchParams);
    for (const r of rows2) {
      const doms = safeJsonParse(r.domains);
      if (domains?.length && !domainMatch(doms, domains)) continue;
      results.push({
        id: r.id,
        entityType: "agency",
        name: r.name,
        subtitle: r.acronym || r.agency_type,
        jurisdiction: r.jurisdiction_level,
        state: r.state,
        domains: doms,
        influenceScore: r.effectiveness_score,
        contactEmail: r.contact_email,
        contactPhone: r.contact_phone,
        website: r.website
      });
    }
  }
  if (types.includes("advocacy_org")) {
    const rows2 = await searchAdvocacyOrgs(searchParams);
    for (const r of rows2) {
      const doms = safeJsonParse(r.domains);
      if (domains?.length && !domainMatch(doms, domains)) continue;
      results.push({
        id: r.id,
        entityType: "advocacy_org",
        name: r.name,
        subtitle: r.org_type || "Advocacy Organization",
        jurisdiction: r.jurisdiction || "National",
        state: r.state,
        domains: doms,
        influenceScore: r.influence_score,
        contactEmail: r.contact_email,
        contactPhone: r.contact_phone,
        website: r.website
      });
    }
  }
  if (types.includes("media")) {
    const rows2 = await searchMedia(searchParams);
    for (const r of rows2) {
      const beats = safeJsonParse(r.beat);
      if (domains?.length && !domainMatch(beats, domains)) continue;
      results.push({
        id: r.id,
        entityType: "media",
        name: r.name,
        subtitle: `${r.outlet} (${r.media_type})`,
        jurisdiction: r.jurisdiction,
        state: r.state,
        domains: beats,
        influenceScore: r.reach_score,
        contactEmail: r.contact_email,
        contactPhone: r.contact_phone,
        website: r.website
      });
    }
  }
  results.sort((a, b) => b.influenceScore - a.influenceScore);
  return results.slice(0, limit);
}
async function getLegislatorDetail(id) {
  const [rows2] = await db.execute(sql8`SELECT * FROM coalition_legislators WHERE id = ${id}`);
  const r = rows2[0];
  if (!r) return null;
  return {
    id: r.id,
    name: r.name,
    title: r.title,
    chamber: r.chamber,
    state: r.state,
    district: r.district,
    party: r.party,
    jurisdictionLevel: r.jurisdiction_level,
    committees: safeJsonParse(r.committees),
    issueAlignment: safeJsonParse(r.issue_alignment),
    contactOffice: r.contact_office,
    contactPhone: r.contact_phone,
    contactEmail: r.contact_email,
    website: r.website,
    socialMedia: safeJsonParse(r.social_media, {}),
    votingRecordUrl: r.voting_record_url,
    influenceScore: r.influence_score,
    accessibilityScore: r.accessibility_score,
    notes: r.notes,
    isActive: !!r.is_active
  };
}
