  if (!obj.primary || typeof obj.primary.type !== "string" || typeof obj.primary.id !== "number" || typeof obj.primary.table !== "string") {
    throw new Error(`[OutputRefs] REJECTED: primary must have type (string), id (number), table (string)`);
  }
