async function validateMetadataCompleteness(runId) {
  const errors = [];
  const [runRows] = await db.execute(
    sql11`SELECT run_id, engine_id, output_refs, status FROM engine_runs WHERE run_id = ${runId}`
  );
  const runs = runRows;
  if (runs.length === 0) {
    return { valid: false, errors: [`No engine_run found for run_id: ${runId}`] };
  }
  const run = runs[0];
  if (run.status !== "success") {
    errors.push(`Run status is "${run.status}", expected "success"`);
  }
  if (!run.output_refs) {
    errors.push("Missing output_refs");
    return { valid: false, errors };
  }
  const refs = typeof run.output_refs === "string" ? JSON.parse(run.output_refs) : run.output_refs;
  if (refs.primary) {
    const table = refs.primary.table;
    const id = refs.primary.id;
    const [trCheck] = await db.execute(
      sql11`SELECT id FROM table_registry WHERE tableName = ${table} LIMIT 1`
    );
    if (trCheck.length === 0) {
      errors.push(`Primary table "${table}" not found in table_registry`);
    }
    try {
      const [rowCheck] = await db.execute(
        sql11.raw(`SELECT id FROM "${table}" WHERE id = ${id} LIMIT 1`)
      );
      if (rowCheck.length === 0) {
        errors.push(`Primary entity id=${id} not found in ${table}`);
      }
    } catch (e) {
      errors.push(`Failed to verify primary entity: ${e.message}`);
    }
    if (refs.artifacts && Array.isArray(refs.artifacts)) {
      for (const artifact of refs.artifacts) {
        const [artTrCheck] = await db.execute(
          sql11`SELECT id FROM table_registry WHERE tableName = ${artifact.table} LIMIT 1`
        );
        if (artTrCheck.length === 0) {
          errors.push(`Artifact table "${artifact.table}" not found in table_registry`);
        }
        try {
          const [artRowCheck] = await db.execute(
            sql11.raw(`SELECT id FROM "${artifact.table}" WHERE id = ${artifact.id} LIMIT 1`)
          );
          if (artRowCheck.length === 0) {
            errors.push(`Artifact entity id=${artifact.id} not found in ${artifact.table}`);
          }
        } catch (e) {
          errors.push(`Failed to verify artifact entity: ${e.message}`);
        }
      }
    }
    if (refs.meta?.tables && Array.isArray(refs.meta.tables)) {
      for (const t2 of refs.meta.tables) {
        const [tCheck] = await db.execute(
          sql11`SELECT id FROM table_registry WHERE tableName = ${t2} LIMIT 1`
        );
        if (tCheck.length === 0) {
          errors.push(`Meta table "${t2}" not found in table_registry`);
        }
      }
    }
  }
  return { valid: errors.length === 0, errors };
}
async function generateOutput(snapshotId) {
  if (!snapshotId) throw new Error("Snapshot required \u2014 Alpha Lake only accepts snapshot_id");
  const [runRows] = await db.execute(sql11`
    SELECT run_id, engine_id, status, output_refs, caseId, startedAt, completedAt
    FROM engine_runs
    WHERE snapshot_id = ${snapshotId}
    ORDER BY startedAt ASC
  `);
  const runs = runRows;
  if (runs.length === 0) {
    throw new Error(`No engine_runs found for snapshot_id=${snapshotId}`);
  }
  const assembled = {
    snapshot_id: snapshotId,
    generated_at: Date.now(),
    engine_count: runs.length,
    runs: runs.map((r) => ({
      run_id: r.run_id,
      engine_id: r.engine_id,
      status: r.status,
      output_refs: typeof r.output_refs === "string" ? JSON.parse(r.output_refs) : r.output_refs,
      case_id: r.caseId,
      started_at: r.startedAt,
      completed_at: r.completedAt
    }))
  };
  const now3 = Date.now();
  const [ins] = await db.execute(sql11`
    INSERT INTO alpha_lake_exports (snapshot_id, export_type, engine_run_ids, output_payload, status, createdAt)
    VALUES (
      ${snapshotId},
      ${"full"},
      ${JSON.stringify(runs.map((r) => r.run_id))},
      ${JSON.stringify(assembled)},
      ${"completed"},
      ${now3}
    )
  `);
  const exportId = ins.insertId;
  await logConduitEvent({
    eventType: "ALPHA_EXPORT",
    pipelineId: "alpha_lake",
    snapshotId,
    metadata: { export_id: exportId, engine_count: runs.length, timestamp: now3 }
  });
  return { snapshotId, runs: assembled.runs, exportId };
}

// server/engine-metadata.ts
var VALID_STATUSES = ["pending", "running", "success", "failed", "unknown"];
function assertStatus(s) {
  if (!VALID_STATUSES.includes(s)) {
    throw new Error(`[EngineMetadata] Invalid status "${s}". Must be one of: ${VALID_STATUSES.join(" | ")}`);
  }
  return s;
}
function syncStatus(s) {
  const validated = assertStatus(s);
  return { runStatus: validated, status: validated };
}
async function wrapEngineExecution(config, engineFn, extractOutputRefs) {
  const runId = `run_${config.engineId}_${Date.now()}_${randomUUID().slice(0, 8)}`;
  const now3 = Date.now();
  await db.insert(engineRuns).values({
    runId,
    caseId: config.caseId,
    engineId: config.engineId,
    userId: config.userId ?? null,
    runType: config.runType ?? "full_pipeline",
    ...syncStatus("pending"),
    currentStage: "init",
    stageResults: null,
    outputRefs: null,
    snapshotId: config.snapshotId ?? null,
    startedAt: now3,
    createdAt: now3
  });
  await db.update(engineRuns).set({ ...syncStatus("running"), currentStage: "executing" }).where(sql12`run_id = ${runId}`);
  try {
    const gateResult = await validateGate(config.engineId);
    if (!gateResult.pass) {
      await db.update(engineRuns).set({
        ...syncStatus("failed"),
        currentStage: "validation_gate",
        errorMessage: gateResult.reason,
        outputRefs: null,
        completedAt: Date.now()
      }).where(sql12`run_id = ${runId}`);
      return { runId, engineId: config.engineId, status: "failed", outputRefs: null, error: gateResult.reason };
    }
    const result = await engineFn();
    let outputRefs = null;
    if (extractOutputRefs) {
      outputRefs = await extractOutputRefs(result, runId);
      assertOutputRefsFormat(outputRefs);
    }
    await db.update(engineRuns).set({
      ...syncStatus("success"),
      currentStage: "done",
      outputRefs,
      completedAt: Date.now()
    }).where(sql12`run_id = ${runId}`);
    console.log(`[EngineMetadata] ${config.engineId} run ${runId} \u2192 success. OutputRefs: ${outputRefs ? "present" : "null"}`);
    await logConduitEvent({
      eventType: "ENGINE_RUN",
      engineId: config.engineId,
      runId,
      snapshotId: config.snapshotId,
      metadata: {
        status: "success",
        case_id: config.caseId,
        has_output_refs: !!outputRefs,
        tables: outputRefs?.meta?.tables ?? [],
        fields: outputRefs?.meta?.fields ?? []
      }
    });
    if (outputRefs) {
      try {
        const persistResult = await persistEngineOutputs(runId);
        console.log(`[EngineMetadata] ${config.engineId} run ${runId} \u2192 backbone persist: ${persistResult.persisted} persisted, ${persistResult?.skipped ?? 0} skipped`);
      } catch (persistErr) {
        console.error(`[EngineMetadata] ${config.engineId} run ${runId} \u2192 backbone persist error:`, persistErr?.message || persistErr);
      }
    }
    return { runId, engineId: config.engineId, status: "success", outputRefs };
  } catch (err) {
    const errorMsg = err?.message || String(err);
    await db.update(engineRuns).set({
      ...syncStatus("failed"),
      currentStage: "error",
      errorMessage: errorMsg,
      completedAt: Date.now()
    }).where(sql12`run_id = ${runId}`);
    console.error(`[EngineMetadata] ${config.engineId} run ${runId} \u2192 failed:`, errorMsg);
    await logConduitEvent({
      eventType: "ENGINE_RUN",
      engineId: config.engineId,
      runId,
      snapshotId: config.snapshotId,
      metadata: { status: "failed", case_id: config.caseId, error: errorMsg }
    }).catch(() => {
    });
    return { runId, engineId: config.engineId, status: "failed", outputRefs: null, error: errorMsg };
  }
}
async function validateGate(engineId) {
  const [rows2] = await db.execute(
    sql12`SELECT engine_id_er, enabled_er FROM engine_registry WHERE engine_id_er = ${engineId} LIMIT 1`
  );
  const registry = rows2;
  if (registry.length === 0) {
    return { pass: false, reason: `Engine ${engineId} is not registered in engine_registry. Registration required before execution.` };
  }
  const entry = registry[0];
  if (!entry.enabled_er) {
    return { pass: false, reason: `Engine ${engineId} is disabled in engine_registry` };
  }
  return { pass: true };
}

// server/canonical-guard.ts
function auditOutputRefs(outputRefs) {
  const violations = [];
  if (!outputRefs || typeof outputRefs !== "object") {
    violations.push("output_refs is null or not an object");
    return violations;
  }
  if (outputRefs.primary?.table && !outputRefs.primary.table.startsWith("canonical_")) {
    violations.push(`primary.table="${outputRefs.primary.table}" is not canonical`);
  }
  if (Array.isArray(outputRefs.artifacts)) {
    for (const a of outputRefs.artifacts) {
      if (a?.table && !a.table.startsWith("canonical_")) {
        violations.push(`artifact.table="${a.table}" is not canonical`);
      }
    }
  }
  if (Array.isArray(outputRefs.meta?.tables)) {
    for (const t2 of outputRefs.meta.tables) {
      if (!t2.startsWith("canonical_")) {
        violations.push(`meta.tables contains non-canonical table "${t2}"`);
      }
    }
  }
  return violations;
}

// server/engine-entrypoint-wrapper.ts
async function withEngineTracking(config, fn) {
  let capturedResult;
  const runResult = await wrapEngineExecution(
    {
      engineId: config.engineId,
      caseId: config.caseId,
      userId: config.userId,
      runType: config.runType,
      snapshotId: config.snapshotId
    },
    async () => {
      capturedResult = await fn();
      return capturedResult;
    },
    config.extractOutputRefs ? async (result2, runId) => {
      const refs = await config.extractOutputRefs(result2, runId);
      const violations = auditOutputRefs(refs);
      if (violations.length > 0) {
        throw new Error(
          `[CanonicalGuard] Engine "${config.engineId}" produced non-canonical output_refs: ` + violations.join("; ")
        );
      }
      return refs;
    } : void 0
  );
  if (runResult.status === "failed" && !capturedResult) {
    throw new Error(runResult.error || `Engine ${config.engineId} failed`);
  }
  const result = capturedResult;
  if (result && typeof result === "object") {
    result._engineRunId = runResult.runId;
  }
  return result;
}
