async function logAction(params) {
  const id = randomUUID2();
  const impactScore = params.impactScore || 0;
  const result = params.result || null;
  const source = params.source || null;
  const sourceId = params.sourceId || null;
  await db.execute(sql13`
    INSERT INTO campaign_actions (id, campaign_id, stage_number, date, action, responsible_party, responsible_party_type, impact_score, result, source, source_id)
    VALUES (${id}, ${params.campaignId}, ${params.stageNumber}, NOW(), ${params.action}, ${params.responsibleParty}, ${params.responsiblePartyType}, ${impactScore}, ${result}, ${source}, ${sourceId})
  `);
  return id;
}
async function getCampaignActions(campaignId, stageNumber) {
  if (stageNumber) {
    const [rows2] = await db.execute(sql13`
      SELECT * FROM campaign_actions WHERE campaign_id = ${campaignId} AND stage_number = ${stageNumber} ORDER BY date DESC
    `);
    return rows2.map(mapAction);
  } else {
    const [rows2] = await db.execute(sql13`
      SELECT * FROM campaign_actions WHERE campaign_id = ${campaignId} ORDER BY date DESC
    `);
    return rows2.map(mapAction);
  }
}
async function recordOutcome(params) {
  const id = randomUUID2();
  const impactScore = params.impactScore || 0;
  const notes = params.notes || null;
  const policyChangeId = params.policyChangeId || null;
  await db.execute(sql13`
    INSERT INTO campaign_outcomes (id, campaign_id, date, result, impact_score, notes, policy_change_id)
    VALUES (${id}, ${params.campaignId}, NOW(), ${params.result}, ${impactScore}, ${notes}, ${policyChangeId})
  `);
  await logAction({
    campaignId: params.campaignId,
    stageNumber: 6,
    action: `Outcome recorded: ${params.result}`,
    responsibleParty: "System",
    responsiblePartyType: "system",
    impactScore: params.impactScore || 0,
    source: "outcome_recording"
  });
  return id;
}
async function getCampaignOutcomes(campaignId) {
  const [rows2] = await db.execute(sql13`
    SELECT * FROM campaign_outcomes WHERE campaign_id = ${campaignId} ORDER BY date DESC
  `);
  return rows2.map(mapOutcome);
}
async function getCampaignDashboard() {
  const [countRows] = await db.execute(sql13`SELECT COUNT(*) as c FROM campaigns`);
  const totalCampaigns = Number(countRows[0]?.c || 0);
  const [statusRows] = await db.execute(sql13`SELECT status, COUNT(*) as c FROM campaigns GROUP BY status`);
  const byStatus = {};
  for (const r of statusRows) byStatus[r.status] = Number(r.c);
  const [stageRows] = await db.execute(sql13`SELECT current_stage, COUNT(*) as c FROM campaigns GROUP BY current_stage`);
  const byStage = {};
  for (const r of stageRows) byStage[Number(r.current_stage)] = Number(r.c);
  const [recentRows] = await db.execute(sql13`SELECT * FROM campaigns ORDER BY updated_at DESC LIMIT 10`);
  const recentCampaigns = recentRows.map(mapCampaign);
  const [actionCountRows] = await db.execute(sql13`SELECT COUNT(*) as c FROM campaign_actions`);
  const totalActions = Number(actionCountRows[0]?.c || 0);
  const [recentActionRows] = await db.execute(sql13`SELECT * FROM campaign_actions ORDER BY date DESC LIMIT 10`);
  const recentActions = recentActionRows.map(mapAction);
  const [outcomeCountRows] = await db.execute(sql13`SELECT COUNT(*) as c FROM campaign_outcomes`);
  const totalOutcomes = Number(outcomeCountRows[0]?.c || 0);
  const [avgRows] = await db.execute(sql13`SELECT AVG(impact_index) as avg_impact FROM campaigns`);
  const averageImpactIndex = Math.round(Number(avgRows[0]?.avg_impact || 0));
  return {
    totalCampaigns,
    byStatus,
    byStage,
    recentCampaigns,
    recentActions,
    totalActions,
    totalOutcomes,
    averageImpactIndex
  };
}
async function getCampaignDetail(campaignId) {
  const campaign = await getCampaign(campaignId);
  if (!campaign) return null;
  const [actions, outcomes, members, targets] = await Promise.all([
    getCampaignActions(campaignId),
    getCampaignOutcomes(campaignId),
    getCoalitionMembers(campaignId),
    getCampaignTargets(campaignId)
  ]);
  return { campaign, actions, outcomes, members, targets };
}

// server/routers/campaign-engine-router.ts
var campaignEngineRouter = router({
  // Auto-create campaigns from critical patterns
  autoCreate: protectedProcedure.mutation(async () => {
    return withEngineTracking({ engineId: ENGINE_IDS.CAMPAIGN, caseId: 0 }, () => checkAndCreateCampaigns());
  }),
  // Manual campaign creation
  create: protectedProcedure.input(z4.object({
    name: z4.string(),
    patternId: z4.string().optional(),
    jurisdiction: z4.string(),
    description: z4.string().optional(),
    impactIndex: z4.number().min(0).max(100).optional()
  })).mutation(async ({ input }) => {
    return withEngineTracking({ engineId: ENGINE_IDS.CAMPAIGN, caseId: 0 }, () => createCampaign(input));
  }),
  // Get single campaign
  get: protectedProcedure.input(z4.object({ id: z4.string() })).query(async ({ input }) => {
    return getCampaign(input.id);
  }),
  // List campaigns
  list: protectedProcedure.input(z4.object({
    status: z4.string().optional(),
    jurisdiction: z4.string().optional(),
    stage: z4.number().optional(),
    limit: z4.number().optional()
  }).optional()).query(async ({ input }) => {
    return listCampaigns(input || void 0);
  }),
  // Full campaign detail
  detail: protectedProcedure.input(z4.object({ id: z4.string() })).query(async ({ input }) => {
    return getCampaignDetail(input.id);
  }),
  // Advance stage
  advanceStage: protectedProcedure.input(z4.object({
    campaignId: z4.string(),
    notes: z4.string().optional()
  })).mutation(async ({ input }) => {
    return withEngineTracking({ engineId: ENGINE_IDS.CAMPAIGN, caseId: 0 }, () => advanceCampaignStage(input.campaignId, input.notes));
  }),
  // Link reform package
  linkReformPackage: protectedProcedure.input(z4.object({
    campaignId: z4.string(),
    reformPackageId: z4.string()
  })).mutation(async ({ input }) => {
    return withEngineTracking({ engineId: ENGINE_IDS.CAMPAIGN, caseId: 0 }, async () => {
      await linkReformPackage(input.campaignId, input.reformPackageId);
      return { success: true };
    });
  }),
  // Coalition members
  addMember: protectedProcedure.input(z4.object({
    campaignId: z4.string(),
    memberType: z4.string(),
    memberId: z4.string(),
    memberName: z4.string(),
    roleInCoalition: z4.string().optional(),
    commitmentLevel: z4.string().optional()
  })).mutation(async ({ input }) => {
    return withEngineTracking({ engineId: ENGINE_IDS.CAMPAIGN, caseId: 0 }, async () => {
      const id = await addCoalitionMember(input);
      return { id };
    });
  }),
  getMembers: protectedProcedure.input(z4.object({ campaignId: z4.string() })).query(async ({ input }) => {
    return getCoalitionMembers(input.campaignId);
  }),
  // Campaign targets
  addTarget: protectedProcedure.input(z4.object({
    campaignId: z4.string(),
    targetType: z4.string(),
    targetId: z4.string(),
    targetName: z4.string(),
    priority: z4.string().optional(),
    strategyNotes: z4.string().optional()
  })).mutation(async ({ input }) => {
    return withEngineTracking({ engineId: ENGINE_IDS.CAMPAIGN, caseId: 0 }, async () => {
      const id = await addCampaignTarget(input);
      return { id };
    });
  }),
  getTargets: protectedProcedure.input(z4.object({ campaignId: z4.string() })).query(async ({ input }) => {
    return getCampaignTargets(input.campaignId);
  }),
  updateTargetStatus: protectedProcedure.input(z4.object({
    targetId: z4.string(),
    status: z4.string(),
    response: z4.string().optional()
  })).mutation(async ({ input }) => {
    return withEngineTracking({ engineId: ENGINE_IDS.CAMPAIGN, caseId: 0 }, async () => {
      await updateTargetStatus(input.targetId, input.status, input.response);
      return { success: true };
    });
  }),
  // Actions
  logAction: protectedProcedure.input(z4.object({
    campaignId: z4.string(),
    stageNumber: z4.number(),
    action: z4.string(),
    responsibleParty: z4.string(),
    responsiblePartyType: z4.string(),
    impactScore: z4.number().optional(),
    result: z4.string().optional(),
    source: z4.string().optional()
  })).mutation(async ({ input }) => {
    return withEngineTracking({ engineId: ENGINE_IDS.CAMPAIGN, caseId: 0 }, async () => {
      const id = await logAction(input);
      return { id };
    });
  }),
  getActions: protectedProcedure.input(z4.object({
    campaignId: z4.string(),
    stageNumber: z4.number().optional()
  })).query(async ({ input }) => {
    return getCampaignActions(input.campaignId, input.stageNumber);
  }),
  // Outcomes
  recordOutcome: protectedProcedure.input(z4.object({
    campaignId: z4.string(),
    result: z4.string(),
    impactScore: z4.number().optional(),
    notes: z4.string().optional(),
    policyChangeId: z4.string().optional()
  })).mutation(async ({ input }) => {
    return withEngineTracking({ engineId: ENGINE_IDS.CAMPAIGN, caseId: 0 }, async () => {
      const id = await recordOutcome(input);
      return { id };
    });
  }),
  getOutcomes: protectedProcedure.input(z4.object({ campaignId: z4.string() })).query(async ({ input }) => {
    return getCampaignOutcomes(input.campaignId);
  }),
  // Dashboard
  dashboard: protectedProcedure.query(async () => {
    return getCampaignDashboard();
  }),
  // Stage definitions
  stages: protectedProcedure.query(async () => {
    return CAMPAIGN_STAGES;
  })
});

// server/routers/dataset-connector-router.ts
import { z as z5 } from "zod";

// server/dataset-connector-service.ts
init_db();
import { sql as sql14 } from "drizzle-orm";
async function listDatasets() {
  const [rows2] = await db.execute(sql14.raw(
    `SELECT stream_id_dsr as dataset_id, stream_name_dsr as dataset_name, source_dsr as source, jurisdiction_dsr as jurisdiction, domain_dsr as domain, 
            records_ingested_dsr as record_count, last_ingested_at_dsr as last_ingested,
            enabled_dsr as enabled, update_freq_dsr as update_frequency
     FROM data_stream_registry ORDER BY stream_name_dsr`
  ));
  return rows2.map((r) => ({
    dataset_id: r.dataset_id,
    dataset_name: r.dataset_name,
    source: r.source,
    jurisdiction: r.jurisdiction,
    domain: r.domain,
    record_count: Number(r.record_count) || 0,
    last_ingested: r.last_ingested ? Number(r.last_ingested) : null,
    enabled: Boolean(r.enabled),
    update_frequency: r.update_frequency
  }));
}
async function getDatasetById(dataset_id) {
  const [rows2] = await db.execute(sql14.raw(
    `SELECT stream_id_dsr as dataset_id, stream_name_dsr as dataset_name, source_dsr as source, jurisdiction_dsr as jurisdiction, domain_dsr as domain,
            records_ingested_dsr as record_count, last_ingested_at_dsr as last_ingested,
            enabled_dsr as enabled, update_freq_dsr as update_frequency
     FROM data_stream_registry WHERE stream_id_dsr = '${dataset_id.replace(/'/g, "''")}'`
  ));
  if (!rows2.length) return null;
  const r = rows2[0];
  return {
    dataset_id: r.dataset_id,
    dataset_name: r.dataset_name,
    source: r.source,
    jurisdiction: r.jurisdiction,
    domain: r.domain,
    record_count: Number(r.record_count) || 0,
    last_ingested: r.last_ingested ? Number(r.last_ingested) : null,
    enabled: Boolean(r.enabled),
    update_frequency: r.update_frequency
  };
}
async function getDatasetSummary() {
  const [rows2] = await db.execute(sql14.raw(
    `SELECT domain_dsr as domain, jurisdiction_dsr as jurisdiction, COUNT(*) as cnt, SUM(records_ingested_dsr) as total, SUM(enabled_dsr) as enabled
     FROM data_stream_registry GROUP BY domain_dsr, jurisdiction_dsr`
  ));
  const byDomain = {};
  const byJurisdiction = {};
  let totalDatasets = 0;
  let enabledDatasets = 0;
  let totalRecords = 0;
  for (const r of rows2) {
    const d = r.domain || "unknown";
    const j = r.jurisdiction || "unknown";
    byDomain[d] = (byDomain[d] || 0) + Number(r.cnt);
    byJurisdiction[j] = (byJurisdiction[j] || 0) + Number(r.cnt);
    totalDatasets += Number(r.cnt);
    enabledDatasets += Number(r.enabled);
    totalRecords += Number(r.total) || 0;
  }
  return { totalDatasets, enabledDatasets, totalRecords, byDomain, byJurisdiction };
}
async function extractSignalsFromComplaints(jurisdiction, limit = 50) {
  const whereClause = jurisdiction ? `WHERE jurisdiction = '${jurisdiction.replace(/'/g, "''")}'` : "";
  const [companySignals] = await db.execute(sql14.raw(
    `SELECT company_name, claim_type, jurisdiction, COUNT(*) as cnt,
            SUM(CASE WHEN consumer_disputed = 1 THEN 1 ELSE 0 END) as disputed
     FROM consumer_complaints ${whereClause}
     GROUP BY company_name, claim_type, jurisdiction
     HAVING cnt >= 3
     ORDER BY cnt DESC
     LIMIT ${limit}`
  ));
  return companySignals.map((r) => {
    const cnt = Number(r.cnt);
    const disputed = Number(r.disputed);
    const severity = cnt >= 20 ? "critical" : cnt >= 10 ? "high" : cnt >= 5 ? "medium" : "low";
    return {
      signalType: "complaint_cluster",
      source: "consumer_complaints",
      entity: r.company_name,
      jurisdiction: r.jurisdiction,
      severity,
      description: `${cnt} complaints against ${r.company_name} (${disputed} disputed) for ${r.claim_type}`,
      dataPoints: cnt,
      claimType: r.claim_type || "consumer_protection"
    };
  });
}
async function extractSignalsFromEnforcement(jurisdiction, limit = 50) {
  const whereClause = jurisdiction ? `WHERE jurisdiction = '${jurisdiction.replace(/'/g, "''")}'` : "";
  const [enfSignals] = await db.execute(sql14.raw(
    `SELECT respondent_name, violation_type, agency_name, jurisdiction, 
            COUNT(*) as cnt, SUM(penalty_amount) as total_penalty
     FROM enforcement_records ${whereClause}
     GROUP BY respondent_name, violation_type, agency_name, jurisdiction
     HAVING cnt >= 2
     ORDER BY cnt DESC
     LIMIT ${limit}`
  ));
  return enfSignals.map((r) => {
    const cnt = Number(r.cnt);
    const penalty = Number(r.total_penalty) || 0;
    const severity = cnt >= 5 ? "critical" : cnt >= 3 ? "high" : "medium";
    return {
      signalType: "enforcement_cluster",
      source: "enforcement_records",
      entity: r.respondent_name,
      jurisdiction: r.jurisdiction,
      severity,
      description: `${cnt} enforcement actions against ${r.respondent_name} by ${r.agency_name} ($${penalty.toLocaleString()} in penalties)`,
      dataPoints: cnt,
      claimType: r.violation_type?.toLowerCase().replace(/ /g, "_") || "enforcement"
    };
  });
}
async function detectRepeatOffenders(minOccurrences = 3, limit = 30) {
  const [patterns3] = await db.execute(sql14.raw(
    `SELECT entity, jurisdiction, domain, SUM(cnt) as total, GROUP_CONCAT(source) as sources
     FROM (
       SELECT company_name as entity, jurisdiction, claim_type as domain, COUNT(*) as cnt, 'complaints' as source
       FROM consumer_complaints GROUP BY company_name, jurisdiction, claim_type
       UNION ALL
       SELECT respondent_name as entity, jurisdiction, violation_type as domain, COUNT(*) as cnt, 'enforcement' as source
       FROM enforcement_records GROUP BY respondent_name, jurisdiction, violation_type
     ) combined
     GROUP BY entity, jurisdiction, domain
     HAVING total >= ${minOccurrences}
     ORDER BY total DESC
     LIMIT ${limit}`
  ));
  return patterns3.map((r) => ({
    patternType: "repeat_offender",
    entity: r.entity,
    jurisdiction: r.jurisdiction,
    occurrences: Number(r.total),
    domain: r.domain || "unknown",
    description: `${r.entity} has ${r.total} combined complaints/enforcement actions across ${r.sources}`
  }));
}
async function detectRegulatoryGaps(limit = 20) {
  const [gaps] = await db.execute(sql14.raw(
    `SELECT c.jurisdiction, c.claim_type as domain, c.complaint_count, COALESCE(e.enforcement_count, 0) as enforcement_count,
            c.complaint_count - COALESCE(e.enforcement_count, 0) as gap
     FROM (
       SELECT jurisdiction, claim_type, COUNT(*) as complaint_count
       FROM consumer_complaints GROUP BY jurisdiction, claim_type
     ) c
     LEFT JOIN (
       SELECT jurisdiction, claim_type, COUNT(*) as enforcement_count
       FROM enforcement_records GROUP BY jurisdiction, claim_type
     ) e ON c.jurisdiction = e.jurisdiction AND c.claim_type = e.claim_type
     WHERE c.complaint_count > 5
     ORDER BY gap DESC
     LIMIT ${limit}`
  ));
  return gaps.map((r) => ({
    patternType: "regulatory_gap",
    entity: `${r.jurisdiction} - ${r.domain}`,
    jurisdiction: r.jurisdiction,
    occurrences: Number(r.gap),
    domain: r.domain || "unknown",
    description: `${r.complaint_count} complaints vs ${r.enforcement_count} enforcement actions in ${r.jurisdiction} for ${r.domain} \u2014 potential enforcement gap`
  }));
}
async function analyzeComplaintTrends(jurisdiction) {
  const whereClause = jurisdiction ? `WHERE jurisdiction = '${jurisdiction.replace(/'/g, "''")}'` : "";
  const [trends] = await db.execute(sql14.raw(
    `SELECT jurisdiction, claim_type as domain,
            SUM(CASE WHEN date_received >= DATE_SUB(CURDATE(), INTERVAL 6 MONTH) THEN 1 ELSE 0 END) as recent,
            SUM(CASE WHEN date_received < DATE_SUB(CURDATE(), INTERVAL 6 MONTH) THEN 1 ELSE 0 END) as older,
            COUNT(*) as total
     FROM consumer_complaints ${whereClause}
     GROUP BY jurisdiction, claim_type
     HAVING total >= 5
     ORDER BY total DESC`
  ));
  return trends.map((r) => {
    const recent = Number(r.recent);
    const older = Number(r.older) || 1;
    const changePercent = (recent - older) / older * 100;
    return {
      metric: "complaint_volume",
      jurisdiction: r.jurisdiction,
      domain: r.domain || "unknown",
      currentValue: recent,
      previousValue: older,
      changePercent: Math.round(changePercent * 10) / 10,
      direction: changePercent > 10 ? "increasing" : changePercent < -10 ? "decreasing" : "stable",
      period: "last_6_months_vs_prior"
    };
  });
}
async function analyzeEnforcementTrends(jurisdiction) {
  const whereClause = jurisdiction ? `WHERE jurisdiction = '${jurisdiction.replace(/'/g, "''")}'` : "";
  const [trends] = await db.execute(sql14.raw(
    `SELECT jurisdiction, violation_type as domain, agency_name,
            SUM(CASE WHEN action_date >= DATE_SUB(CURDATE(), INTERVAL 6 MONTH) THEN 1 ELSE 0 END) as recent,
            SUM(CASE WHEN action_date < DATE_SUB(CURDATE(), INTERVAL 6 MONTH) THEN 1 ELSE 0 END) as older,
            COUNT(*) as total,
            SUM(penalty_amount) as total_penalty
     FROM enforcement_records ${whereClause}
     GROUP BY jurisdiction, violation_type, agency_name
     HAVING total >= 3
     ORDER BY total DESC`
  ));
  return trends.map((r) => {
    const recent = Number(r.recent);
    const older = Number(r.older) || 1;
    const changePercent = (recent - older) / older * 100;
    return {
      metric: "enforcement_frequency",
      jurisdiction: r.jurisdiction,
      domain: r.domain || "unknown",
      currentValue: recent,
      previousValue: older,
      changePercent: Math.round(changePercent * 10) / 10,
      direction: changePercent > 10 ? "increasing" : changePercent < -10 ? "decreasing" : "stable",
      period: "last_6_months_vs_prior"
    };
  });
}
async function generateInterventionTargets(jurisdiction, limit = 20) {
  const whereClause = jurisdiction ? `AND jurisdiction = '${jurisdiction.replace(/'/g, "''")}'` : "";
  const [targets] = await db.execute(sql14.raw(
    `SELECT entity, jurisdiction, complaints, enforcements, penalties,
            complaints + enforcements as total
     FROM (
       SELECT company_name as entity, jurisdiction, COUNT(*) as complaints, 0 as enforcements, 0 as penalties
       FROM consumer_complaints WHERE 1=1 ${whereClause}
       GROUP BY company_name, jurisdiction
       UNION ALL
       SELECT respondent_name as entity, jurisdiction, 0 as complaints, COUNT(*) as enforcements, SUM(penalty_amount) as penalties
       FROM enforcement_records WHERE 1=1 ${whereClause}
       GROUP BY respondent_name, jurisdiction
     ) combined
     GROUP BY entity, jurisdiction
     ORDER BY total DESC
     LIMIT ${limit}`
  ));
  return targets.map((r) => {
    const complaints = Number(r.complaints);
    const enforcements = Number(r.enforcements);
    const penalties = Number(r.penalties) || 0;
    const total = complaints + enforcements;
    const priority = total >= 10 ? "critical" : total >= 5 ? "high" : total >= 3 ? "medium" : "low";
    const recommendedAction = enforcements > 0 ? "Monitor ongoing enforcement; consider advocacy escalation" : complaints >= 5 ? "File formal complaint with regulatory agency" : "Document pattern; prepare for potential escalation";
    return {
      entity: r.entity,
      jurisdiction: r.jurisdiction,
      complaint_count: complaints,
      enforcement_count: enforcements,
      totalPenalties: penalties,
      recommendedAction,
      priority
    };
  });
}
async function getPolicyChangeProposals(jurisdiction, status) {
  let where = "WHERE 1=1";
  if (jurisdiction) where += ` AND jurisdiction = '${jurisdiction.replace(/'/g, "''")}'`;
  if (status) where += ` AND status = '${status.replace(/'/g, "''")}'`;
  const [rows2] = await db.execute(sql14.raw(
    `SELECT change_id, proposal_title, reform_type, jurisdiction, harm_domain,
            status, priority_score, urgency_level, evidence_strength, proposal_summary
     FROM policy_change_registry ${where}
     ORDER BY priority_score DESC`
  ));
  return rows2.map((r) => ({
    changeId: r.change_id,
    title: r.proposal_title,
    reformType: r.reform_type,
    jurisdiction: r.jurisdiction,
    domain: r.harm_domain,
    status: r.status,
    priorityScore: Number(r.priority_score),
    urgencyLevel: r.urgency_level,
    evidenceStrength: r.evidence_strength,
    summary: r.proposal_summary
  }));
}
async function analyzeCampaignFinance(policyDomain, limit = 20) {
  let where = "WHERE 1=1";
  if (policyDomain) where += ` AND policy_domain = '${policyDomain.replace(/'/g, "''")}'`;
  const [rows2] = await db.execute(sql14.raw(
    `SELECT candidate_name, party, office, jurisdiction, policy_domain,
            SUM(contribution_amount) as total, COUNT(*) as cnt
     FROM campaign_finance_records ${where}
     GROUP BY candidate_name, party, office, jurisdiction, policy_domain
     ORDER BY total DESC
     LIMIT ${limit}`
  ));
  return rows2.map((r) => {
    const total = Number(r.total) || 0;
    const cnt = Number(r.cnt);
    const alignmentScore = Math.min(100, Math.round(total / 1e4 * 50 + cnt / 5 * 50));
    return {
      candidateName: r.candidate_name,
      party: r.party,
      office: r.office,
      jurisdiction: r.jurisdiction,
      totalContributions: total,
      contributorCount: cnt,
      policyDomain: r.policy_domain,
      alignmentScore
    };
  });
}
async function getIngestionJobs() {
  const [rows2] = await db.execute(sql14.raw(
    `SELECT stream_id_dsr as dataset_id, update_freq_dsr as update_frequency, cron_expression_dsr as cron_expression, enabled_dsr as enabled
     FROM data_stream_registry ORDER BY stream_name_dsr`
  ));
  return rows2.map((r) => ({
    dataset_id: r.dataset_id,
    frequency: r.update_frequency,
    cron_expression: r.cron_expression,
    enabled: Boolean(r.enabled)
  }));
}
async function updateIngestionJob(dataset_id, updates) {
  const setClauses = [];
  if (updates.enabled !== void 0) setClauses.push(`enabled_dsr = ${updates.enabled ? 1 : 0}`);
  if (updates.cron_expression) setClauses.push(`cron_expression_dsr = '${updates.cron_expression.replace(/'/g, "''")}'`);
  if (updates.frequency) setClauses.push(`update_freq_dsr = '${updates.frequency.replace(/'/g, "''")}'`);
  if (!setClauses.length) return false;
  setClauses.push(`updated_at_dsr = ${Date.now()}`);
  ;
  await db.execute(sql14.raw(
    `UPDATE data_stream_registry SET ${setClauses.join(", ")} WHERE stream_id_dsr = '${dataset_id.replace(/'/g, "''")}'`
  ));
  return true;
}
async function getCrossDatasetIntelligence() {
  const [signals, enfSignals, patterns3, gaps, trends, enfTrends, proposals, targets] = await Promise.all([
    extractSignalsFromComplaints(void 0, 10),
    extractSignalsFromEnforcement(void 0, 10),
    detectRepeatOffenders(3, 10),
    detectRegulatoryGaps(5),
    analyzeComplaintTrends(),
    analyzeEnforcementTrends(),
    getPolicyChangeProposals(),
    generateInterventionTargets(void 0, 10)
  ]);
  return {
    signals: [...signals, ...enfSignals].slice(0, 15),
    patterns: [...patterns3, ...gaps].slice(0, 10),
    trends: [...trends, ...enfTrends].slice(0, 10),
    policyProposals: proposals.length,
    interventionTargets: targets.length
  };
}

