init_interpretation_service();

// server/services/dispatcher.ts
async function dispatcher(_input) {
  return null;
}

// server/lib/constitutional-enforce.ts
import { TRPCError as TRPCError6 } from "@trpc/server";
async function runRead(caseId2) {
  try {
    const interpretation = await getCaseInterpretation(Number(caseId2));
    if (!interpretation) {
      throw new TRPCError6({
        code: "PRECONDITION_FAILED",
        message: "BLOCKED: No interpretation available for case"
      });
    }
    if (interpretation.status !== "ok") {
      throw new TRPCError6({
        code: "PRECONDITION_FAILED",
        message: `BLOCKED: Interpretation status is ${interpretation.status}`
      });
    }
    return interpretation;
  } catch (error) {
    if (error instanceof TRPCError6) throw error;
    throw new TRPCError6({
      code: "INTERNAL_SERVER_ERROR",
      message: "BLOCKED: Failed to retrieve interpretation"
    });
  }
}
async function runAction(caseId2, actionType, input) {
  try {
    const interpretation = await getCaseInterpretation(Number(caseId2));
    if (!interpretation) {
      throw new TRPCError6({
        code: "PRECONDITION_FAILED",
        message: "BLOCKED: No interpretation available for action"
      });
    }
    if (interpretation.status !== "ok") {
      throw new TRPCError6({
        code: "PRECONDITION_FAILED",
        message: `BLOCKED: Interpretation status is ${interpretation.status}`
      });
    }
    return await dispatcher.dispatch({
      type: actionType,
      caseId: Number(caseId2),
      interpretation,
      input
    });
  } catch (error) {
    if (error instanceof TRPCError6) throw error;
    throw new TRPCError6({
      code: "INTERNAL_SERVER_ERROR",
      message: "BLOCKED: Failed to dispatch action"
    });
  }
}

