// server/routers/governance.ts
init_db();
import { z as z11 } from "zod";
import { sql as sql21 } from "drizzle-orm";
var governanceRouter = router({
  /**
   * Create a governance event (audit trail entry)
   * Every override must write a governance_events record
   */
  createGovernanceEvent: adminProcedure.input(
    z11.object({
      caseId: z11.string().optional(),
      signalId: z11.string().optional(),
      actionId: z11.string().optional(),
      stage: z11.enum([
        "lens_activation",
        "action_queue",
        "action_execution",
        "action_outcome",
        "feedback_generation"
      ]),
      eventType: z11.string(),
      actorType: z11.enum(["admin", "system", "tsunam", "reviewer"]),
      actorId: z11.string(),
      reason: z11.string(),
      beforeState: z11.record(z11.string(), z11.any()).optional(),
      afterState: z11.record(z11.string(), z11.any()).optional()
    })
  ).mutation(async ({ input }) => {
    const timestamp3 = Date.now();
    const eventId = `gov_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    await db.execute(
      sql21`INSERT INTO governance_events (governance_event_id, case_id, signal_id, action_id, stage, event_type, actor_type, actor_id, reason, before_state, after_state, created_at)
        VALUES (${eventId}, ${input.caseId || null}, ${input.signalId || null}, ${input.actionId || null}, 
        ${input.stage}, ${input.eventType}, ${input.actorType}, ${input.actorId}, ${input.reason},
        ${input.beforeState ? JSON.stringify(input.beforeState) : null},
        ${input.afterState ? JSON.stringify(input.afterState) : null},
        ${timestamp3})`
    );
    return { eventId, created_at: timestamp3 };
  }),
  /**
   * Pause an action (stops execution without deleting)
   */
  pauseAction: adminProcedure.input(
    z11.object({
      actionId: z11.string(),
      reason: z11.string(),
      actorId: z11.string()
    })
  ).mutation(async ({ input }) => {
    const timestamp3 = Date.now();
    const action = await db.execute(
      sql21`SELECT * FROM action_queue WHERE action_id = ${input.actionId} LIMIT 1`
    );
    if (!action || action.length === 0) {
      throw new Error(`Action ${input.actionId} not found`);
    }
    const beforeState = action[0];
    const controlId = `ctrl_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    await db.execute(
      sql21`INSERT INTO governance_controls (control_id, target_type, target_id, control_type, control_status, reason, actor_id, created_at, updated_at)
        VALUES (${controlId}, 'action', ${input.actionId}, 'pause', 'active', ${input.reason}, ${input.actorId}, ${timestamp3}, ${timestamp3})`
    );
    await db.execute(
      sql21`INSERT INTO governance_events (governance_event_id, action_id, stage, event_type, actor_type, actor_id, reason, before_state, after_state, created_at)
        VALUES (CONCAT('gov_', UUID()), ${input.actionId}, 'action_execution', 'action_paused', 'admin', ${input.actorId}, ${input.reason},
        JSON_OBJECT('status', '${beforeState.status}'),
        JSON_OBJECT('status', 'paused'),
        ${timestamp3})`
    );
    return { controlId, action_id: input.actionId, status: "paused" };
  }),
  /**
   * Resume a paused action
   */
  resumeAction: adminProcedure.input(
    z11.object({
      actionId: z11.string(),
      reason: z11.string(),
      actorId: z11.string()
    })
  ).mutation(async ({ input }) => {
    const timestamp3 = Date.now();
    await db.execute(
      sql21`UPDATE governance_controls 
        SET control_status = 'inactive', updated_at = ${timestamp3}
        WHERE target_id = ${input.actionId} AND control_type = 'pause' AND control_status = 'active'`
    );
    await db.execute(
      sql21`INSERT INTO governance_events (governance_event_id, action_id, stage, event_type, actor_type, actor_id, reason, created_at)
        VALUES (CONCAT('gov_', UUID()), ${input.actionId}, 'action_execution', 'action_resumed', 'admin', ${input.actorId}, ${input.reason}, ${timestamp3})`
    );
    return { action_id: input.actionId, status: "resumed" };
  }),
  /**
   * Force override a lens state
   */
  overrideLensState: adminProcedure.input(
    z11.object({
      caseId: z11.string(),
      lens: z11.enum(["user", "professional", "systemic", "advocate", "admin"]),
      forceActive: z11.boolean(),
      reason: z11.string(),
      actorId: z11.string()
    })
  ).mutation(async ({ input }) => {
    const timestamp3 = Date.now();
    await db.execute(
      sql21`INSERT INTO governance_events (governance_event_id, case_id, stage, event_type, actor_type, actor_id, reason, before_state, after_state, created_at)
        VALUES (CONCAT('gov_', UUID()), ${input.caseId}, 'lens_activation', 'lens_override', 'admin', ${input.actorId}, ${input.reason},
        JSON_OBJECT('lens', ${input.lens}, 'active', !${input.forceActive}),
        JSON_OBJECT('lens', ${input.lens}, 'active', ${input.forceActive}),
        ${timestamp3})`
    );
    return {
      case_id: input.caseId,
      lens: input.lens,
      force_active: input.forceActive,
      timestamp: timestamp3
    };
  }),
  /**
   * Mark action outcome as disputed
   */
  disputeOutcome: adminProcedure.input(
    z11.object({
      actionId: z11.string(),
      reason: z11.string(),
      actorId: z11.string()
    })
  ).mutation(async ({ input }) => {
    const timestamp3 = Date.now();
    await db.execute(
      sql21`INSERT INTO governance_events (governance_event_id, action_id, stage, event_type, actor_type, actor_id, reason, created_at)
        VALUES (CONCAT('gov_', UUID()), ${input.actionId}, 'action_outcome', 'outcome_disputed', 'admin', ${input.actorId}, ${input.reason}, ${timestamp3})`
    );
    return { action_id: input.actionId, status: "disputed" };
  }),
  /**
   * Get governance events for a case
   */
  getGovernanceEvents: protectedProcedure.input(z11.object({ caseId: z11.string() })).query(async ({ input }) => {
    const events2 = await db.execute(
      sql21`SELECT * FROM governance_events 
        WHERE case_id = ${input.caseId}
        ORDER BY created_at DESC
        LIMIT 100`
    );
    return events2 || [];
  }),
  /**
   * Get active governance controls
   */
  getActiveControls: protectedProcedure.query(async () => {
    const controls = await db.execute(
      sql21`SELECT * FROM governance_controls 
      WHERE control_status = 'active'
      ORDER BY created_at DESC`
    );
    return controls || [];
  }),
  /**
   * Get governance audit log (all events)
   */
  getGovernanceAuditLog: adminProcedure.input(
    z11.object({
      limit: z11.number().default(100),
      offset: z11.number().default(0)
    })
  ).query(async ({ input }) => {
    const events2 = await db.execute(
      sql21`SELECT * FROM governance_events 
        ORDER BY created_at DESC
        LIMIT ${input.limit} OFFSET ${input.offset}`
    );
    return events2 || [];
  })
});

