// server/routers/sunam.ts
init_db();
import { z as z12 } from "zod";
var sunamRouter = router({
  /**
   * Enrich a proto-form through Sunam gate with explicit transaction
   */
  enrichForm: publicProcedure.input(z12.object({
    protoFormId: z12.string()
  })).mutation(async ({ input }) => {
    const client = await getPool().connect();
    try {
      await client.query("BEGIN");
      const { rows: protoFormRows } = await client.query(
        `SELECT * FROM forms_registry_staging WHERE id = $1`,
        [input.protoFormId]
      );
      const protoForm = protoFormRows[0];
      if (!protoForm) {
        throw new Error("Proto-form not found");
      }
      const enriched = {
        ...protoForm,
        enrichment_status: "enriched",
        enriched_at: Date.now()
      };
      const { rows: result } = await client.query(
        `INSERT INTO detected_signals (
            signal_type, title, description, severity, confidence, 
            domain, raw_context, created_at
          ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8) RETURNING id`,
        [
          "FORM_DETECTION",
          enriched.form_name || "Form",
          JSON.stringify(enriched),
          "medium",
          enriched.confidence_score || 0.5,
          enriched.primary_domain || "general",
          enriched.raw_context || "",
          Date.now()
        ]
      );
      await client.query("COMMIT");
      return {
        success: true,
        signal_id: result[0]?.id,
        proto_form_id: input.protoFormId
      };
    } catch (error) {
      try {
        await client.query("ROLLBACK");
      } catch (e) {
        console.error("[Sunam] Rollback error:", e);
      }
      console.error("[Sunam] Enrichment failed:", error);
      throw error;
    } finally {
      client.release();
    }
  }),
  /**
   * Get enrichment status for a form
   */
  getStatus: publicProcedure.input(z12.object({
    protoFormId: z12.string()
  })).query(async ({ input }) => {
    const { rows: rows2 } = await getPool().query(
      `SELECT enrichment_status, enriched_at FROM forms_registry_staging WHERE id = $1`,
      [input.protoFormId]
    );
    return rows2[0] || { status: "not_found" };
  }),
  /**
   * List all enriched signals
   */
  listSignals: publicProcedure.query(async () => {
    const { rows: rows2 } = await getPool().query(
      `SELECT id, signal_type, title, severity, confidence, created_at 
       FROM detected_signals 
       ORDER BY created_at DESC 
       LIMIT 100`
    );
    return rows2 || [];
  })
});

// server/routers/analyze.ts
init_db();
import { z as z13 } from "zod";
var analyzeRouter = router({
  /**
   * 1. CLAIM ELEMENTS - Extract and analyze claim structure
   */
  getClaimElements: publicProcedure.input(z13.object({ caseId: z13.number() })).query(async ({ input }) => {
    const { rows: rows2 } = await getPool().query(
      `SELECT id, claim_type, element_name, element_value, evidence_id, created_at 
         FROM claims WHERE case_id = $1 ORDER BY created_at DESC`,
      [input.caseId]
    );
    return rows2 || [];
  }),
  /**
   * 2. PROOF FRAMEWORKS - Legal proof requirements
   */
  getProofFrameworks: publicProcedure.input(z13.object({ caseId: z13.number() })).query(async ({ input }) => {
    const { rows: rows2 } = await getPool().query(
      `SELECT wf.id, wf.workflow_name, wf.proof_standard, wf.required_elements, wf.evidence_threshold
         FROM workflows wf
         JOIN cases c ON c.domain = wf.domain
         WHERE c.id = $1 LIMIT 10`,
      [input.caseId]
    );
    return rows2 || [];
  }),
  /**
   * 3. CONTRADICTION SCORING - Detect contradictions in evidence
   */
  getContradictionScores: publicProcedure.input(z13.object({ caseId: z13.number() })).query(async ({ input }) => {
    const { rows: rows2 } = await getPool().query(
      `SELECT id, finding_id, contradiction_type, severity, evidence_ids, score, created_at
         FROM findings WHERE case_id = $1 AND finding_type = 'contradiction' ORDER BY score DESC`,
      [input.caseId]
    );
    return rows2 || [];
  }),
  /**
   * 4. LITIGATION BARRIERS - Identify legal obstacles
   */
  getLitigationBarriers: publicProcedure.input(z13.object({ caseId: z13.number() })).query(async ({ input }) => {
    const { rows: rows2 } = await getPool().query(
      `SELECT ab.id, ab.barrier_name, ab.barrier_type, ab.legal_basis, ab.mitigation_strategy, ab.severity
         FROM accountability_paths ap
         JOIN (SELECT id, barrier_name, barrier_type, legal_basis, mitigation_strategy, severity FROM accountability_legal_hooks) ab 
         ON ap.id = ab.id
         WHERE ap.case_id = $1 ORDER BY ab.severity DESC`,
      [input.caseId]
    );
    return rows2 || [];
  }),
  /**
   * 5. DOCTRINE GRAPH - Map legal doctrine connections
   */
  getDoctrineGraph: publicProcedure.input(z13.object({ caseId: z13.number() })).query(async ({ input }) => {
    const { rows: rows2 } = await getPool().query(
      `SELECT ssl.id, ssl.signal_id, ssl.statute_id, ssl.connection_type, ssl.relevance_score
         FROM signal_statute_links ssl
         JOIN signal_flags sf ON ssl.signal_id = sf.id
         WHERE sf.case_id = $1 ORDER BY ssl.relevance_score DESC`,
      [input.caseId]
    );
    return rows2 || [];
  }),
  /**
   * 6. CLAIM DENIAL ANALYSIS - Analyze denial patterns
   */
  getClaimDenialAnalysis: publicProcedure.input(z13.object({ caseId: z13.number() })).query(async ({ input }) => {
    const { rows: rows2 } = await getPool().query(
      `SELECT id, denial_reason, denial_category, evidence_supporting, evidence_contradicting, pattern_match, created_at
         FROM findings WHERE case_id = $1 AND finding_type = 'denial_analysis' ORDER BY created_at DESC`,
      [input.caseId]
    );
    return rows2 || [];
  }),
  /**
   * 7. PROVENANCE DRILL-DOWN - Trace evidence origin
   */
  getProvenanceDrillDown: publicProcedure.input(z13.object({ caseId: z13.number() })).query(async ({ input }) => {
    const { rows: rows2 } = await getPool().query(
      `SELECT d.id, d.filename, d.source, d.upload_date, d.document_type, 
                COUNT(e.id) as evidence_count, COUNT(f.id) as finding_count
         FROM documents d
         LEFT JOIN evidence e ON d.id = e.document_id
         LEFT JOIN findings f ON e.id = f.evidence_id
         WHERE d.case_id = $1 GROUP BY d.id ORDER BY d.upload_date DESC`,
      [input.caseId]
    );
    return rows2 || [];
  }),
  /**
   * 8. SIGNAL REGISTRY - Master signal catalog
   */
  getSignalRegistry: publicProcedure.query(async () => {
    const { rows: rows2 } = await getPool().query(
      `SELECT id, signal_type, domain, trigger_patterns, severity, explanation, created_at
       FROM signal_flags GROUP BY signal_type ORDER BY created_at DESC LIMIT 100`
    );
    return rows2 || [];
  }),
  /**
   * Get all analysis data for a case (summary)
   */
  getCaseSummary: publicProcedure.input(z13.object({ caseId: z13.number() })).query(async ({ input }) => {
    const { rows: claimCount } = await getPool().query(
      `SELECT COUNT(*) as count FROM claims WHERE case_id = $1`,
      [input.caseId]
    );
    const { rows: finding_count } = await getPool().query(
      `SELECT COUNT(*) as count FROM findings WHERE case_id = $1`,
      [input.caseId]
    );
    const { rows: signalCount } = await getPool().query(
      `SELECT COUNT(*) as count FROM signal_flags WHERE case_id = $1`,
      [input.caseId]
    );
    const { rows: documentCount } = await getPool().query(
      `SELECT COUNT(*) as count FROM documents WHERE case_id = $1`,
      [input.caseId]
    );
    return {
      claim_elements: claimCount[0]?.count || 0,
      findings: finding_count[0]?.count || 0,
      signals: signalCount[0]?.count || 0,
      documents: documentCount[0]?.count || 0
    };
  })
});

// server/routers/admin-maintenance.ts
init_db();
import { sql as sql22 } from "drizzle-orm";
var adminMaintenanceRouter = router({
  /**
   * Backfill confidence scores for signals with NULL or 0 values.
   * This is a one-time operation that permanently updates the database.
   */
  backfillConfidenceScores: protectedProcedure.query(async ({ ctx }) => {
    if (ctx.user?.role !== "admin") {
      throw new Error("Admin access required");
    }
    try {
      await db.execute(sql22.raw(`
          UPDATE detected_signals
          SET confidence_score = CASE
            WHEN severity_level = 'critical' THEN 75
            WHEN severity_level = 'high' THEN 65
            WHEN severity_level = 'medium' THEN 55
            WHEN severity_level = 'low' THEN 45
            ELSE 50
          END +
          CASE
            WHEN escalation_status = 'escalated' THEN 20
            WHEN escalation_status = 'pending' THEN 0
            ELSE 0
          END +
          CASE
            WHEN sunam_status = 'approved' THEN 15
            WHEN sunam_status = 'pending' THEN 0
            WHEN sunam_status = 'rejected' THEN -30
            ELSE 0
          END
          WHERE confidence_score IS NULL OR confidence_score = 0
        `));
      await db.execute(sql22.raw(`UPDATE detected_signals SET confidence_score = 100 WHERE confidence_score > 100`));
      await db.execute(sql22.raw(`UPDATE detected_signals SET confidence_score = 0 WHERE confidence_score < 0`));
      const stats = await db.execute(sql22.raw(`
          SELECT 
            COUNT(*) as total,
            COUNT(CASE WHEN confidence_score >= 85 THEN 1 END) as high,
            COUNT(CASE WHEN confidence_score >= 70 AND confidence_score < 85 THEN 1 END) as medium_high,
            COUNT(CASE WHEN confidence_score >= 50 AND confidence_score < 70 THEN 1 END) as medium,
            COUNT(CASE WHEN confidence_score < 50 THEN 1 END) as low,
            ROUND(AVG(confidence_score), 1) as avg_score
          FROM detected_signals
        `));
      const s = stats[0][0];
      return {
        success: true,
        message: "Confidence scores backfilled permanently",
        stats: {
          total: s.total,
          high: s.high,
          medium_high: s.medium_high,
          medium: s.medium,
          low: s.low,
          avg_score: s.avg_score
        }
      };
    } catch (error) {
      console.error("[Backfill] Error:", error);
      throw error;
    }
  }),
  /**
   * Check current confidence score statistics
   */
  checkConfidenceStats: protectedProcedure.query(async ({ ctx }) => {
    if (ctx.user?.role !== "admin") {
      throw new Error("Admin access required");
    }
    const stats = await db.execute(sql22.raw(`
        SELECT 
          COUNT(*) as total,
          COUNT(CASE WHEN confidence_score > 0 THEN 1 END) as with_score,
          COUNT(CASE WHEN confidence_score IS NULL THEN 1 END) as null_scores,
          COUNT(CASE WHEN confidence_score = 0 THEN 1 END) as zero_scores,
          COUNT(CASE WHEN confidence_score >= 85 THEN 1 END) as high,
          COUNT(CASE WHEN confidence_score >= 70 AND confidence_score < 85 THEN 1 END) as medium_high,
          COUNT(CASE WHEN confidence_score >= 50 AND confidence_score < 70 THEN 1 END) as medium,
          COUNT(CASE WHEN confidence_score < 50 THEN 1 END) as low,
          MIN(confidence_score) as min_score,
          MAX(confidence_score) as max_score,
          ROUND(AVG(confidence_score), 1) as avg_score
        FROM detected_signals
      `));
    const s = stats[0][0];
    return {
      total: s.total,
      with_score: s.with_score,
      null_scores: s.null_scores,
      zero_scores: s.zero_scores,
      distribution: {
        high: s.high,
        medium_high: s.medium_high,
        medium: s.medium,
        low: s.low
      },
      range: {
        min: s.min_score,
        max: s.max_score,
        avg: s.avg_score
      }
    };
  })
});

