// server/enforcement-rules.ts
init_db();
import { sql as sql25 } from "drizzle-orm";
async function enforceRegisteredEngine(engineId) {
  const [rows2] = await db.execute(
    sql25`SELECT engine_id_er, enabled_er FROM engine_registry WHERE engine_id_er = ${engineId} LIMIT 1`
  );
  const found = rows2.length > 0;
  const enabled = found && rows2[0].enabled_er === 1;
  if (!found) {
    return { rule: "NO_UNREGISTERED_ENGINE", passed: false, message: `Engine "${engineId}" not found in engine_registry` };
  }
  if (!enabled) {
    return { rule: "NO_UNREGISTERED_ENGINE", passed: false, message: `Engine "${engineId}" is disabled in engine_registry` };
  }
  return { rule: "NO_UNREGISTERED_ENGINE", passed: true, message: `Engine "${engineId}" is registered and enabled` };
}
async function enforceNoOrphanOutput(outputRefs) {
  if (!outputRefs || typeof outputRefs !== "object" || !outputRefs.primary) {
    return { rule: "NO_ORPHAN_OUTPUT", passed: false, message: "output_refs is missing or invalid" };
  }
  const allEntities = [outputRefs.primary, ...outputRefs.artifacts || []];
  const orphans = [];
  for (const entity of allEntities) {
    try {
      const [rows2] = await db.execute(
        sql25.raw(`SELECT id FROM "${entity.table}" WHERE id = ${entity.id} LIMIT 1`)
      );
      if (rows2.length === 0) {
        orphans.push(`${entity.type}:${entity.id} in ${entity.table}`);
      }
    } catch (e) {
      orphans.push(`${entity.type}:${entity.id} \u2014 table "${entity.table}" error: ${e.message}`);
    }
  }
  if (orphans.length > 0) {
    return { rule: "NO_ORPHAN_OUTPUT", passed: false, message: `Orphan outputs found: ${orphans.join("; ")}`, details: orphans };
  }
  return { rule: "NO_ORPHAN_OUTPUT", passed: true, message: "All output entities resolve to real rows" };
}
async function enforceSnapshotValidation(runId) {
  const [runRows] = await db.execute(
    sql25`SELECT run_id, engine_id, status, output_refs, snapshot_id FROM engine_runs WHERE run_id = ${runId}`
  );
  const runs = runRows;
  if (runs.length === 0) {
    return { rule: "NO_SNAPSHOT_WITHOUT_VALIDATION", passed: false, message: `No engine_run found for run_id: ${runId}` };
  }
  const run = runs[0];
  const errors = [];
  if (run.engine_id) {
    const [engineCheck] = await db.execute(
      sql25`SELECT id FROM engine_registry WHERE engine_id_er = ${run.engine_id} LIMIT 1`
    );
    if (engineCheck.length === 0) {
      errors.push(`Engine "${run.engine_id}" not in engine_registry`);
    }
  } else {
    errors.push("Missing engine_id");
  }
  if (run.status !== "success") {
    errors.push(`Status is "${run.status}", must be "success"`);
  }
  if (!run.output_refs) {
    errors.push("Missing output_refs");
  }
  if (errors.length > 0) {
    return { rule: "NO_SNAPSHOT_WITHOUT_VALIDATION", passed: false, message: errors.join("; "), details: errors };
  }
  return { rule: "NO_SNAPSHOT_WITHOUT_VALIDATION", passed: true, message: "Run passes snapshot validation" };
}
function enforceAlphaExportSnapshot(snapshotId) {
  if (!snapshotId || snapshotId <= 0) {
    return { rule: "NO_ALPHA_EXPORT_WITHOUT_SNAPSHOT", passed: false, message: "Alpha Lake export requires a valid snapshot_id" };
  }
  return { rule: "NO_ALPHA_EXPORT_WITHOUT_SNAPSHOT", passed: true, message: `Snapshot ${snapshotId} provided for Alpha Lake export` };
}
function enforceOutputRefsDeterministic(outputRefs) {
  if (!outputRefs || typeof outputRefs !== "object") {
    return { rule: "NO_UNDETERMINISTIC_REFS", passed: false, message: "output_refs is missing or not an object" };
  }
  if (Array.isArray(outputRefs)) {
    return { rule: "NO_UNDETERMINISTIC_REFS", passed: false, message: "output_refs is a legacy string array \u2014 not deterministic" };
  }
  if (!outputRefs.meta) {
    return { rule: "NO_UNDETERMINISTIC_REFS", passed: false, message: "output_refs.meta is missing" };
  }
  if (outputRefs.meta.deterministic !== true) {
    return { rule: "NO_UNDETERMINISTIC_REFS", passed: false, message: `output_refs.meta.deterministic is ${outputRefs.meta.deterministic}, must be true` };
  }
  if (!Array.isArray(outputRefs.meta.tables) || outputRefs.meta.tables.length === 0) {
    return { rule: "NO_UNDETERMINISTIC_REFS", passed: false, message: "output_refs.meta.tables is missing or empty" };
  }
  if (!Array.isArray(outputRefs.meta.fields) || outputRefs.meta.fields.length === 0) {
    return { rule: "NO_UNDETERMINISTIC_REFS", passed: false, message: "output_refs.meta.fields is missing or empty" };
  }
  return { rule: "NO_UNDETERMINISTIC_REFS", passed: true, message: "output_refs is deterministic with tables and fields" };
}
async function enforceAllRules(runId) {
  const [runRows] = await db.execute(
    sql25`SELECT run_id, engine_id, status, output_refs, snapshot_id FROM engine_runs WHERE run_id = ${runId}`
  );
  const runs = runRows;
  if (runs.length === 0) {
    return {
      allPassed: false,
      results: [{ rule: "SYSTEM", passed: false, message: `No engine_run found for run_id: ${runId}` }]
    };
  }
  const run = runs[0];
  const outputRefs = typeof run.output_refs === "string" ? JSON.parse(run.output_refs) : run.output_refs;
  const results = [];
  results.push(await enforceRegisteredEngine(run.engine_id));
  if (outputRefs && !Array.isArray(outputRefs)) {
    results.push(await enforceNoOrphanOutput(outputRefs));
  } else {
    results.push({ rule: "NO_ORPHAN_OUTPUT", passed: false, message: "output_refs not in new format \u2014 cannot verify" });
  }
  results.push(await enforceSnapshotValidation(runId));
  results.push(enforceAlphaExportSnapshot(run.snapshot_id));
  results.push(enforceOutputRefsDeterministic(outputRefs));
  return {
    allPassed: results.every((r) => r.passed),
    results
  };
}

// server/routers/conduit-router.ts
var conduitRouter = router({
  // ─── Metadata Health Panel ───
  metadataHealth: protectedProcedure.query(async ({ ctx }) => {
    const [tableRows] = await db.execute(sql26`
      SELECT category, status, COUNT(*) as cnt, SUM(rowCount) as total_rows
      FROM table_registry
      GROUP BY category, status
      ORDER BY category
    `);
    const [fieldStats] = await db.execute(sql26`
      SELECT COUNT(*) as total_fields,
             SUM(CASE WHEN isPrimaryKey = 1 THEN 1 ELSE 0 END) as pk_fields,
             SUM(CASE WHEN isIndexed = 1 THEN 1 ELSE 0 END) as indexed_fields
      FROM field_dictionary
    `);
    const drift = await detectDrift();
    const cutoff = Date.now() - 864e5;
    const [eventCounts] = await db.execute(sql26`
      SELECT event_type, COUNT(*) as cnt
      FROM conduit_events
      WHERE createdAt > ${cutoff}
      GROUP BY event_type
      ORDER BY cnt DESC
    `);
    const [totalTables] = await db.execute(sql26`SELECT COUNT(*) as cnt FROM table_registry`);
    const [total_fields] = await db.execute(sql26`SELECT COUNT(*) as cnt FROM field_dictionary`);
    return {
      tables: {
        total: totalTables[0]?.cnt || 0,
        // @ts-ignore - cast is valid at runtime
        by_category: tableRows
      },
      fields: {
        total: total_fields[0]?.cnt || 0,
        stats: fieldStats[0] || { total_fields: 0, pk_fields: 0, indexed_fields: 0 }
      },
      drift: {
        orphan_fields: drift.orphanFields,
        unknown_tables: drift.unknownTables,
        unknown_table_names: drift.unknownTableNames.slice(0, 20),
        coverage: drift.totalDbTables > 0 ? Math.round(drift.registeredTables / drift.totalDbTables * 100) : 0
      },
      // @ts-ignore - cast is valid at runtime
      events24h: eventCounts
    };
  }),
  scanSchema: protectedProcedure.mutation(async () => {
    return await scanSchema();
  }),
  detectDrift: protectedProcedure.mutation(async () => {
    return await detectDrift();
  }),
  // ─── Pipeline Integrity Panel ───
  pipelineIntegrity: protectedProcedure.query(async ({ ctx }) => {
    const [recentRuns] = await db.execute(sql26`
      SELECT run_id, engine_id, status, 
             CASE 
               WHEN output_refs IS NULL THEN 'missing'
               WHEN JSON_TYPE(output_refs) = 'OBJECT' AND JSON_EXTRACT(output_refs, '$.primary') IS NOT NULL THEN 'deterministic'
               WHEN JSON_TYPE(output_refs) = 'ARRAY' THEN 'legacy'
               ELSE 'unknown'
             END as ref_format,
             CASE WHEN snapshot_id IS NOT NULL THEN 1 ELSE 0 END as has_snapshot,
             startedAt, completedAt
      FROM engine_runs
      ORDER BY startedAt DESC
      LIMIT 50
    `);
    const [success_runs] = await db.execute(sql26`
      SELECT run_id FROM engine_runs WHERE status = 'success' ORDER BY completedAt DESC LIMIT 10
    `);
    const ruleResults = [];
    for (const r of success_runs.slice(0, 5)) {
      const enforcement = await enforceAllRules(r.run_id);
      ruleResults.push({
        run_id: r.run_id,
        allPassed: enforcement.allPassed,
        failedRules: enforcement.results.filter((x) => !x.passed).map((x) => x.rule)
      });
    }
    const backboneCounts = await getBackboneTableCounts();
    const [formatDist] = await db.execute(sql26`
      SELECT 
        COUNT(*) as total,
        SUM(CASE WHEN output_refs IS NULL THEN 1 ELSE 0 END) as no_refs,
        SUM(CASE WHEN JSON_TYPE(output_refs) = 'OBJECT' AND JSON_EXTRACT(output_refs, '$.primary') IS NOT NULL THEN 1 ELSE 0 END) as deterministic,
        SUM(CASE WHEN JSON_TYPE(output_refs) = 'ARRAY' THEN 1 ELSE 0 END) as legacy
      FROM engine_runs
    `);
    return {
      // @ts-ignore - cast is valid at runtime
      recent_runs: recentRuns,
      enforcement: ruleResults,
      backboneCounts,
      format_distribution: formatDist[0] || { total: 0, no_refs: 0, deterministic: 0, legacy: 0 }
    };
  }),
  enforceRules: protectedProcedure.input(z14.object({ runId: z14.string() })).mutation(async ({ input }) => {
    return await enforceAllRules(input.runId);
  }),
  // ─── Export Readiness Panel ───
  exportReadiness: protectedProcedure.query(async ({ ctx }) => {
    const [snapshots2] = await db.execute(sql26`
      SELECT s.id, s.caseId, s.status, s.createdAt,
             COUNT(er.run_id) as bound_runs,
             SUM(CASE WHEN er.status = 'success' THEN 1 ELSE 0 END) as success_runs
      FROM case_snapshots s
      LEFT JOIN engine_runs er ON er.snapshot_id = s.id
      GROUP BY s.id
      ORDER BY s.createdAt DESC
      LIMIT 20
    `);
    const [exports] = await db.execute(sql26`
      SELECT id, snapshot_id, export_type, status, createdAt
      FROM alpha_lake_exports
      ORDER BY createdAt DESC
      LIMIT 20
    `);
    const readySnapshots = [];
    for (const snap of snapshots2.slice(0, 5)) {
      if (snap.bound_runs > 0 && snap.success_runs === snap.bound_runs) {
        readySnapshots.push({
          snapshotId: snap.id,
          caseId: snap.caseId,
          bound_runs: snap.bound_runs,
          ready: true
        });
      }
    }
    const [exportEvents] = await db.execute(sql26`
      SELECT COUNT(*) as cnt FROM conduit_events WHERE event_type = 'ALPHA_EXPORT'
    `);
    return {
      // @ts-ignore - cast is valid at runtime
      snapshots: snapshots2,
      // @ts-ignore - cast is valid at runtime
      exports,
      readySnapshots,
      total_alpha_exports: exportEvents[0]?.cnt || 0
    };
  }),
  generateAlphaExport: protectedProcedure.input(z14.object({ snapshotId: z14.number() })).mutation(async ({ input }) => {
    return await generateOutput(input.snapshotId);
  }),
  // ─── Validate metadata completeness for a run ───
  validateCompleteness: protectedProcedure.input(z14.object({ runId: z14.string() })).mutation(async ({ input }) => {
    return await validateMetadataCompleteness(input.runId);
  })
});

// server/services/integrity-lockdown.ts
init_db();
var CANONICAL_TABLES = [
  // Core legal knowledge
  { table: "legal_statutes", minRows: 1, critical: true },
  { table: "legal_case_law", minRows: 1, critical: true },
  { table: "legal_weak_joints", minRows: 1, critical: true },
  { table: "legal_contradictions", minRows: 1, critical: true },
  { table: "legal_enforcement_records", minRows: 1, critical: true },
  { table: "legal_statute_clauses", minRows: 1, critical: true },
  // Doctrine graph
  { table: "doctrine_registry", minRows: 1, critical: true },
  { table: "doctrine_graph_edges", minRows: 1, critical: true },
  // Enforcement
  { table: "enforcement_penalties", minRows: 1, critical: true },
  { table: "enforcement_viability_rules", minRows: 1, critical: true },
  { table: "agency_authority_map", minRows: 1, critical: true },
  { table: "agency_forms", minRows: 1, critical: true },
  // Signals
  { table: "signal_registry", minRows: 1, critical: true },
  { table: "live_signals", minRows: 1, critical: true },
  { table: "detected_signals", minRows: 0, critical: false },
  // Procedural engine
  { table: "jurisdiction_hierarchy", minRows: 1, critical: true },
  { table: "workflow_master", minRows: 1, critical: true },
  { table: "workflow_steps", minRows: 1, critical: true },
  { table: "evidence_profiles", minRows: 1, critical: true },
  { table: "escalation_routes", minRows: 1, critical: true },
  { table: "deadline_rules", minRows: 1, critical: true },
  { table: "weak_joint_triggers", minRows: 1, critical: true },
  { table: "claim_detection_rules", minRows: 1, critical: true },
  { table: "node_timeline", minRows: 1, critical: true },
  // Barriers & frameworks
  { table: "litigation_barriers", minRows: 1, critical: true },
  { table: "proof_frameworks", minRows: 1, critical: true },
  { table: "claim_elements", minRows: 1, critical: true },
  // Narrative & filing
  { table: "narrative_templates", minRows: 1, critical: true },
  { table: "filing_generator_templates", minRows: 1, critical: true },
  { table: "investigation_guidance", minRows: 1, critical: true },
  // Interagency
  { table: "interagency_referrals", minRows: 1, critical: true },
  // Contradiction templates
  { table: "contradiction_templates", minRows: 1, critical: true },
  // Guidance
  { table: "agency_guidance", minRows: 1, critical: true },
  // Workflow definitions (signal-to-workflow)
  { table: "workflow_definitions", minRows: 1, critical: true },
  // Ingestion
  { table: "data_stream_registry", minRows: 1, critical: true },
  { table: "ingest_runs", minRows: 0, critical: false },
  // Users & cases (operational — can be empty on fresh deploy)
  { table: "users", minRows: 0, critical: false },
  { table: "cases", minRows: 0, critical: false }
];
async function runIntegrityLockdown(throwOnCritical = false) {
  const results = [];
  for (const entry of CANONICAL_TABLES) {
    let exists = false;
    let rowCount = 0;
    let note;
    try {
      const [rows2] = await pool.query(
        `SELECT COUNT(*) AS cnt FROM \`${entry.table}\``
      );
      exists = true;
      rowCount = Number(rows2[0]?.cnt ?? 0);
    } catch (e) {
      exists = false;
      note = e.message?.slice(0, 120);
    }
    const pass = exists && rowCount >= entry.minRows;
    results.push({
      table: entry.table,
      exists,
      rowCount,
      minRows: entry.minRows,
      critical: entry.critical,
      pass,
      note
    });
  }
  const passed = results.filter((r) => r.pass).length;
  const failed = results.filter((r) => !r.pass).length;
  const criticalFailures = results.filter((r) => !r.pass && r.critical).length;
  const healthy = criticalFailures === 0;
  const report = {
    timestamp: Date.now(),
    totalTables: results.length,
    passed,
    failed,
    criticalFailures,
    results,
    healthy
  };
  console.log(`
\u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2557`);
  console.log(`\u2551  LUMINARI INTEGRITY LOCKDOWN \u2014 ${new Date(report.timestamp).toISOString()}  \u2551`);
  console.log(`\u255A\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u255D`);
  console.log(`  Tables checked : ${report.totalTables}`);
  console.log(`  Passed         : ${report.passed}`);
  console.log(`  Failed         : ${report.failed}`);
  console.log(`  Critical fails : ${report.criticalFailures}`);
  console.log(`  Status         : ${healthy ? "\u2705 HEALTHY" : "\u274C DEGRADED"}`);
  if (failed > 0) {
    console.log(`
  Failed tables:`);
    for (const r of results.filter((r2) => !r2.pass)) {
      console.log(`    \u274C ${r.table.padEnd(35)} rows=${r.rowCount} min=${r.minRows} critical=${r.critical}${r.note ? ` [${r.note}]` : ""}`);
    }
  }
  console.log("");
  if (throwOnCritical && criticalFailures > 0) {
    throw new Error(
      `[IntegrityLockdown] ${criticalFailures} critical table(s) failed. System cannot start in this state.`
    );
  }
  return report;
}

// server/routers/business.ts
init_db();
init_schema();
import { z as z15 } from "zod";
import { eq as eq8, and as and6 } from "drizzle-orm";
var businessRouter = router({
  /**
   * Get all business baselines for analytics
   */
  getBaselines: protectedProcedure.query(async () => {
    const baselines = await db.select().from(businessBaselines);
    return baselines;
  }),
  /**
   * Get baseline for a specific entity
   */
  getBaseline: protectedProcedure.input(z15.object({
    entityType: z15.enum(["product", "expense_category"]),
    entityId: z15.string()
  })).query(async ({ input }) => {
    const [baseline] = await db.select().from(businessBaselines).where(
      and6(
        eq8(businessBaselines.entityType, input.entityType),
        eq8(businessBaselines.entityId, input.entityId)
      )
    );
    return baseline || null;
  }),
  /**
   * Create or update a baseline
   */
  upsertBaseline: protectedProcedure.input(z15.object({
    entityType: z15.enum(["product", "expense_category"]),
    entityId: z15.string(),
    avgAmount: z15.string(),
    stddevAmount: z15.string().optional(),
    sampleCount: z15.number()
  })).mutation(async ({ input }) => {
    const now3 = Date.now();
    const result = await db.insert(businessBaselines).values({
      entityType: input.entityType,
      entityId: input.entityId,
      avgAmount: input.avgAmount,
      stddevAmount: input.stddevAmount,
      sampleCount: input.sampleCount,
      lastUpdated: now3
    }).onDuplicateKeyUpdate({
      set: {
        avgAmount: input.avgAmount,
        stddevAmount: input.stddevAmount,
        sampleCount: input.sampleCount,
        lastUpdated: now3
      }
    });
    return { success: true, id: result?.[0]?.insertId ?? result.insertId };
  }),
  /**
   * Get analytics summary
   */
  getAnalyticsSummary: protectedProcedure.query(async () => {
    const baselines = await db.select().from(businessBaselines);
    const productBaselines = baselines.filter((b) => b.entityType === "product");
    const expenseBaselines = baselines.filter((b) => b.entityType === "expense_category");
    return {
      total_baselines: baselines.length,
      product_count: productBaselines.length,
      expense_category_count: expenseBaselines.length,
      last_updated: baselines.length > 0 ? Math.max(...baselines.map((b) => b.lastUpdated || 0)) : null
    };
  })
});

