var _uprCache = null;
var _intakeCache = null;
var _pipelineTypesCache = null;
function loadUPR() {
  if (!_uprCache) {
    const raw = readFileSync3(join3(configDir, "unified_pipeline_registry.json"), "utf-8");
    const data = JSON.parse(raw);
    _uprCache = data.pipelines;
  }
  return _uprCache;
}
function loadIntakeMappings() {
  if (!_intakeCache) {
    const raw = readFileSync3(join3(configDir, "intake_pre_lens_map.json"), "utf-8");
    const data = JSON.parse(raw);
    _intakeCache = data.intake_mappings;
  }
  return _intakeCache;
}
function loadPipelineTypes() {
  if (!_pipelineTypesCache) {
    const raw = readFileSync3(join3(configDir, "pipeline_types.json"), "utf-8");
    _pipelineTypesCache = JSON.parse(raw);
  }
  return _pipelineTypesCache;
}
function getAllCategories() {
  const upr = loadUPR();
  const categories = Object.keys(CATEGORY_CONFIG);
  return categories.map((cat) => {
    const pipelines = upr.filter((p) => p.category === cat);
    const totalSituations = pipelines.reduce((sum, p) => sum + (p.situations?.length || 0), 0);
    const config = CATEGORY_CONFIG[cat];
    return {
      category: cat,
      label: config.label,
      description: config.description,
      icon: config.icon,
      color: config.color,
      pipeline_count: pipelines.length,
      situation_count: totalSituations,
      pipelines: pipelines.map((p) => ({
        pipeline_id: p.pipeline_id,
        description: p.description,
        aliases: p.aliases || [],
        default_lenses: p.default_lenses || [],
        situation_count: p.situations?.length || 0,
        oversight_entities: p.oversight_entities || [],
        escalation_profile: p.escalation_profile
      }))
    };
  });
}
function getCategoryDetail(categoryId) {
  const all = getAllCategories();
  return all.find((c) => c.category === categoryId) || null;
}
function getPipelineDetail(pipelineId) {
  const upr = loadUPR();
  const pipeline = upr.find((p) => p.pipeline_id === pipelineId);
  if (!pipeline) return null;
  const intakeMappings = loadIntakeMappings();
  const pipelineIntake = {};
  for (const situation of pipeline.situations || []) {
    if (intakeMappings[situation]) {
      pipelineIntake[situation] = intakeMappings[situation];
    }
  }
  return {
    ...pipeline,
    intake_mappings: pipelineIntake
  };
}
function getPipelineLabel(pipelineId) {
  const pt = loadPipelineTypes();
  const cats = pt.categories || {};
  for (const catData of Object.values(cats)) {
    for (const p of catData.pipelines || []) {
      if (p.id === pipelineId) return p.label;
    }
  }
  return pipelineId.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

