// server/routers/lighthouse/lineage.ts
var lighthouseLineageRouter = router({
  /** Full lineage trace with optional filters */
  list: publicProcedure.input(
    z19.object({
      signalType: z19.string().optional(),
      decision: z19.enum(["PROMOTE", "STAGE", "HOLD", "REJECT", "ESCALATE_REVIEW"]).optional(),
      limit: z19.number().int().min(1).max(500).default(200)
    })
  ).query(async ({ input }) => {
    const lineage = await getSignalLineage({
      signalType: input.signalType,
      decision: input.decision,
      limit: input.limit
    });
    return { lineage, count: lineage.length };
  }),
  /** Get full lineage for a single signal by signal_id */
  getBySignalId: publicProcedure.input(z19.object({ signalId: z19.string().uuid() })).query(async ({ input }) => {
    const all = await getSignalLineage({ limit: 500 });
    const entry = all.find((l) => l.detected_signal_id === input.signalId) ?? null;
    return { entry };
  }),
  /** Lineage coverage stats */
  coverageStats: publicProcedure.query(async () => {
    const lineage = await getSignalLineage({ limit: 500 });
    let fullChain = 0;
    let patternLinked = 0;
    let trendLinked = 0;
    let promoted = 0;
    for (const l of lineage) {
      if (l.gate_decision === "PROMOTE") promoted++;
      if (l.linked_pattern_id) patternLinked++;
      if (l.linked_trend_id) trendLinked++;
      if (l.linked_pattern_id && l.linked_trend_id) fullChain++;
    }
    return {
      total_signals: lineage.length,
      promoted,
      patternLinked,
      trendLinked,
      fullChain,
      promotion_rate: lineage.length > 0 ? Math.round(promoted / lineage.length * 100) : 0,
      full_chain_rate: promoted > 0 ? Math.round(fullChain / promoted * 100) : 0
    };
  })
});

