// server/routers/docket.ts
import { z as z24 } from "zod";
import { TRPCError as TRPCError10 } from "@trpc/server";

// server/docket-db.ts
init_db();
init_schema();
import { eq as eq17, and as and14, desc as desc6, asc as asc3, sql as sql31, like as like2, or } from "drizzle-orm";
async function listDocketEntries(opts) {
  const conditions = [];
  if (opts?.jurisdiction) conditions.push(eq17(docketEntries.jurisdiction, opts.jurisdiction));
  if (opts?.jurisdictionLevel) conditions.push(eq17(docketEntries.jurisdictionLevel, opts.jurisdictionLevel));
  if (opts?.lawType) conditions.push(eq17(docketEntries.lawType, opts.lawType));
  if (opts?.status) conditions.push(eq17(docketEntries.status, opts.status));
  if (opts?.search) {
    const term = `%${opts.search}%`;
    conditions.push(
      or(
        like2(docketEntries.title, term),
        like2(docketEntries.summary, term),
        like2(docketEntries.jurisdiction, term)
      )
    );
  }
  const where = conditions.length > 0 ? and14(...conditions) : void 0;
  const rows2 = await db.select().from(docketEntries).where(where).orderBy(desc6(docketEntries.updatedAt)).limit(opts?.limit ?? 50).offset(opts?.offset ?? 0);
  return rows2;
}
async function getDocketEntry(id) {
  const [row] = await db.select().from(docketEntries).where(eq17(docketEntries.id, id));
  return row ?? null;
}
async function getDocketEntryBySlug(slug) {
  const [row] = await db.select().from(docketEntries).where(eq17(docketEntries.slug, slug));
  return row ?? null;
}
async function createDocketEntry(data) {
  const [result] = await db.insert(docketEntries).values(data);
  return result.insertId;
}
async function updateDocketEntry(id, data) {
  await db.update(docketEntries).set({ ...data, updatedAt: Date.now() }).where(eq17(docketEntries.id, id));
}
async function listActorsForDocket(docketId) {
  return db.select().from(docketActors).where(eq17(docketActors.docketId, docketId)).orderBy(asc3(docketActors.actorType), asc3(docketActors.actorName));
}
async function createDocketActor(data) {
  const [result] = await db.insert(docketActors).values(data);
  return result.insertId;
}
async function bulkCreateActors(actors) {
  if (actors.length === 0) return;
  await db.insert(docketActors).values(actors);
}
async function deleteActorsForDocket(docketId) {
  await db.delete(docketActors).where(eq17(docketActors.docketId, docketId));
}
async function listImpactsForDocket(docketId) {
  return db.select().from(docketImpacts).where(eq17(docketImpacts.docketId, docketId)).orderBy(asc3(docketImpacts.impactCategory), asc3(docketImpacts.affectedEntity));
}
async function createDocketImpact(data) {
  const [result] = await db.insert(docketImpacts).values(data);
  return result.insertId;
}
async function bulkCreateImpacts(impacts) {
  if (impacts.length === 0) return;
  await db.insert(docketImpacts).values(impacts);
}
async function deleteImpactsForDocket(docketId) {
  await db.delete(docketImpacts).where(eq17(docketImpacts.docketId, docketId));
}
async function listSourcesForDocket(docketId) {
  return db.select().from(docketSources).where(eq17(docketSources.docketId, docketId)).orderBy(asc3(docketSources.sourceType), asc3(docketSources.title));
}
async function createDocketSource(data) {
  const [result] = await db.insert(docketSources).values(data);
  return result.insertId;
}
async function bulkCreateSources(sources) {
  if (sources.length === 0) return;
  await db.insert(docketSources).values(sources);
}
async function deleteSourcesForDocket(docketId) {
  await db.delete(docketSources).where(eq17(docketSources.docketId, docketId));
}
async function getFullDocketAnalysis(docketId) {
  const entry = await getDocketEntry(docketId);
  if (!entry) return null;
  const [actors, impacts, sources] = await Promise.all([
    listActorsForDocket(docketId),
    listImpactsForDocket(docketId),
    listSourcesForDocket(docketId)
  ]);
  return { entry, actors, impacts, sources };
}
async function createDocketSubmission(data) {
  const [result] = await db.insert(docketSubmissions).values(data);
  return result.insertId;
}
async function listDocketSubmissions(opts) {
  const conditions = [];
  if (opts?.userId) conditions.push(eq17(docketSubmissions.userId, opts.userId));
  if (opts?.status) conditions.push(eq17(docketSubmissions.status, opts.status));
  const where = conditions.length > 0 ? and14(...conditions) : void 0;
  return db.select().from(docketSubmissions).where(where).orderBy(desc6(docketSubmissions.createdAt)).limit(opts?.limit ?? 50).offset(opts?.offset ?? 0);
}
async function getDocketSubmission(id) {
  const [row] = await db.select().from(docketSubmissions).where(eq17(docketSubmissions.id, id));
  return row ?? null;
}
async function updateDocketSubmission(id, data) {
  await db.update(docketSubmissions).set({ ...data, updatedAt: Date.now() }).where(eq17(docketSubmissions.id, id));
}
async function searchActorsByName(term) {
  return db.select().from(docketActors).where(like2(docketActors.actorName, `%${term}%`)).orderBy(asc3(docketActors.actorName)).limit(20);
}
async function getDocketStats() {
  const [countResult] = await db.select({ count: sql31`COUNT(*)` }).from(docketEntries);
  const entries = await db.select({
    jurisdiction: docketEntries.jurisdiction,
    jurisdictionLevel: docketEntries.jurisdictionLevel,
    lawType: docketEntries.lawType,
    status: docketEntries.status
  }).from(docketEntries);
  const byLevel = {};
  const byType = {};
  const byJurisdiction = {};
  for (const e of entries) {
    byLevel[e.jurisdictionLevel] = (byLevel[e.jurisdictionLevel] || 0) + 1;
    byType[e.lawType] = (byType[e.lawType] || 0) + 1;
    byJurisdiction[e.jurisdiction] = (byJurisdiction[e.jurisdiction] || 0) + 1;
  }
  return {
    total: countResult.count,
    byLevel,
    byType,
    byJurisdiction
  };
}

// server/routers/docket.ts
init_notification();
var docketEntryInput = z24.object({
  slug: z24.string().min(1).max(256),
  title: z24.string().min(1).max(512),
  shortTitle: z24.string().max(256).optional(),
  jurisdiction: z24.string().min(1).max(128),
  jurisdictionLevel: z24.enum(["federal", "state", "county", "city", "tribal"]),
  lawType: z24.enum(["statute", "ordinance", "regulation", "executive_order", "ballot_measure", "proposed_bill", "constitutional_amendment"]),
  status: z24.enum(["enacted", "proposed", "repealed", "amended", "under_review"]),
  dateIntroduced: z24.string().optional(),
  dateEnacted: z24.string().optional(),
  dateEffective: z24.string().optional(),
  summary: z24.string().optional(),
  keyChanges: z24.array(z24.string()).optional(),
  implementationAgencies: z24.array(z24.string()).optional(),
  adminSteps: z24.array(z24.string()).optional(),
  complianceObligations: z24.array(z24.string()).optional(),
  rolloutTimeline: z24.array(z24.string()).optional(),
  structuralExemptions: z24.array(z24.string()).optional(),
  enforcementGaps: z24.array(z24.string()).optional(),
  reportingGaps: z24.array(z24.string()).optional(),
  delegatedAuthority: z24.array(z24.string()).optional(),
  similarLaws: z24.array(z24.object({ jurisdiction: z24.string(), title: z24.string(), note: z24.string() })).optional(),
  historicalPrecedents: z24.array(z24.object({ title: z24.string(), year: z24.string(), note: z24.string() })).optional(),
  implementationVariations: z24.array(z24.string()).optional(),
  primarySourceUrl: z24.string().optional()
});
var actorInput = z24.object({
  actorName: z24.string().min(1).max(512),
  actorType: z24.enum([
    "sponsor",
    "cosponsor",
    "committee",
    "implementing_agency",
    "regulatory_body",
    "lobbyist_org",
    "advocacy_group",
    "opposition_group",
    "executive_signatory",
    "judicial_body"
  ]),
  role: z24.string().optional(),
  affiliation: z24.string().optional(),
  sourceUrl: z24.string().optional(),
  sourceNote: z24.string().optional()
});
var impactInput = z24.object({
  impactCategory: z24.enum(["population", "industry", "government_agency", "geographic"]),
  affectedEntity: z24.string().min(1).max(512),
  impactDescription: z24.string().optional(),
  scope: z24.string().optional(),
  sourceUrl: z24.string().optional(),
  sourceNote: z24.string().optional()
});
var sourceInput = z24.object({
  sourceType: z24.enum([
    "legislation_text",
    "committee_report",
    "agency_rule",
    "court_decision",
    "federal_register",
    "congressional_record",
    "state_legislature",
    "executive_order",
    "press_release",
    "government_report",
    "other"
  ]),
  title: z24.string().min(1).max(512),
  url: z24.string().optional(),
  citation: z24.string().optional(),
  accessDate: z24.string().optional(),
  note: z24.string().optional()
});
var docketRouter = router({
  /** List all docket entries with optional filters and search */
  list: publicProcedure.input(z24.object({
    jurisdiction: z24.string().optional(),
    jurisdictionLevel: z24.enum(["federal", "state", "county", "city", "tribal"]).optional(),
    lawType: z24.enum(["statute", "ordinance", "regulation", "executive_order", "ballot_measure", "proposed_bill", "constitutional_amendment"]).optional(),
    status: z24.enum(["enacted", "proposed", "repealed", "amended", "under_review"]).optional(),
    search: z24.string().optional(),
    limit: z24.number().min(1).max(100).default(50),
    offset: z24.number().min(0).default(0)
  }).optional()).query(async ({ input }) => {
    return listDocketEntries(input);
  }),
  /** Search actors by name across all docket entries */
  searchActors: publicProcedure.input(z24.object({ term: z24.string().min(1) })).query(async ({ input }) => {
    return searchActorsByName(input.term);
  }),
  /** Get a single docket entry by ID */
  getById: publicProcedure.input(z24.object({ id: z24.number() })).query(async ({ input }) => {
    const entry = await getDocketEntry(input.id);
    if (!entry) throw new TRPCError10({ code: "NOT_FOUND", message: "Docket entry not found" });
    return entry;
  }),
  /** Get a single docket entry by slug */
  getBySlug: publicProcedure.input(z24.object({ slug: z24.string() })).query(async ({ input }) => {
    const entry = await getDocketEntryBySlug(input.slug);
    if (!entry) throw new TRPCError10({ code: "NOT_FOUND", message: "Docket entry not found" });
    return entry;
  }),
  /** Get full analysis (entry + actors + impacts + sources) */
  getFullAnalysis: publicProcedure.input(z24.object({ id: z24.number() })).query(async ({ input }) => {
    const analysis = await getFullDocketAnalysis(input.id);
    if (!analysis) throw new TRPCError10({ code: "NOT_FOUND", message: "Docket entry not found" });
    return analysis;
  }),
  /** Get docket statistics */
  stats: publicProcedure.query(async () => {
    return getDocketStats();
  }),
  /** Create a new docket entry (admin only) */
  create: adminProcedure.input(docketEntryInput).mutation(async ({ input }) => {
    const now3 = Date.now();
    const id = await createDocketEntry({
      ...input,
      createdAt: now3,
      updatedAt: now3
    });
    return { id };
  }),
  /** Update a docket entry (admin only) */
  update: adminProcedure.input(z24.object({ id: z24.number() }).merge(docketEntryInput.partial())).mutation(async ({ input }) => {
    const { id, ...data } = input;
    const existing = await getDocketEntry(id);
    if (!existing) throw new TRPCError10({ code: "NOT_FOUND" });
    await updateDocketEntry(id, data);
    return { success: true };
  }),
  /** Seed a complete docket analysis (admin only) — entry + actors + impacts + sources */
  seedFullAnalysis: adminProcedure.input(z24.object({
    entry: docketEntryInput,
    actors: z24.array(actorInput),
    impacts: z24.array(impactInput),
    sources: z24.array(sourceInput)
  })).mutation(async ({ input }) => {
    const now3 = Date.now();
    const existing = await getDocketEntryBySlug(input.entry.slug);
    if (existing) {
      await updateDocketEntry(existing.id, input.entry);
      await deleteActorsForDocket(existing.id);
      await deleteImpactsForDocket(existing.id);
      await deleteSourcesForDocket(existing.id);
      if (input.actors.length > 0) {
        await bulkCreateActors(input.actors.map((a) => ({ ...a, docketId: existing.id, createdAt: now3 })));
      }
      if (input.impacts.length > 0) {
        await bulkCreateImpacts(input.impacts.map((i) => ({ ...i, docketId: existing.id, createdAt: now3 })));
      }
      if (input.sources.length > 0) {
        await bulkCreateSources(input.sources.map((s) => ({ ...s, docketId: existing.id, createdAt: now3 })));
      }
      return { id: existing.id, updated: true };
    }
    const id = await createDocketEntry({
      ...input.entry,
      createdAt: now3,
      updatedAt: now3
    });
    if (input.actors.length > 0) {
      await bulkCreateActors(input.actors.map((a) => ({ ...a, docketId: id, createdAt: now3 })));
    }
    if (input.impacts.length > 0) {
      await bulkCreateImpacts(input.impacts.map((i) => ({ ...i, docketId: id, createdAt: now3 })));
    }
    if (input.sources.length > 0) {
      await bulkCreateSources(input.sources.map((s) => ({ ...s, docketId: id, createdAt: now3 })));
    }
    return { id, updated: false };
  }),
  // ─── Actor sub-routes ───
  actors: router({
    list: publicProcedure.input(z24.object({ docketId: z24.number() })).query(async ({ input }) => {
      return listActorsForDocket(input.docketId);
    }),
    create: adminProcedure.input(z24.object({ docketId: z24.number() }).merge(actorInput)).mutation(async ({ input }) => {
      const { docketId, ...data } = input;
      const id = await createDocketActor({ ...data, docketId, createdAt: Date.now() });
      return { id };
    })
  }),
  // ─── Impact sub-routes ───
  impacts: router({
    list: publicProcedure.input(z24.object({ docketId: z24.number() })).query(async ({ input }) => {
      return listImpactsForDocket(input.docketId);
    }),
    create: adminProcedure.input(z24.object({ docketId: z24.number() }).merge(impactInput)).mutation(async ({ input }) => {
      const { docketId, ...data } = input;
      const id = await createDocketImpact({ ...data, docketId, createdAt: Date.now() });
      return { id };
    })
  }),
  // ─── Source sub-routes ───
  sources: router({
    list: publicProcedure.input(z24.object({ docketId: z24.number() })).query(async ({ input }) => {
      return listSourcesForDocket(input.docketId);
    }),
    create: adminProcedure.input(z24.object({ docketId: z24.number() }).merge(sourceInput)).mutation(async ({ input }) => {
      const { docketId, ...data } = input;
      const id = await createDocketSource({ ...data, docketId, createdAt: Date.now() });
      return { id };
    })
  }),
  // ─── Submission sub-routes ───
  submissions: router({
    /** Submit a law for analysis (authenticated users) */
    create: protectedProcedure.input(z24.object({
      lawTitle: z24.string().min(1).max(512),
      jurisdiction: z24.string().min(1).max(128),
      jurisdictionLevel: z24.enum(["federal", "state", "county", "city", "tribal"]),
      referenceUrl: z24.string().max(1024).optional(),
      fileUrl: z24.string().max(1024).optional(),
      fileName: z24.string().max(512).optional(),
      notes: z24.string().max(2e3).optional()
    })).mutation(async ({ ctx, input }) => {
      const now3 = Date.now();
      const id = await createDocketSubmission({
        userId: ctx.user.id,
        userName: ctx.user.name ?? void 0,
        userEmail: ctx.user.email ?? void 0,
        lawTitle: input.lawTitle,
        jurisdiction: input.jurisdiction,
        jurisdictionLevel: input.jurisdictionLevel,
        referenceUrl: input.referenceUrl,
        fileUrl: input.fileUrl,
        fileName: input.fileName,
        notes: input.notes,
        status: "pending",
        createdAt: now3,
        updatedAt: now3
      });
      const fileNote = input.fileName ? ` [Attached: ${input.fileName}]` : "";
      await notifyOwner({
        title: "New Docket Room Submission",
        content: `${ctx.user.name ?? "A user"} submitted "${input.lawTitle}" (${input.jurisdiction}, ${input.jurisdictionLevel}) for analysis.${fileNote}`
      }).catch(() => {
      });
      return { id };
    }),
    /** List current user's submissions */
    mine: protectedProcedure.input(z24.object({
      limit: z24.number().min(1).max(50).default(20),
      offset: z24.number().min(0).default(0)
    }).optional()).query(async ({ ctx, input }) => {
      return listDocketSubmissions({
        userId: ctx.user.id,
        limit: input?.limit,
        offset: input?.offset
      });
    }),
    /** List all submissions (admin only) */
    listAll: adminProcedure.input(z24.object({
      status: z24.enum(["pending", "in_review", "published", "rejected"]).optional(),
      limit: z24.number().min(1).max(100).default(50),
      offset: z24.number().min(0).default(0)
    }).optional()).query(async ({ input }) => {
      return listDocketSubmissions(input);
    }),
    /** Update submission status (admin only) */
    updateStatus: adminProcedure.input(z24.object({
      id: z24.number(),
      status: z24.enum(["pending", "in_review", "published", "rejected"]),
      adminNotes: z24.string().optional(),
      docketEntryId: z24.number().optional()
    })).mutation(async ({ input }) => {
      const existing = await getDocketSubmission(input.id);
      if (!existing) throw new TRPCError10({ code: "NOT_FOUND" });
      await updateDocketSubmission(input.id, {
        status: input.status,
        adminNotes: input.adminNotes,
        docketEntryId: input.docketEntryId
      });
      return { success: true };
    })
  }),
  /**
   * Seattle Legistar Live Feed
   * Fetches recent legislative matters from the Seattle Legistar Web API.
   * Public API — no key required. Returns recent matters filtered by keyword.
   */
  legistarFeed: publicProcedure.input(z24.object({
    keyword: z24.string().optional(),
    top: z24.number().min(1).max(20).default(8)
  }).optional()).query(async ({ input }) => {
    const top = input?.top ?? 8;
    const keyword = input?.keyword?.trim();
    const baseUrl = "https://webapi.legistar.com/v1/seattle/matters";
    let filterParts = [];
    if (keyword) {
      filterParts.push(`substringof('${encodeURIComponent(keyword)}',MatterTitle)`);
    }
    const filterStr = filterParts.length > 0 ? `&$filter=${filterParts.join(" and ")}` : "";
    const url = `${baseUrl}?$top=${top}&$orderby=MatterLastModifiedUtc+desc${filterStr}`;
    try {
      const res = await fetch(url, {
        headers: { "Accept": "application/json" },
        signal: AbortSignal.timeout(8e3)
      });
      if (!res.ok) throw new Error(`Legistar API error: ${res.status}`);
      const data = await res.json();
      return {
        source: "Seattle Legistar",
        fetched_at: Date.now(),
        matters: data.map((m) => ({
          id: m.MatterId,
          file: m.MatterFile,
          title: m.MatterTitle,
          type: m.MatterTypeName,
          status: m.MatterStatusName,
          body: m.MatterBodyName,
          intro_date: m.MatterIntroDate,
          passed_date: m.MatterPassedDate,
          last_modified: m.MatterLastModifiedUtc,
          url: `https://seattle.legistar.com/LegislationDetail.aspx?ID=${m.MatterId}&GUID=${m.MatterGuid}`
        }))
      };
    } catch (err) {
      return {
        source: "Seattle Legistar",
        fetched_at: Date.now(),
        error: err.message || "Failed to fetch Legistar data",
        matters: []
      };
    }
  }),
  /**
   * Seattle Legistar Events Feed
   * Returns upcoming/recent city council events for the Case Deadlines panel.
   */
  legistarEvents: publicProcedure.input(z24.object({
    top: z24.number().min(1).max(10).default(5)
  }).optional()).query(async ({ input }) => {
    const top = input?.top ?? 5;
    const url = `https://webapi.legistar.com/v1/seattle/events?$top=${top}&$orderby=EventDate+desc`;
    try {
      const res = await fetch(url, {
        headers: { "Accept": "application/json" },
        signal: AbortSignal.timeout(8e3)
      });
      if (!res.ok) throw new Error(`Legistar Events API error: ${res.status}`);
      const data = await res.json();
      return {
        fetched_at: Date.now(),
        events: data.map((e) => ({
          id: e.EventId,
          body: e.EventBodyName,
          date: e.EventDate,
          location: e.EventLocation,
          agenda_url: e.EventAgendaFile
        }))
      };
    } catch (err) {
      return {
        fetched_at: Date.now(),
        error: err.message || "Failed to fetch Legistar events",
        events: []
      };
    }
  })
});

