var _rtcProfiles = null;
var _biasProfiles = null;
function getRTCProfiles() {
  if (!_rtcProfiles) _rtcProfiles = buildRTCProfiles();
  return _rtcProfiles;
}
function getRTCProfile(state) {
  return getRTCProfiles().find((p) => p.state === state.toUpperCase());
}
function getPrecedentChain() {
  return PRECEDENT_CHAIN;
}
function getPrecedentNode(id) {
  return PRECEDENT_CHAIN.find((p) => p.id === id);
}
function getStructuralBiasProfiles() {
  if (!_biasProfiles) _biasProfiles = buildStructuralBiasProfiles();
  return _biasProfiles;
}
function getStructuralBiasProfile(state) {
  return getStructuralBiasProfiles().find((p) => p.state === state.toUpperCase());
}
function getCivilGideonSummary() {
  const profiles = getRTCProfiles();
  const precedents = getPrecedentChain();
  const biasProfiles = getStructuralBiasProfiles();
  const gradeDistribution = { A: 0, B: 0, C: 0, D: 0, F: 0 };
  for (const p of profiles) gradeDistribution[p.overall_grade]++;
  const totalProvisions = profiles.reduce((sum, p) => sum + p.provisions.length, 0);
  const statesWithEvictionRTC = profiles.filter(
    (p) => p.provisions.some((pr) => pr.category === "housing_eviction" && pr.type !== "proposed" && pr.type !== "none")
  ).length;
  const statesWithFamilyRTC = profiles.filter(
    (p) => p.provisions.some((pr) => pr.category.startsWith("family_") && pr.type !== "proposed" && pr.type !== "none")
  ).length;
  const statesShareJudges = biasProfiles.filter((p) => p.court_structure.shares_judges_with_criminal).length;
  const statesShareCourthouse = biasProfiles.filter((p) => p.court_structure.shares_courthouse_with_criminal).length;
  return {
    states_profiled: profiles.length,
    total_provisions: totalProvisions,
    states_with_eviction_rtc: statesWithEvictionRTC,
    states_with_family_rtc: statesWithFamilyRTC,
    grade_distribution: gradeDistribution,
    precedent_chain_length: precedents.length,
    positive_precedents: precedents.filter((p) => p.outcome_for_rtc === "positive").length,
    structural_bias_states_profiled: biasProfiles.length,
    states_sharing_judges_with_criminal: statesShareJudges,
    states_sharing_courthouse_with_criminal: statesShareCourthouse
  };
}

// server/routers/civil-gideon.ts
var civilGideonRouter = router({
  /** Summary statistics for the Civil Gideon module */
  summary: publicProcedure.query(() => {
    return getCivilGideonSummary();
  }),
  /** All right-to-counsel state profiles */
  rtcProfiles: publicProcedure.query(() => {
    return getRTCProfiles();
  }),
  /** Single state RTC profile */
  rtcProfile: publicProcedure.input(z28.object({ state: z28.string().length(2) })).query(({ input }) => {
    return getRTCProfile(input.state) ?? null;
  }),
  /** Full precedent chain */
  precedentChain: publicProcedure.query(() => {
    return getPrecedentChain();
  }),
  /** Single precedent node */
  precedentNode: publicProcedure.input(z28.object({ id: z28.string() })).query(({ input }) => {
    return getPrecedentNode(input.id) ?? null;
  }),
  /** All structural bias profiles */
  biasProfiles: publicProcedure.query(() => {
    return getStructuralBiasProfiles();
  }),
  /** Single state structural bias profile */
  biasProfile: publicProcedure.input(z28.object({ state: z28.string().length(2) })).query(({ input }) => {
    return getStructuralBiasProfile(input.state) ?? null;
  })
});

// server/routers/registry-router.ts
import { z as z29 } from "zod";
import { TRPCError as TRPCError12 } from "@trpc/server";

// server/registry-db.ts
init_db();
import { sql as sql34 } from "drizzle-orm";
async function listJurisdictions() {
  const result = await db.execute(
    sql34`SELECT * FROM registry_jurisdictions ORDER BY name`
  );
  return result.rows ?? [];
}
async function getJurisdiction(id) {
  const result = await db.execute(
    sql34`SELECT * FROM registry_jurisdictions WHERE id = ${Number(id)} LIMIT 1`
  );
  return (result.rows ?? [])[0] ?? null;
}
async function listPrograms(jurisdictionId, category) {
  if (jurisdictionId && category) {
    const result2 = await db.execute(
      sql34`SELECT * FROM registry_programs WHERE jurisdiction_id = ${Number(jurisdictionId)} AND category = ${category} ORDER BY name`
    );
    return result2.rows ?? [];
  }
  if (jurisdictionId) {
    const result2 = await db.execute(
      sql34`SELECT * FROM registry_programs WHERE jurisdiction_id = ${Number(jurisdictionId)} ORDER BY name`
    );
    return result2.rows ?? [];
  }
  const result = await db.execute(
    sql34`SELECT * FROM registry_programs ORDER BY name`
  );
  return result.rows ?? [];
}
async function listPolicyAlerts(jurisdictionId) {
  if (jurisdictionId) {
    const result2 = await db.execute(
      sql34`SELECT * FROM registry_policy_alerts WHERE jurisdiction_id = ${Number(jurisdictionId)} ORDER BY created_at DESC`
    );
    return result2.rows ?? [];
  }
  const result = await db.execute(
    sql34`SELECT * FROM registry_policy_alerts ORDER BY created_at DESC`
  );
  return result.rows ?? [];
}
async function listWorkflows(jurisdictionId) {
  if (jurisdictionId) {
    const result2 = await db.execute(
      sql34`SELECT * FROM registry_workflows WHERE jurisdiction_id = ${Number(jurisdictionId)} ORDER BY name`
    );
    return result2.rows ?? [];
  }
  const result = await db.execute(
    sql34`SELECT * FROM registry_workflows ORDER BY name`
  );
  return result.rows ?? [];
}
async function listOversightBodies(jurisdictionId) {
  if (jurisdictionId) {
    const result2 = await db.execute(
      sql34`SELECT * FROM registry_oversight_bodies WHERE jurisdiction_id_rob = ${Number(jurisdictionId)} ORDER BY agency_name_rob`
    );
    return result2.rows ?? [];
  }
  const result = await db.execute(
    sql34`SELECT * FROM registry_oversight_bodies ORDER BY agency_name_rob`
  );
  return result.rows ?? [];
}
async function getSignals(jurisdictionId, signalType) {
  if (jurisdictionId && signalType) {
    const result2 = await db.execute(
      sql34`SELECT * FROM registry_signals WHERE jurisdiction_id = ${Number(jurisdictionId)} AND signal_type = ${signalType} ORDER BY created_at DESC`
    );
    return result2.rows ?? [];
  }
  if (jurisdictionId) {
    const result2 = await db.execute(
      sql34`SELECT * FROM registry_signals WHERE jurisdiction_id = ${Number(jurisdictionId)} ORDER BY created_at DESC`
    );
    return result2.rows ?? [];
  }
  if (signalType) {
    const result2 = await db.execute(
      sql34`SELECT * FROM registry_signals WHERE signal_type = ${signalType} ORDER BY created_at DESC`
    );
    return result2.rows ?? [];
  }
  const result = await db.execute(
    sql34`SELECT * FROM registry_signals ORDER BY created_at DESC`
  );
  return result.rows ?? [];
}
async function getSourceTraceability(jurisdictionId) {
  return { jurisdictionId, sources: [], lastUpdated: null };
}
async function getProgramCategories(jurisdictionId) {
  if (jurisdictionId) {
    const result2 = await db.execute(
      sql34`SELECT DISTINCT category FROM registry_programs WHERE jurisdiction_id = ${Number(jurisdictionId)} AND category IS NOT NULL ORDER BY category`
    );
    return (result2.rows ?? []).map((r) => r.category);
  }
  const result = await db.execute(
    sql34`SELECT DISTINCT category FROM registry_programs WHERE category IS NOT NULL ORDER BY category`
  );
  return (result.rows ?? []).map((r) => r.category);
}
async function getCounts() {
  const jurisdictions = await db.execute(sql34`SELECT COUNT(*) as count FROM registry_jurisdictions`);
  const programs = await db.execute(sql34`SELECT COUNT(*) as count FROM registry_programs`);
  const alerts = await db.execute(sql34`SELECT COUNT(*) as count FROM registry_policy_alerts`);
  const workflows = await db.execute(sql34`SELECT COUNT(*) as count FROM registry_workflows`);
  const oversight = await db.execute(sql34`SELECT COUNT(*) as count FROM registry_oversight_bodies`);
  const signals = await db.execute(sql34`SELECT COUNT(*) as count FROM registry_signals`);
  return {
    jurisdictions: Number((jurisdictions.rows ?? [])[0]?.count ?? 0),
    programs: Number((programs.rows ?? [])[0]?.count ?? 0),
    policyAlerts: Number((alerts.rows ?? [])[0]?.count ?? 0),
    workflows: Number((workflows.rows ?? [])[0]?.count ?? 0),
    oversightBodies: Number((oversight.rows ?? [])[0]?.count ?? 0),
    signals: Number((signals.rows ?? [])[0]?.count ?? 0)
  };
}

