    const rows2 = await db.select().from(detectedSignals).where(conditions.length > 0 ? and18(...conditions) : void 0).orderBy(desc10(detectedSignals.detectionTimestamp)).limit(opts.limit ?? 100).offset(opts.offset ?? 0);
