      db.select({ count: sql37`COUNT(*)` }).from(detectedSignals).where(eq22(detectedSignals.severityLevel, "medium")),
      db.select({ count: sql37`COUNT(*)` }).from(detectedSignals).where(eq22(detectedSignals.severityLevel, "low")),
      db.select({ datasetId: detectedSignals.datasetId, count: sql37`COUNT(*)` }).from(detectedSignals).groupBy(detectedSignals.datasetId)
