    const results = await Promise.all(
      tables.map(async (t2) => {
        try {
          const { rows: rows2 } = await getPool().query(`SELECT COUNT(*)::int AS cnt FROM ${quoteSafeIdentifier(t2.name)}`);
          const cnt = Number(rows2[0]?.cnt ?? 0);
          return {
            name: t2.name,
            label: t2.label,
            count: cnt,
            target: t2.target,
            coverage: Math.min(100, Math.round(cnt / t2.target * 100))
          };
        } catch {
          return { name: t2.name, label: t2.label, count: 0, target: t2.target, coverage: 0 };
        }
      })
    );
    const totalPopulated = results.reduce((s, r) => s + r.count, 0);
    const totalTarget = results.reduce((s, r) => s + r.target, 0);
    const criticallyLow = results.filter((r) => r.count === 0);
    const underPopulated = results.filter((r) => r.count > 0 && r.coverage < 25);
