    if (records.length === 0) throw new TRPCError13({ code: "BAD_REQUEST", message: "No records found in JSON" });
    if (records.length > 2e3) throw new TRPCError13({ code: "BAD_REQUEST", message: "Maximum 2000 records per import" });
    if (!allowedKnowledgeBackboneTables.has(input.targetTable)) {
      throw new TRPCError13({ code: "BAD_REQUEST", message: "Unsupported Knowledge Backbone target table" });
    }
    const quotedTable = quoteSafeIdentifier(input.targetTable);
    const pool3 = getPool();
    const { rows: columnRows } = await pool3.query(
      `
          SELECT column_name, data_type, udt_name
          FROM information_schema.columns
          WHERE table_schema = 'public' AND table_name = $1
        `,
      [input.targetTable]
    );
    if (columnRows.length === 0) {
      throw new TRPCError13({ code: "BAD_REQUEST", message: `Target table not found: ${input.targetTable}` });
    }
    const columns = new Map(
      columnRows.map((row) => [
        row.column_name,
        { dataType: row.data_type, udtName: row.udt_name }
      ])
    );
    const legacyDefaults = {
      legal_statutes: { jurisdiction_id: 0, statute_citation: "" },
      legal_case_law: { jurisdiction_id: 0, case_citation: "" },
      lumensend_templates: { name: "" },
      legislator_contacts: { full_name: "", jurisdiction: "", chamber: "other" },
      advocacy_organizations: { name: "", org_type: "other", jurisdiction: "" },
      deadline_rules: { claim_type: "", jurisdiction: "", trigger_event: "", deadline_type: "filing" },
      weak_joint_triggers: { trigger_name: "" }
    };
