async function evaluatePatternsForStrategies() {
  const [patterns3] = await db.execute(sql58`
    SELECT pr.pattern_id, pr.pattern_type AS pattern_name, pr.pattern_type, pr.signal_count,
           tr.trend_classification, tr.pressure_index, pr.geographic_spread
    FROM pattern_registry pr
    LEFT JOIN trend_registry tr ON pr.pattern_id = tr.pattern_id
    WHERE pr.decay_status != 'decayed'
      AND pr.pattern_id NOT IN (
        SELECT DISTINCT pattern_id FROM sys_strategy_paths
        WHERE path_status IN ('proposed', 'approved', 'in_progress')
      )
    ORDER BY COALESCE(tr.pressure_index, 0) DESC
    LIMIT 20
  `);
  const results = [];
  let strategiesGenerated = 0;
  for (const p of patterns3) {
    const trend = p.trend_classification || "stable";
    const pressure = p.pressure_index || 50;
    const strategy = await selectStrategy(p.pattern_type, trend, pressure);
    if (strategy) {
      const { pathId } = await generateStrategyPath({
        patternId: p.pattern_id,
        strategyId: strategy.strategyId,
        pathName: `${strategy.strategyName} \u2014 ${p.pattern_name}`,
        trendClassification: trend,
        pressureIndex: pressure,
        signalCount: p.signal_count || 0,
        geographicScope: []
      });
      results.push({ patternId: p.pattern_id, patternName: p.pattern_name, strategyName: strategy.strategyName, pathId });
      strategiesGenerated++;
    } else {
      results.push({ patternId: p.pattern_id, patternName: p.pattern_name, strategyName: null, pathId: null });
    }
  }
  return { evaluated: patterns3.length, strategiesGenerated, results };
}
async function updateStepStatus(stepId, status, notes) {
  const now3 = /* @__PURE__ */ new Date();
  if (status === "in_progress") {
    await db.execute(sql58`
      UPDATE strategy_steps SET step_status = ${status}, started_at = ${now3},
        notes = COALESCE(${notes || null}, notes), updated_at = ${now3}
      WHERE step_id = ${stepId}
    `);
  } else if (status === "completed") {
    await db.execute(sql58`
      UPDATE strategy_steps SET step_status = ${status}, completed_at = ${now3},
        notes = COALESCE(${notes || null}, notes), updated_at = ${now3}
      WHERE step_id = ${stepId}
    `);
  } else {
    await db.execute(sql58`
      UPDATE strategy_steps SET step_status = ${status},
        notes = COALESCE(${notes || null}, notes), updated_at = ${now3}
      WHERE step_id = ${stepId}
    `);
  }
  return { success: true };
}
async function updatePathStatus(pathId, status, approvedBy) {
  const now3 = /* @__PURE__ */ new Date();
  if (status === "approved") {
    await db.execute(sql58`
      UPDATE sys_strategy_paths SET path_status = ${status},
        approved_by = ${approvedBy || null}, approved_at = ${now3}, updated_at = ${now3}
      WHERE path_id = ${pathId}
    `);
  } else if (status === "in_progress") {
    await db.execute(sql58`
      UPDATE sys_strategy_paths SET path_status = ${status},
        started_at = ${now3}, updated_at = ${now3}
      WHERE path_id = ${pathId}
    `);
  } else if (status === "completed") {
    await db.execute(sql58`
      UPDATE sys_strategy_paths SET path_status = ${status},
        completed_at = ${now3}, updated_at = ${now3}
      WHERE path_id = ${pathId}
    `);
  } else {
    await db.execute(sql58`
      UPDATE sys_strategy_paths SET path_status = ${status}, updated_at = ${now3}
      WHERE path_id = ${pathId}
    `);
  }
  return { success: true };
}
