async function getMissionControlStrategySummary() {
  const [summaryRows] = await db.execute(sql58`
    SELECT
      COUNT(*) as total,
      SUM(CASE WHEN path_status = 'proposed' THEN 1 ELSE 0 END) as proposed,
      SUM(CASE WHEN path_status = 'approved' THEN 1 ELSE 0 END) as approved,
      SUM(CASE WHEN path_status = 'in_progress' THEN 1 ELSE 0 END) as in_progress,
      SUM(CASE WHEN path_status = 'completed' THEN 1 ELSE 0 END) as completed,
      AVG(success_probability) as avg_probability,
      SUM(COALESCE(estimated_cost, 0)) as total_cost
    FROM sys_strategy_paths
  `);
  const s = summaryRows[0] || {};
  const [typeRows] = await db.execute(sql58`
    SELECT sr.strategy_type as type, COUNT(*) as count
    FROM sys_strategy_paths sp
    JOIN strategy_registry sr ON sp.strategy_id = sr.strategy_id
    GROUP BY sr.strategy_type
    ORDER BY count DESC
  `);
  return {
    totalPaths: Number(s.total) || 0,
    proposed: Number(s.proposed) || 0,
    approved: Number(s.approved) || 0,
    inProgress: Number(s.in_progress) || 0,
    completed: Number(s.completed) || 0,
    avgSuccessProbability: Math.round(Number(s.avg_probability) || 0),
    totalEstimatedCost: Number(s.total_cost) || 0,
    strategiesByType: typeRows.map((r) => ({
      type: r.type,
      count: Number(r.count)
    }))
  };
}

// server/paperwork-trigger.ts
init_db();
import { sql as sql60 } from "drizzle-orm";

// server/paperwork-engine.ts
init_db();
init_llm();
init_schema();
import { eq as eq45, desc as desc23 } from "drizzle-orm";
async function generateDocument(input) {
  const [[caseRow], caseClaims, caseFindings, caseEvents] = await Promise.all([
    db.select().from(cases).where(eq45(cases.id, input.caseId)),
    db.select({
      claimType: claims.claimType,
      // @ts-ignore pre-existing type mismatch
      description: claims.description,
      // @ts-ignore pre-existing type mismatch
      severity: claims.severity
    }).from(claims).where(eq45(claims.caseId, input.caseId)).limit(10),
    db.select({
      findingType: findings.findingType,
      // @ts-ignore pre-existing type mismatch
      summary: findings.summary
    }).from(findings).where(eq45(findings.caseId, input.caseId)).limit(10),
    db.select({
      description: events.description,
      // @ts-ignore pre-existing type mismatch
      eventDate: events.eventDate
      // @ts-ignore pre-existing type mismatch
    }).from(events).where(eq45(events.caseId, input.caseId)).orderBy(events.eventDate).limit(15)
  ]);
  if (!caseRow) throw new Error("Case not found");
  let templateBody = "";
  let templateTitle = "";
  if (input.templateId) {
    const [tmpl] = await db.select().from(paperworkTemplates).where(eq45(paperworkTemplates.id, input.templateId));
    if (tmpl) {
      templateBody = tmpl.templateBody;
      templateTitle = tmpl.title;
    }
  }
  const docTypeLabels = {
    appeal_letter: "Appeal Letter",
    complaint_filing: "Formal Complaint",
    foia_request: "FOIA Request",
    record_request: "Record Request",
    grievance: "Formal Grievance",
    cease_desist: "Cease and Desist Letter",
    demand_letter: "Demand Letter",
    formal_response: "Formal Response"
  };
  const docLabel = docTypeLabels[input.documentType] || input.documentType;
  const claimsSummary = caseClaims.map(
    (c) => `- ${c.claimType}: ${c.description?.slice(0, 120) || "No description"}`
  ).join("\n");
  const findingsSummary = caseFindings.map(
    (f) => `- ${f.findingType}: ${f.summary?.slice(0, 120) || "No summary"}`
  ).join("\n");
  const eventsSummary = caseEvents.slice(0, 8).map(
    (e) => `- ${e.eventDate ? new Date(e.eventDate).toLocaleDateString() : "Date unknown"}: ${e.description?.slice(0, 100) || "Event"}`
  ).join("\n");
  const prompt = `Generate a professional ${docLabel} based on the following case information. The document should be formal, clear, and suitable for submission to a government agency, court, or organization.

CASE: ${caseRow.name}
${input.recipientName ? `RECIPIENT: ${input.recipientName}` : ""}
${input.recipientAddress ? `ADDRESS: ${input.recipientAddress}` : ""}

CLAIMS:
${claimsSummary || "No specific claims identified yet"}

KEY FINDINGS:
${findingsSummary || "No findings yet"}

KEY EVENTS (CHRONOLOGICAL):
${eventsSummary || "No events extracted yet"}

${templateBody ? `TEMPLATE TO FOLLOW:
${templateBody}
` : ""}
${input.customInstructions ? `ADDITIONAL INSTRUCTIONS:
${input.customInstructions}
` : ""}

Generate the complete document in Markdown format. Include:
1. Proper header with date, recipient, and sender placeholders
2. Clear subject line
3. Professional opening
4. Factual body referencing specific claims and events
5. Clear request or demand
6. Professional closing
7. Signature block with [YOUR NAME], [YOUR ADDRESS], [YOUR PHONE], [YOUR EMAIL] placeholders

Use formal but accessible language. The person filing this may not be a lawyer.`;
  const response = await invokeLLM({
    messages: [
      { role: "system", content: "You are a legal document drafting assistant. Generate professional, formal documents suitable for official submission. Use Markdown formatting. Be specific and reference the case facts provided." },
      { role: "user", content: prompt }
    ]
  });
  const content = response.choices?.[0]?.message?.content;
  if (!content) throw new Error("No response from LLM");
  const title = templateTitle || `${docLabel} \u2014 ${caseRow.name}`;
  const now3 = Date.now();
  const [inserted] = await db.insert(generatedDocuments).values({
    caseId: input.caseId,
    userId: input.userId,
    templateId: input.templateId || null,
    remedyStepId: input.remedyStepId || null,
    documentType: input.documentType,
    title,
    content,
    recipientName: input.recipientName || null,
    recipientAddress: input.recipientAddress || null,
    createdAt: now3,
    updatedAt: now3
  });
  return inserted.insertId;
}

// server/paperwork-trigger.ts
var STEP_DOC_MAPPINGS = [
  {
    stepTypePattern: /cease.?and.?desist|cease_desist|c&d/i,
    documentType: "cease_desist",
    templateLabel: "Enforcement Letter \u2014 Cease & Desist",
    triggerOn: ["ready", "in_progress"]
  },
  {
    stepTypePattern: /complaint|agency.?complaint|file.?complaint/i,
    documentType: "complaint_filing",
    templateLabel: "Agency Complaint Template",
    triggerOn: ["ready", "in_progress"]
  },
  {
    stepTypePattern: /oversight|oversight.?request|legislative.?brief/i,
    documentType: "formal_response",
    templateLabel: "Oversight Briefing Package",
    triggerOn: ["ready"]
  },
  {
    stepTypePattern: /regulatory.?notice|notice.?package|agency.?notice/i,
    documentType: "demand_letter",
    templateLabel: "Regulatory Notice Package",
    triggerOn: ["ready"]
  },
  {
    stepTypePattern: /foia|records?.?request|public.?records/i,
    documentType: "foia_request",
    templateLabel: "FOIA / Records Request",
    triggerOn: ["in_progress"]
  },
  {
    stepTypePattern: /appeal|administrative.?appeal/i,
    documentType: "appeal_letter",
    templateLabel: "Appeal Letter",
    triggerOn: ["ready", "in_progress"]
  },
  {
    stepTypePattern: /grievance|formal.?grievance/i,
    documentType: "grievance",
    templateLabel: "Formal Grievance Filing",
    triggerOn: ["ready"]
  },
  {
    stepTypePattern: /demand|demand.?letter/i,
    documentType: "demand_letter",
    templateLabel: "Demand Letter",
    triggerOn: ["ready", "in_progress"]
  },
  {
    stepTypePattern: /investigation|investigation.?package|evidence.?package/i,
    documentType: "complaint_filing",
    templateLabel: "Investigation Package",
    triggerOn: ["in_progress"]
  },
  {
    stepTypePattern: /enforcement|enforcement.?referral/i,
    documentType: "cease_desist",
    templateLabel: "Enforcement Referral Letter",
    triggerOn: ["ready", "in_progress"]
  }
];
function resolveDocMapping(stepType, stepName, stepDescription) {
  const combined = `${stepType} ${stepName} ${stepDescription}`.toLowerCase();
  for (const mapping of STEP_DOC_MAPPINGS) {
    if (mapping.stepTypePattern.test(combined)) {
      return mapping;
    }
  }
  return null;
}
async function hasExistingDoc(stepId, documentType) {
  const [rows2] = await db.execute(sql60`
    SELECT id FROM generated_documents
    WHERE metadata->>'$.strategyStepId' = ${stepId}
      AND documentType = ${documentType}
    LIMIT 1
  `);
  return rows2.length > 0;
}
async function triggerPaperworkForStep(params) {
  const [stepRows] = await db.execute(sql60`
    SELECT step_id, step_name, step_type, step_description, documentation_required
    FROM strategy_steps WHERE step_id = ${params.stepId}
  `);
  const step = stepRows[0];
  if (!step) {
    return { triggered: false, reason: "Step not found" };
  }
  const mapping = resolveDocMapping(
    step.step_type || "",
    step.step_name || "",
    step.step_description || ""
  );
  if (!mapping) {
    return { triggered: false, reason: `No document mapping for step type: ${step.step_type}` };
  }
  if (!mapping.triggerOn.includes(params.newStatus)) {
    return {
      triggered: false,
      reason: `Status '${params.newStatus}' does not trigger for ${mapping.documentType}`
    };
  }
  const exists = await hasExistingDoc(params.stepId, mapping.documentType);
  if (exists) {
    return { triggered: false, reason: "Document already generated for this step" };
  }
  const docId = await generateDocument({
    caseId: params.caseId,
    userId: params.userId,
    documentType: mapping.documentType,
    customInstructions: `Auto-generated for strategy step: ${step.step_name}. ${step.step_description || ""}`
  });
  const metadata = JSON.stringify({
    strategyStepId: params.stepId,
    strategyPathId: params.pathId,
    patternId: params.patternId || null,
    strategyId: params.strategyId || null,
    autoGenerated: true,
    triggerStatus: params.newStatus,
    templateLabel: mapping.templateLabel
  });
  await db.execute(sql60`
    UPDATE generated_documents
    SET metadata = ${metadata}
    WHERE id = ${docId}
  `);
  await db.execute(sql60`
    INSERT INTO evidence_items (caseId, evidenceType, title, description, sourceName, fileReference, metadata, createdAt, updatedAt)
    VALUES (
      ${params.caseId},
      'generated_document',
      ${`[Auto] ${mapping.templateLabel} \u2014 ${step.step_name}`},
      ${`Auto-generated document for strategy step "${step.step_name}" (${mapping.documentType}). Linked to path ${params.pathId}.`},
      'Paperwork Trigger Engine',
      ${`generated_doc:${docId}`},
      ${JSON.stringify({
    generatedDocId: docId,
    strategyStepId: params.stepId,
    strategyPathId: params.pathId,
    patternId: params.patternId,
    documentType: mapping.documentType
  })},
      ${Date.now()},
      ${Date.now()}
    )
  `);
  return {
    triggered: true,
    documentId: docId,
    documentType: mapping.documentType,
    reason: `Generated ${mapping.templateLabel} for step "${step.step_name}"`
  };
}
async function triggerPaperworkForPath(params) {
  const statusClause = params.statusFilter ? sql60`AND step_status = ${params.statusFilter}` : sql60`AND step_status IN ('ready', 'in_progress', 'completed')`;
  const [steps] = await db.execute(sql60`
    SELECT step_id, step_name, step_status
    FROM strategy_steps
    WHERE path_id = ${params.pathId} ${statusClause}
    ORDER BY step_number ASC
  `);
  const results = [];
  let triggered = 0;
  let skipped = 0;
  for (const step of steps) {
    const result = await triggerPaperworkForStep({
      stepId: step.step_id,
      pathId: params.pathId,
      newStatus: step.step_status,
      caseId: params.caseId,
      userId: params.userId,
      patternId: params.patternId,
      strategyId: params.strategyId
    });
    results.push({
      stepId: step.step_id,
      stepName: step.step_name,
      triggered: result.triggered,
      documentId: result.documentId,
      reason: result.reason
    });
    if (result.triggered) triggered++;
    else skipped++;
  }
  return {
    total: steps.length,
    triggered,
    skipped,
    results
  };
}
async function getAutoGeneratedDocsForStep(stepId) {
  const [rows2] = await db.execute(sql60`
    SELECT id, caseId, documentType, title, genDocStatus, createdAt, metadata
    FROM generated_documents
    WHERE metadata->>'$.strategyStepId' = ${stepId}
    ORDER BY createdAt DESC
  `);
  return rows2;
}
async function getAutoGeneratedDocsForPath(pathId) {
  const [rows2] = await db.execute(sql60`
    SELECT id, caseId, documentType, title, genDocStatus, createdAt, metadata
    FROM generated_documents
    WHERE metadata->>'$.strategyPathId' = ${pathId}
    ORDER BY createdAt DESC
  `);
  return rows2;
}
async function getPaperworkTriggerStatus() {
  const [countRows] = await db.execute(sql60`
    SELECT COUNT(*) as total FROM generated_documents
    WHERE metadata->>'$.autoGenerated' = 'true'
  `);
  const [typeRows] = await db.execute(sql60`
    SELECT documentType, COUNT(*) as cnt FROM generated_documents
    WHERE metadata->>'$.autoGenerated' = 'true'
    GROUP BY documentType
  `);
  const [recentRows] = await db.execute(sql60`
    SELECT id, caseId, documentType, title, genDocStatus, createdAt, metadata
    FROM generated_documents
    WHERE metadata->>'$.autoGenerated' = 'true'
    ORDER BY createdAt DESC
    LIMIT 20
  `);
  const byDocumentType = {};
  for (const row of typeRows) {
    byDocumentType[row.documentType] = Number(row.cnt);
  }
  return {
    totalAutoGenerated: Number(countRows[0]?.total) || 0,
    byDocumentType,
    recentTriggers: recentRows
  };
}

// server/routers/systemic-strategy-router.ts
var systemicStrategyRouter = router({
  /** Dashboard: list all strategy paths with joined strategy + pattern info */
  dashboard: protectedProcedure.input(
    z51.object({
      status: z51.string().optional(),
      strategyType: z51.string().optional(),
      limit: z51.number().optional(),
      offset: z51.number().optional()
    }).optional()
  ).query(async ({ input }) => {
    return getStrategyDashboard(input || void 0);
  }),
  /** Detail: full strategy path with steps, strategy info, pattern info */
  detail: protectedProcedure.input(z51.object({ pathId: z51.string() })).query(async ({ input }) => {
    return getStrategyPathDetail(input.pathId);
  }),
  /** Select best strategy for a pattern based on type, trend, and pressure */
  selectStrategy: protectedProcedure.input(z51.object({
    patternType: z51.string(),
    trendClassification: z51.string(),
    pressureIndex: z51.number()
  })).query(async ({ input }) => {
    return selectStrategy(input.patternType, input.trendClassification, input.pressureIndex);
  }),
  /** Calculate success probability for a strategy */
  calculateProbability: protectedProcedure.input(z51.object({
    historicalSuccessRate: z51.number(),
    pressureIndex: z51.number(),
    trendClassification: z51.string(),
    signalCount: z51.number(),
    geographicSpread: z51.number()
  })).query(async ({ input }) => {
    const probability = calculateSuccessProbability(
      input.historicalSuccessRate,
      input.pressureIndex,
      input.trendClassification,
      input.signalCount,
      input.geographicSpread
    );
    return { probability };
  }),
  /** Generate a strategy path for a pattern */
  generatePath: protectedProcedure.input(z51.object({
    patternId: z51.string(),
    strategyId: z51.string(),
    pathName: z51.string(),
    pathDescription: z51.string().optional(),
    trendClassification: z51.string(),
    pressureIndex: z51.number(),
    signalCount: z51.number(),
    geographicScope: z51.any().optional(),
    assignedLead: z51.string().optional()
  })).mutation(async ({ input }) => {
    return generateStrategyPath(input);
  }),
  /** Evaluate all active patterns and generate strategy paths */
  evaluateAll: protectedProcedure.mutation(async () => {
    return evaluatePatternsForStrategies();
  }),
  /** Update a strategy step status — with automated paperwork trigger */
  updateStep: protectedProcedure.input(z51.object({
    stepId: z51.string(),
    status: z51.string(),
    notes: z51.string().optional(),
    caseId: z51.number().optional(),
    patternId: z51.string().optional(),
    strategyId: z51.string().optional(),
    pathId: z51.string().optional()
  })).mutation(async ({ input, ctx }) => {
    const result = await updateStepStatus(input.stepId, input.status, input.notes);
    let paperworkResult = null;
    if (input.caseId && input.pathId) {
      try {
        paperworkResult = await triggerPaperworkForStep({
          stepId: input.stepId,
          pathId: input.pathId,
          newStatus: input.status,
          caseId: input.caseId,
          userId: ctx.user.id,
          patternId: input.patternId,
          strategyId: input.strategyId
        });
      } catch (err) {
        console.error("[PaperworkTrigger] Error:", err);
        paperworkResult = { triggered: false, reason: "Trigger error" };
      }
    }
    return { ...result, paperwork: paperworkResult };
  }),
  /** Update a strategy path status */
  updatePathStatus: protectedProcedure.input(z51.object({
    pathId: z51.string(),
    status: z51.string(),
    approvedBy: z51.string().optional()
  })).mutation(async ({ input }) => {
    return updatePathStatus(input.pathId, input.status, input.approvedBy);
  }),
  /** Trigger paperwork for all eligible steps in a path */
  triggerPathPaperwork: protectedProcedure.input(z51.object({
    pathId: z51.string(),
    caseId: z51.number(),
    patternId: z51.string().optional(),
    strategyId: z51.string().optional(),
    statusFilter: z51.string().optional()
  })).mutation(async ({ input, ctx }) => {
    return triggerPaperworkForPath({
      ...input,
      userId: ctx.user.id
    });
  }),
  /** Get auto-generated documents for a step */
  stepDocuments: protectedProcedure.input(z51.object({ stepId: z51.string() })).query(async ({ input }) => {
    return getAutoGeneratedDocsForStep(input.stepId);
  }),
  /** Get auto-generated documents for a path */
  pathDocuments: protectedProcedure.input(z51.object({ pathId: z51.string() })).query(async ({ input }) => {
    return getAutoGeneratedDocsForPath(input.pathId);
  }),
  /** Paperwork trigger status summary */
  paperworkTriggerStatus: protectedProcedure.query(async () => {
    return getPaperworkTriggerStatus();
  }),
  /** Mission Control summary widget */
  missionControlSummary: protectedProcedure.query(async () => {
    return getMissionControlStrategySummary();
  })
});

// server/routers/outcome-engine-router.ts
import { z as z52 } from "zod";

// server/outcome-engine.ts
init_db();
import { sql as sql61 } from "drizzle-orm";
import { randomUUID as randomUUID5 } from "crypto";
async function recordOutcome2(params) {
  const outcomeId = randomUUID5();
  const [patternRows] = await db.execute(sql61`
    SELECT pr.signal_count, tr.pressure_index, tr.trend_classification
    FROM pattern_registry pr
    LEFT JOIN trend_registry tr ON pr.pattern_id = tr.pattern_id
    WHERE pr.pattern_id = ${params.patternId}
  `);
  const p = patternRows[0];
  await db.execute(sql61`
    INSERT INTO outcome_registry (
      outcome_id, path_id, strategy_id, pattern_id,
      outcome_status, outcome_description,
      intervention_start_date, intervention_end_date,
      signals_before, pressure_before, trend_before,
      lessons_learned
    ) VALUES (
      ${outcomeId}, ${params.pathId}, ${params.strategyId}, ${params.patternId},
      ${params.outcomeStatus}, ${params.outcomeDescription || null},
      ${params.interventionStartDate ? new Date(params.interventionStartDate) : null},
      ${params.interventionEndDate ? new Date(params.interventionEndDate) : null},
      ${p?.signal_count || 0}, ${p?.pressure_index || 0}, ${p?.trend_classification || "unknown"},
      ${params.lessonsLearned || null}
    )
  `);
  return { outcomeId };
}
async function updateOutcomeMetrics(outcomeId, params) {
  const [currentRows] = await db.execute(sql61`
    SELECT signals_before, pressure_before FROM outcome_registry WHERE outcome_id = ${outcomeId}
  `);
  const current = currentRows[0];
  if (!current) return { success: false };
  const signalsBefore = Number(current.signals_before) || 0;
  const pressureBefore = Number(current.pressure_before) || 0;
  const signalsAfter = params.signalsAfter ?? signalsBefore;
  const pressureAfter = params.pressureAfter ?? pressureBefore;
  const signalReductionPct = signalsBefore > 0 ? Math.round((signalsBefore - signalsAfter) / signalsBefore * 1e4) / 100 : 0;
  const pressureReductionPct = pressureBefore > 0 ? Math.round((pressureBefore - pressureAfter) / pressureBefore * 1e4) / 100 : 0;
  const signalsReduced = Math.max(0, signalsBefore - signalsAfter);
  const costPerSignalReduced = signalsReduced > 0 && params.totalCost ? Math.round(params.totalCost / signalsReduced * 100) / 100 : 0;
  const trendImproved = params.trendAfter === "declining" || params.trendAfter === "stable";
  const effectivenessScore = calculateEffectivenessScore({
    signalReductionPct: Math.max(0, signalReductionPct),
    pressureReductionPct: Math.max(0, pressureReductionPct),
    trendImprovement: trendImproved,
    costEfficiency: costPerSignalReduced > 0 ? Math.min(1, 1e3 / costPerSignalReduced) : 0.5,
    timeEfficiency: 0.5,
    // default
    geographicCoverage: 0.5
    // default
  });
  await db.execute(sql61`
    UPDATE outcome_registry SET
      outcome_status = COALESCE(${params.outcomeStatus || null}, outcome_status),
      signals_after = ${signalsAfter},
      signal_reduction_pct = ${signalReductionPct},
      pressure_after = ${pressureAfter},
      pressure_reduction_pct = ${pressureReductionPct},
      trend_after = COALESCE(${params.trendAfter || null}, trend_after),
      entities_affected = COALESCE(${params.entitiesAffected ?? null}, entities_affected),
      geographic_areas_affected = COALESCE(${params.geographicAreasAffected ?? null}, geographic_areas_affected),
      total_cost = COALESCE(${params.totalCost ?? null}, total_cost),
      cost_per_signal_reduced = ${costPerSignalReduced},
      overall_effectiveness_score = ${effectivenessScore},
      lessons_learned = COALESCE(${params.lessonsLearned || null}, lessons_learned),
      updated_at = NOW()
    WHERE outcome_id = ${outcomeId}
  `);
  return { success: true, effectivenessScore };
}
function calculateEffectivenessScore(params) {
  const score = Math.min(100, Math.max(0, params.signalReductionPct)) * 0.3 + Math.min(100, Math.max(0, params.pressureReductionPct)) * 0.25 + (params.trendImprovement ? 15 : 0) + Math.min(1, Math.max(0, params.costEfficiency)) * 15 + Math.min(1, Math.max(0, params.timeEfficiency)) * 10 + Math.min(1, Math.max(0, params.geographicCoverage)) * 5;
  return Math.max(0, Math.min(100, Math.round(score)));
}
async function recordOutcomeMetric(params) {
  const changePct = params.valueBefore !== 0 ? Math.round((params.valueAfter - params.valueBefore) / Math.abs(params.valueBefore) * 1e4) / 100 : 0;
  const [result] = await db.execute(sql61`
    INSERT INTO outcome_metrics (
      outcome_id, metric_name, metric_category,
      value_before, value_after, change_pct,
      measurement_date, notes
    ) VALUES (
      ${params.outcomeId}, ${params.metricName}, ${params.metricCategory},
      ${params.valueBefore}, ${params.valueAfter}, ${changePct},
      NOW(), ${params.notes || null}
    )
  `);
  return { metricId: result.insertId };
}
async function feedbackLoop(outcomeId) {
  const [outcomeRows] = await db.execute(sql61`
    SELECT o.*, pr.pattern_type
    FROM outcome_registry o
    LEFT JOIN pattern_registry pr ON o.pattern_id = pr.pattern_id
    WHERE o.outcome_id = ${outcomeId}
  `);
  const outcome = outcomeRows[0];
  if (!outcome) return { effectivenessUpdated: false, successRateUpdated: false, trendImpactRecorded: false, registryUpdated: false };
  let effectivenessUpdated = false;
  try {
    const [existing] = await db.execute(sql61`
      SELECT effectiveness_id FROM strategy_effectiveness
      WHERE strategy_id = ${outcome.strategy_id} AND pattern_type = ${outcome.pattern_type || "unknown"}
      LIMIT 1
    `);
    if (existing.length > 0) {
      await db.execute(sql61`
        UPDATE strategy_effectiveness SET
          total_deployments = total_deployments + 1,
          successful_deployments = successful_deployments + ${outcome.outcome_status === "successful" ? 1 : 0},
          avg_signal_reduction_pct = (avg_signal_reduction_pct * (total_deployments - 1) + ${Number(outcome.signal_reduction_pct) || 0}) / total_deployments,
          avg_pressure_reduction_pct = (avg_pressure_reduction_pct * (total_deployments - 1) + ${Number(outcome.pressure_reduction_pct) || 0}) / total_deployments,
          avg_effectiveness_score = (avg_effectiveness_score * (total_deployments - 1) + ${outcome.overall_effectiveness_score || 0}) / total_deployments,
          avg_cost = (avg_cost * (total_deployments - 1) + ${Number(outcome.total_cost) || 0}) / total_deployments,
          last_calculated = NOW()
        WHERE strategy_id = ${outcome.strategy_id} AND pattern_type = ${outcome.pattern_type || "unknown"}
      `);
    } else {
      await db.execute(sql61`
        INSERT INTO strategy_effectiveness (
          strategy_id, pattern_type, jurisdiction,
          total_deployments, successful_deployments,
          avg_signal_reduction_pct, avg_pressure_reduction_pct,
          avg_effectiveness_score, avg_cost, last_calculated
        ) VALUES (
          ${outcome.strategy_id}, ${outcome.pattern_type || "unknown"}, 'general',
          1, ${outcome.outcome_status === "successful" ? 1 : 0},
          ${Number(outcome.signal_reduction_pct) || 0}, ${Number(outcome.pressure_reduction_pct) || 0},
          ${outcome.overall_effectiveness_score || 0}, ${Number(outcome.total_cost) || 0}, NOW()
        )
      `);
    }
    effectivenessUpdated = true;
  } catch (e) {
    console.error("[FeedbackLoop] effectiveness update error:", e);
  }
  let successRateUpdated = false;
  try {
    const [existingRate] = await db.execute(sql61`
      SELECT rate_id FROM strategy_success_rates
      WHERE strategy_id = ${outcome.strategy_id} AND pattern_type = ${outcome.pattern_type || "unknown"}
      LIMIT 1
    `);
    if (existingRate.length > 0) {
      const statusCol = outcome.outcome_status === "successful" ? "successful_outcomes" : outcome.outcome_status === "partial" ? "partial_outcomes" : "failed_outcomes";
      await db.execute(sql61`
        UPDATE strategy_success_rates SET
          total_attempts = total_attempts + 1,
          ${sql61.raw(statusCol)} = ${sql61.raw(statusCol)} + 1,
          last_updated = NOW()
        WHERE strategy_id = ${outcome.strategy_id} AND pattern_type = ${outcome.pattern_type || "unknown"}
      `);
    } else {
      await db.execute(sql61`
        INSERT INTO strategy_success_rates (
          strategy_id, pattern_type, total_attempts,
          successful_outcomes, partial_outcomes, failed_outcomes, last_updated
        ) VALUES (
          ${outcome.strategy_id}, ${outcome.pattern_type || "unknown"}, 1,
          ${outcome.outcome_status === "successful" ? 1 : 0},
          ${outcome.outcome_status === "partial" ? 1 : 0},
          ${outcome.outcome_status === "failed" ? 1 : 0},
          NOW()
        )
      `);
    }
    successRateUpdated = true;
  } catch (e) {
    console.error("[FeedbackLoop] success rate update error:", e);
  }
  let trendImpactRecorded = false;
  try {
    const impactId = randomUUID5();
    await db.execute(sql61`
      INSERT INTO trend_intervention_impacts (
        impact_id, pattern_id, intervention_id, intervention_date,
        pre_trend_classification, pre_pressure_index,
        post_trend_classification, post_pressure_index,
        pressure_reduction, confidence_of_impact
      ) VALUES (
        ${impactId}, ${outcome.pattern_id}, ${outcomeId}, CURDATE(),
        ${outcome.trend_before || "unknown"}, ${Number(outcome.pressure_before) || 0},
        ${outcome.trend_after || outcome.trend_before || "unknown"}, ${Number(outcome.pressure_after) || Number(outcome.pressure_before) || 0},
        ${(Number(outcome.pressure_before) || 0) - (Number(outcome.pressure_after) || 0)},
        ${Number(outcome.overall_effectiveness_score) || 0}
      )
    `);
    trendImpactRecorded = true;
  } catch (e) {
    console.error("[FeedbackLoop] trend impact error:", e);
  }
  let registryUpdated = false;
  try {
    const [rateRows] = await db.execute(sql61`
      SELECT SUM(total_attempts) as total, SUM(successful_outcomes) as successes
      FROM strategy_success_rates WHERE strategy_id = ${outcome.strategy_id}
    `);
    const r = rateRows[0];
    if (r && Number(r.total) > 0) {
      const newRate = Math.round(Number(r.successes) / Number(r.total) * 1e4) / 100;
      await db.execute(sql61`
        UPDATE strategy_registry SET
          historical_success_rate = ${newRate},
          last_updated_from_outcomes = CURDATE(),
          updated_at = NOW()
        WHERE strategy_id = ${outcome.strategy_id}
      `);
      registryUpdated = true;
    }
  } catch (e) {
    console.error("[FeedbackLoop] registry update error:", e);
  }
  return { effectivenessUpdated, successRateUpdated, trendImpactRecorded, registryUpdated };
}
async function getOutcomeDashboard() {
  const [outcomeRows] = await db.execute(sql61`
    SELECT o.outcome_id, o.path_id, o.strategy_id, o.pattern_id,
           o.outcome_status, o.outcome_description,
           o.signals_before, o.signals_after, o.signal_reduction_pct,
           o.pressure_before, o.pressure_after, o.pressure_reduction_pct,
           o.trend_before, o.trend_after,
           o.entities_affected, o.geographic_areas_affected,
           o.total_cost, o.cost_per_signal_reduced,
           o.overall_effectiveness_score, o.lessons_learned,
           o.created_at,
           sr.strategy_name, sr.strategy_type,
           pr.pattern_type AS pattern_name, pr.pattern_type
    FROM outcome_registry o
    LEFT JOIN strategy_registry sr ON o.strategy_id = sr.strategy_id
    LEFT JOIN pattern_registry pr ON o.pattern_id = pr.pattern_id
    ORDER BY o.created_at DESC
    LIMIT 50
  `);
  const [summaryRows] = await db.execute(sql61`
    SELECT
      COUNT(*) as total,
      SUM(CASE WHEN outcome_status = 'successful' THEN 1 ELSE 0 END) as successful,
      SUM(CASE WHEN outcome_status = 'partial' THEN 1 ELSE 0 END) as partial,
      SUM(CASE WHEN outcome_status = 'failed' THEN 1 ELSE 0 END) as failed,
      SUM(CASE WHEN outcome_status = 'in_progress' THEN 1 ELSE 0 END) as in_progress,
      AVG(overall_effectiveness_score) as avg_effectiveness,
      AVG(signal_reduction_pct) as avg_signal_reduction,
      AVG(pressure_reduction_pct) as avg_pressure_reduction,
      SUM(total_cost) as total_cost
    FROM outcome_registry
  `);
  const s = summaryRows[0] || {};
  return {
    outcomes: outcomeRows,
    summary: {
      total: Number(s.total) || 0,
      successful: Number(s.successful) || 0,
      partial: Number(s.partial) || 0,
      failed: Number(s.failed) || 0,
      inProgress: Number(s.in_progress) || 0,
      avgEffectiveness: Math.round(Number(s.avg_effectiveness) || 0),
      avgSignalReduction: Math.round((Number(s.avg_signal_reduction) || 0) * 100) / 100,
      avgPressureReduction: Math.round((Number(s.avg_pressure_reduction) || 0) * 100) / 100,
      totalCost: Number(s.total_cost) || 0
    }
  };
}
async function getEffectivenessReport() {
  const [rows2] = await db.execute(sql61`
    SELECT se.effectiveness_id, se.strategy_id, se.pattern_type, se.jurisdiction,
           se.total_deployments, se.successful_deployments,
           se.avg_signal_reduction_pct, se.avg_pressure_reduction_pct,
           se.avg_effectiveness_score, se.avg_cost, se.avg_duration_days,
           se.last_calculated,
           sr.strategy_name, sr.strategy_type
    FROM strategy_effectiveness se
    LEFT JOIN strategy_registry sr ON se.strategy_id = sr.strategy_id
    ORDER BY se.avg_effectiveness_score DESC
  `);
  return rows2;
}
async function getMissionControlOutcomeSummary() {
  const [summaryRows] = await db.execute(sql61`
    SELECT
      COUNT(*) as total,
      AVG(overall_effectiveness_score) as avg_effectiveness,
      SUM(GREATEST(0, COALESCE(signals_before, 0) - COALESCE(signals_after, 0))) as total_signals_reduced,
      SUM(COALESCE(total_cost, 0)) as total_cost
    FROM outcome_registry
  `);
  const s = summaryRows[0] || {};
  const [topRows] = await db.execute(sql61`
    SELECT sr.strategy_name, se.avg_effectiveness_score
    FROM strategy_effectiveness se
    JOIN strategy_registry sr ON se.strategy_id = sr.strategy_id
    ORDER BY se.avg_effectiveness_score DESC
    LIMIT 1
  `);
  const topStrategy = topRows[0] ? { name: topRows[0].strategy_name, score: topRows[0].avg_effectiveness_score } : null;
  const [recentRows] = await db.execute(sql61`
    SELECT pr.pattern_type AS pattern_name, o.outcome_status, o.overall_effectiveness_score
    FROM outcome_registry o
    LEFT JOIN pattern_registry pr ON o.pattern_id = pr.pattern_id
    ORDER BY o.created_at DESC
    LIMIT 5
  `);
  return {
    totalOutcomes: Number(s.total) || 0,
    avgEffectiveness: Math.round(Number(s.avg_effectiveness) || 0),
    totalSignalsReduced: Number(s.total_signals_reduced) || 0,
    totalCostInvested: Number(s.total_cost) || 0,
    topStrategy,
    recentOutcomes: recentRows.map((r) => ({
      patternName: r.pattern_name || "Unknown",
      status: r.outcome_status,
      score: r.overall_effectiveness_score || 0
    }))
  };
}

