  if (filters?.jurisdiction) query = sql67`${query} AND jurisdiction = ${filters.jurisdiction}`;
  if (filters?.templateType) query = sql67`${query} AND template_type = ${filters.templateType}`;
  if (filters?.difficultyLevel) query = sql67`${query} AND difficulty_level = ${filters.difficultyLevel}`;
  if (filters?.search) query = sql67`${query} AND template_name LIKE ${`%${filters.search}%`}`;
  query = sql67`${query} ORDER BY usage_count DESC, template_name ASC`;
