async function getTemplate(templateId) {
  const [rows2] = await db.execute(
    sql67`SELECT * FROM remedy_templates WHERE template_id = ${templateId}`
  );
  const row = rows2[0];
  if (!row) throw new Error(`Template not found: ${templateId}`);
  return {
    ...mapTemplateRow(row),
    templateBody: row.template_body
  };
}
async function findMatchingTemplates(claimType, jurisdiction, templateType) {
  let query = sql67`SELECT * FROM remedy_templates 
      WHERE is_active = 1 AND claim_type = ${claimType} AND jurisdiction = ${jurisdiction}`;
  if (templateType) query = sql67`${query} AND template_type = ${templateType}`;
  query = sql67`${query} ORDER BY usage_count DESC, success_rate DESC`;
  const [rows2] = await db.execute(query);
  let results = rows2.map(mapTemplateRow);
  if (results.length === 0 || jurisdiction !== "federal") {
    const [federalRows] = await db.execute(
      sql67`SELECT * FROM remedy_templates 
          WHERE is_active = 1 AND claim_type = ${claimType} AND jurisdiction = 'federal'
          ${templateType ? sql67`AND template_type = ${templateType}` : sql67``}
          ORDER BY usage_count DESC`
    );
    const federalResults = federalRows.map(mapTemplateRow);
    results = [...results, ...federalResults];
  }
  return results;
}
