async function enqueueGeneration(request) {
  const queueId = randomUUID9();
  await db.execute(
    sql67`INSERT INTO doc_generation_queue 
        (queue_id, template_id, case_id, pattern_id, strategy_path_id, priority, queue_status, requested_by, requested_at)
        VALUES (${queueId}, ${request.templateId || ""}, ${request.caseId || null}, ${request.patternId || null}, 
                ${request.strategyPathId || null},
                ${request.priority || 5}, 'pending', ${request.userId || null}, ${Date.now()})`
  );
  return queueId;
}
async function processQueue(limit = 10) {
  const [pending] = await db.execute(
    sql67`SELECT * FROM doc_generation_queue WHERE queue_status = 'pending' ORDER BY priority ASC, requested_at ASC LIMIT ${limit}`
  );
  let processed = 0;
  let errors = 0;
  for (const item of pending) {
    try {
      await db.execute(
        sql67`UPDATE doc_generation_queue SET queue_status = 'processing' WHERE queue_id = ${item.queue_id}`
      );
      if (item.template_id) {
        await generateDocument2(item.template_id, {}, {
          caseId: item.case_id,
          patternId: item.pattern_id,
          strategyPathId: item.strategy_path_id,
          userId: item.requested_by
        });
      } else if (item.pattern_id) {
        const [patternRows] = await db.execute(
          sql67`SELECT pattern_type FROM pattern_registry WHERE pattern_id = ${item.pattern_id} LIMIT 1`
        );
        const pattern = patternRows[0];
        if (pattern) {
          const templates = await findMatchingTemplates(pattern.pattern_type, "WA", "demand_letter");
          if (templates.length > 0) {
            await generateDocument2(templates[0].templateId, {}, {
              caseId: item.case_id,
              patternId: item.pattern_id,
              strategyPathId: item.strategy_path_id,
              userId: item.requested_by
            });
          }
        }
      }
      await db.execute(
        sql67`UPDATE doc_generation_queue SET queue_status = 'completed', processed_at = ${Date.now()} WHERE queue_id = ${item.queue_id}`
      );
      processed++;
    } catch (err) {
      await db.execute(
        sql67`UPDATE doc_generation_queue SET queue_status = 'failed', error_message = ${err.message || "Unknown error"} WHERE queue_id = ${item.queue_id}`
      );
      errors++;
    }
  }
  return { processed, errors };
}
async function getQueueStatus3() {
  const [statusRows] = await db.execute(
    sql67`SELECT queue_status, COUNT(*) as cnt FROM doc_generation_queue GROUP BY queue_status`
  );
  const statusMap = {};
  for (const r of statusRows) {
    statusMap[r.queue_status] = r.cnt;
  }
  const [recent] = await db.execute(
    sql67`SELECT * FROM doc_generation_queue ORDER BY requested_at DESC LIMIT 10`
  );
  return {
    pending: statusMap["pending"] || 0,
    processing: statusMap["processing"] || 0,
    completed: statusMap["completed"] || 0,
    failed: statusMap["failed"] || 0,
    recentItems: recent.map((r) => ({
      queueId: r.queue_id,
      caseId: r.case_id,
      patternId: r.pattern_id,
      templateId: r.template_id,
      strategyPathId: r.strategy_path_id,
      priority: r.priority,
      status: r.queue_status,
      createdAt: r.requested_at
    }))
  };
}
