// server/routers/coalition-advocacy-router.ts
import { z as z62 } from "zod";
init_db();
import { sql as sql75 } from "drizzle-orm";

// server/coalition-advocacy-service.ts
init_db();
import { sql as sql74 } from "drizzle-orm";
function genId2(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}
function safeParseJson(val) {
  if (Array.isArray(val)) return val;
  if (!val) return [];
  try {
    return JSON.parse(val);
  } catch {
    return [];
  }
}
async function matchAdvocacyTargets(patternId, opts) {
  const [patternRows] = await db.execute(
    sql74`SELECT * FROM pattern_registry WHERE pattern_id = ${patternId} LIMIT 1`
  );
  const pattern = patternRows[0];
  if (!pattern) throw new Error(`Pattern not found: ${patternId}`);
  const jurisdiction = opts?.jurisdiction || pattern.jurisdiction_scope || pattern.jurisdiction || "";
  const harmDomains = safeParseJson(pattern.harm_domains);
  const limit = opts?.limit || 20;
  let targetQuery = sql74`SELECT * FROM advocacy_targets WHERE 1=1`;
  if (jurisdiction) {
    targetQuery = sql74`SELECT * FROM advocacy_targets WHERE jurisdiction = ${jurisdiction} OR jurisdiction = 'federal' OR jurisdiction = 'national'`;
  }
  const [targetRows] = await db.execute(targetQuery);
  let targets = targetRows.map((t2) => ({
    targetId: t2.target_id,
    name: t2.name,
    organization: t2.organization || "",
    role: t2.role || "",
    jurisdiction: t2.jurisdiction || "",
    issueDomains: safeParseJson(t2.issue_domains),
    influenceScore: Number(t2.influence_score) || 0,
    publicVisibilityScore: Number(t2.public_visibility_score) || 0
  }));
  targets = targets.map((t2) => {
    let relevance = t2.influenceScore;
    const domainOverlap = t2.issueDomains.filter(
      (d) => harmDomains.some((h) => h.toLowerCase().includes(d.toLowerCase()) || d.toLowerCase().includes(h.toLowerCase()))
    ).length;
    relevance += domainOverlap * 15;
    if (t2.jurisdiction === jurisdiction) relevance += 10;
    return { ...t2, relevanceScore: relevance };
  }).sort((a, b) => b.relevanceScore - a.relevanceScore).slice(0, limit);
  let coalitionQuery = sql74`SELECT * FROM coalition_registry WHERE 1=1`;
  if (jurisdiction) {
    coalitionQuery = sql74`SELECT * FROM coalition_registry WHERE jurisdiction_scope = ${jurisdiction} OR jurisdiction_scope = 'national' OR jurisdiction_scope = 'federal'`;
  }
  const [coalitionRows] = await db.execute(coalitionQuery);
  let coalitions = coalitionRows.map((c) => ({
    coalitionId: c.coalition_id,
    coalitionName: c.coalition_name,
    coalitionType: c.coalition_type,
    jurisdictionScope: c.jurisdiction_scope || "",
    issueDomains: safeParseJson(c.issue_domains),
    credibilityScore: Number(c.credibility_score) || 0,
    verificationStatus: c.verification_status || "unverified"
  }));
  coalitions = coalitions.sort((a, b) => b.credibilityScore - a.credibilityScore).slice(0, limit);
  const [orgRows] = await db.execute(
    sql74`SELECT * FROM advocacy_organizations ORDER BY id LIMIT 20`
  );
  const orgs = orgRows.map((o) => ({
    coalitionId: `ORG-${o.id}`,
    coalitionName: o.name,
    coalitionType: o.org_type || "nonprofit",
    jurisdictionScope: o.jurisdiction || o.jurisdiction_scope || "",
    issueDomains: safeParseJson(o.focus_areas || o.issue_domains),
    credibilityScore: 70,
    verificationStatus: "verified"
  }));
  const allCoalitions = [...coalitions, ...orgs].slice(0, limit);
  return { targets, coalitions: allCoalitions };
}
async function activateCoalition(patternId, coalitionIds, actionType) {
  const now3 = Date.now();
  const actionIds = [];
  const [patternRows] = await db.execute(
    sql74`SELECT * FROM pattern_registry WHERE pattern_id = ${patternId} LIMIT 1`
  );
  const pattern = patternRows[0];
  let changeId = genId2("PCH");
  try {
    const [changeRows] = await db.execute(
      sql74`SELECT change_id FROM policy_change_registry WHERE pattern_type = ${pattern?.pattern_type || ""} ORDER BY created_at DESC LIMIT 1`
    );
    changeId = changeRows[0]?.change_id || changeId;
  } catch {
  }
  for (const cid of coalitionIds) {
    const actionId = genId2("ADV");
    actionIds.push(actionId);
    let orgName = cid;
    if (cid.startsWith("ORG-")) {
      const orgId = cid.replace("ORG-", "");
      const [orgRows] = await db.execute(sql74`SELECT name FROM advocacy_organizations WHERE id = ${orgId} LIMIT 1`);
      orgName = orgRows[0]?.name || cid;
    } else {
      const [coalRows] = await db.execute(sql74`SELECT coalition_name FROM coalition_registry WHERE coalition_id = ${cid} LIMIT 1`);
      orgName = coalRows[0]?.coalition_name || cid;
    }
    await db.execute(sql74`
      INSERT INTO advocacy_action_registry (action_id, change_id, organization_name, action_type,
        recipient_target, packet_generated, response_status, notes, created_at)
      VALUES (${actionId}, ${changeId}, ${orgName}, ${actionType},
        ${pattern?.pattern_name || patternId}, ${false}, 'pending',
        ${"Coalition activation for pattern " + patternId}, ${now3})
    `);
  }
  return { actionsCreated: actionIds.length, actionIds };
}
async function generateAdvocacyPackage(patternId) {
  const [patternRows] = await db.execute(
    sql74`SELECT * FROM pattern_registry WHERE pattern_id = ${patternId} LIMIT 1`
  );
  const pattern = patternRows[0];
  if (!pattern) throw new Error(`Pattern not found: ${patternId}`);
  let signals = [];
  try {
    const [signalRows] = await db.execute(
      sql74`SELECT * FROM detected_signals WHERE signal_type = ${pattern.pattern_type || ""} ORDER BY detection_timestamp DESC LIMIT 20`
    );
    signals = signalRows;
  } catch {
  }
  let trends = [];
  try {
    const [trendRows] = await db.execute(
      sql74`SELECT * FROM trend_registry WHERE pattern_id = ${patternId} ORDER BY created_at DESC LIMIT 5`
    );
    trends = trendRows;
  } catch {
  }
  const [outcomeRows] = await db.execute(
    sql74`SELECT * FROM outcome_registry WHERE pattern_id = ${patternId} ORDER BY created_at DESC LIMIT 10`
  );
  const outcomes = outcomeRows;
  const [reformRows] = await db.execute(
    sql74`SELECT * FROM reform_registry WHERE pattern_id = ${patternId} ORDER BY created_at DESC LIMIT 5`
  );
  const reforms = reformRows;
  const { targets, coalitions } = await matchAdvocacyTargets(patternId);
  const harmDomains = safeParseJson(pattern.harm_domains);
  const jurisdiction = pattern.jurisdiction_scope || pattern.jurisdiction || "Multi-jurisdiction";
  const executiveSummary = JSON.stringify({
    patternName: pattern.pattern_name || pattern.name,
    patternType: pattern.pattern_type,
    jurisdiction,
    urgency: pattern.severity_level || pattern.priority_level || "high",
    signalCount: signals.length,
    affectedDomains: harmDomains,
    callToAction: `Immediate attention required for ${pattern.pattern_name || "this pattern"} affecting ${harmDomains.join(", ")} in ${jurisdiction}`
  });
  const evidenceBrief = JSON.stringify({
    totalSignals: signals.length,
    jurisdictions: [...new Set(signals.map((s) => s.jurisdiction))],
    signalTypes: [...new Set(signals.map((s) => s.signal_type))],
    timespan: signals.length > 1 ? { earliest: signals[signals.length - 1]?.detected_at, latest: signals[0]?.detected_at } : null,
    keyFindings: signals.slice(0, 5).map((s) => ({
      signalId: s.signal_id,
      type: s.signal_type,
      jurisdiction: s.jurisdiction
    }))
  });
  const trendAnalysis = JSON.stringify({
    trends: trends.map((t2) => ({
      trendId: t2.trend_id,
      direction: t2.trend_direction || t2.direction,
      magnitude: t2.magnitude,
      period: t2.period,
      metric: t2.metric_name || t2.trend_type
    })),
    overallDirection: trends.length > 0 ? trends[0].trend_direction || trends[0].direction : "stable"
  });
  const humanImpactSection = JSON.stringify({
    affectedPopulations: harmDomains,
    geographicImpact: [...new Set(signals.map((s) => s.jurisdiction))],
    estimatedScope: `${signals.length} documented instances across ${new Set(signals.map((s) => s.jurisdiction)).size} jurisdictions`,
    outcomeHistory: outcomes.map((o) => ({
      type: o.outcome_type || o.intervention_type,
      status: o.status || o.outcome_status,
      jurisdiction: o.jurisdiction
    }))
  });
  const recommendedReforms = JSON.stringify({
    reforms: reforms.map((r) => ({
      title: r.reform_title,
      type: r.reform_type,
      description: r.reform_description,
      priority: r.priority_level
    }))
  });
  const supportingData = JSON.stringify({
    signalSummary: {
      total: signals.length,
      byType: signals.reduce((acc, s) => {
        acc[s.signal_type] = (acc[s.signal_type] || 0) + 1;
        return acc;
      }, {})
    },
    trendSummary: trends.length,
    outcomeSummary: outcomes.length,
    reformSummary: reforms.length
  });
  const packageId = genId2("ADVPKG");
  return {
    packageId,
    patternId,
    executiveSummary,
    evidenceBrief,
    trendAnalysis,
    humanImpactSection,
    recommendedReforms,
    supportingData,
    targets: targets.slice(0, 10),
    coalitions: coalitions.slice(0, 10)
  };
}
async function recordAdvocacyOutcome(patternId, coalitionId, outcomeType, description, impactScore) {
  const now3 = Date.now();
  const outcomeId = genId2("AO");
  if (coalitionId) {
    await db.execute(sql74`
      INSERT INTO advocacy_outcomes (outcome_id, pattern_id, coalition_id, outcome_type,
        description, impact_score, date_occurred, created_at)
      VALUES (${outcomeId}, ${patternId}, ${coalitionId}, ${outcomeType},
        ${description}, ${impactScore}, ${now3}, ${now3})
    `);
  } else {
    await db.execute(sql74`
      INSERT INTO advocacy_outcomes (outcome_id, pattern_id, outcome_type,
        description, impact_score, date_occurred, created_at)
      VALUES (${outcomeId}, ${patternId}, ${outcomeType},
        ${description}, ${impactScore}, ${now3}, ${now3})
    `);
  }
  if (impactScore >= 60) {
    const [patternRows] = await db.execute(
      sql74`SELECT pattern_type, jurisdiction_scope FROM pattern_registry WHERE pattern_id = ${patternId} LIMIT 1`
    );
    const pattern = patternRows[0];
    if (pattern) {
      const memId = genId2("MEM");
      await db.execute(sql74`
        INSERT INTO strategy_memory (memory_id, pattern_type, jurisdiction, intervention_type,
          success_score, confidence_score, notes, created_at)
        VALUES (${memId}, ${pattern.pattern_type || "advocacy"}, ${pattern.jurisdiction_scope || "national"},
          ${"advocacy_" + outcomeType},
          ${impactScore}, ${Math.min(impactScore, 100)},
          ${`Auto-recorded from advocacy outcome ${outcomeId}: ${description.substring(0, 200)}`}, ${now3})
      `);
    }
  }
  return outcomeId;
}
async function getCoalitionDashboard() {
  const [coalitionRows] = await db.execute(sql74`SELECT * FROM coalition_registry ORDER BY credibility_score DESC`);
  const coalitions = coalitionRows;
  const byType = {};
  const byVerification = {};
  coalitions.forEach((c) => {
    byType[c.coalition_type] = (byType[c.coalition_type] || 0) + 1;
    byVerification[c.verification_status] = (byVerification[c.verification_status] || 0) + 1;
  });
  const [targetCountRows] = await db.execute(sql74`SELECT COUNT(*) as cnt FROM advocacy_targets`);
  const totalTargets = Number(targetCountRows[0]?.cnt || 0);
  const [outcomeRows] = await db.execute(sql74`SELECT * FROM advocacy_outcomes ORDER BY date_occurred DESC LIMIT 50`);
  const outcomes = outcomeRows;
  const outcomesByType = {};
  outcomes.forEach((o) => {
    outcomesByType[o.outcome_type] = (outcomesByType[o.outcome_type] || 0) + 1;
  });
  const [orgCountRows] = await db.execute(sql74`SELECT COUNT(*) as cnt FROM advocacy_organizations`);
  const orgCount = Number(orgCountRows[0]?.cnt || 0);
  return {
    totalCoalitions: coalitions.length + orgCount,
    byType,
    byVerification,
    totalTargets,
    totalOutcomes: outcomes.length,
    outcomesByType,
    recentOutcomes: outcomes.slice(0, 10).map((o) => ({
      outcomeId: o.outcome_id,
      patternId: o.pattern_id,
      coalitionId: o.coalition_id,
      outcomeType: o.outcome_type,
      description: o.description,
      impactScore: Number(o.impact_score) || 0,
      dateOccurred: o.date_occurred ? Number(o.date_occurred) : null
    })),
    topCoalitions: coalitions.slice(0, 10).map((c) => ({
      coalitionId: c.coalition_id,
      coalitionName: c.coalition_name,
      coalitionType: c.coalition_type,
      jurisdictionScope: c.jurisdiction_scope,
      credibilityScore: Number(c.credibility_score) || 0,
      verificationStatus: c.verification_status
    }))
  };
}

