function scoreFeasibility(rule, evidenceScore, resources) {
  const minConf = Number(rule.minimum_evidence_confidence || 50);
  const evidenceAdequacy = evidenceScore >= minConf ? Math.min(100, 50 + (evidenceScore - minConf) / (100 - minConf) * 50) : Math.max(0, evidenceScore / minConf * 50);
  const estCost = Number(rule.estimated_cost || 0) + Number(rule.filing_fee || 0);
  const costFeasibility = estCost === 0 ? 100 : resources.budget >= estCost ? 100 : Math.max(0, resources.budget / estCost * 100);
  const reqDays = Number(rule.time_requirement_days || 90);
  const timeFeasibility = resources.timeAvailableDays >= reqDays ? 100 : Math.max(0, resources.timeAvailableDays / reqDays * 100);
  const prereqs = typeof rule.prerequisites === "string" ? JSON.parse(rule.prerequisites) : rule.prerequisites || [];
  const metPrereqs = prereqs.filter((p) => resources.prerequisitesMet.includes(p));
  const prerequisiteCompletion = prereqs.length === 0 ? 100 : metPrereqs.length / prereqs.length * 100;
  const riskFlagsArr = typeof rule.risk_flags === "string" ? JSON.parse(rule.risk_flags) : rule.risk_flags || [];
  const riskLevel = riskFlagsArr.length >= 3 ? "high" : riskFlagsArr.length >= 2 ? "medium" : "low";
  const overall = Math.round(
    evidenceAdequacy * 0.35 + costFeasibility * 0.25 + timeFeasibility * 0.2 + prerequisiteCompletion * 0.2
  );
  return {
    overall: Math.max(0, Math.min(100, overall)),
    evidenceAdequacy: Math.round(evidenceAdequacy),
    costFeasibility: Math.round(costFeasibility),
    timeFeasibility: Math.round(timeFeasibility),
    prerequisiteCompletion: Math.round(prerequisiteCompletion),
    riskLevel
  };
}
async function assessRemedyFeasibility(strategyType, evidenceScore, resources) {
  const [rows2] = await db.execute(
    sql79`SELECT * FROM remedy_feasibility_rules WHERE strategy_type = ${strategyType} LIMIT 1`
  );
  const rule = rows2[0];
  if (!rule) {
    return {
      strategyType,
      feasibilityScore: {
        overall: 0,
        evidenceAdequacy: 0,
        costFeasibility: 0,
        timeFeasibility: 0,
        prerequisiteCompletion: 0,
        riskLevel: "high"
      },
      viable: false,
      recommendedAlternative: null,
      resourceRequirements: {
        estimatedCost: 0,
        costRange: { low: 0, high: 0 },
        estimatedTimeDays: 0,
        timeRange: { low: 0, high: 0 },
        attorneyRequired: false,
        proSePossible: false,
        filingFee: 0,
        serviceRequired: "unknown"
      },
      unmetPrerequisites: [],
      riskFlags: [],
      complexityLevel: "unknown",
      successRateEstimate: "unknown"
    };
  }
  const score = scoreFeasibility(rule, evidenceScore, resources);
  const prereqs = typeof rule.prerequisites === "string" ? JSON.parse(rule.prerequisites) : rule.prerequisites || [];
  const unmetPrerequisites = prereqs.filter((p) => !resources.prerequisitesMet.includes(p));
  const riskFlags = typeof rule.risk_flags === "string" ? JSON.parse(rule.risk_flags) : rule.risk_flags || [];
  const viable = score.overall >= 50 && evidenceScore >= Number(rule.minimum_evidence_confidence || 50);
  return {
    strategyType,
    feasibilityScore: score,
    viable,
    recommendedAlternative: viable ? null : rule.alternative_path || null,
    resourceRequirements: {
      estimatedCost: Number(rule.estimated_cost || 0),
      costRange: { low: Number(rule.cost_range_low || 0), high: Number(rule.cost_range_high || 0) },
      estimatedTimeDays: Number(rule.time_requirement_days || 0),
      timeRange: { low: Number(rule.time_range_low || 0), high: Number(rule.time_range_high || 0) },
      attorneyRequired: Boolean(rule.attorney_required),
      proSePossible: Boolean(rule.pro_se_possible),
      filingFee: Number(rule.filing_fee || 0),
      serviceRequired: rule.service_required || "none"
    },
    unmetPrerequisites,
    riskFlags,
    complexityLevel: rule.complexity_level || "medium",
    successRateEstimate: rule.success_rate_estimate || "medium"
  };
}

// server/procedural-path-engine-service.ts
init_db();
import { sql as sql80 } from "drizzle-orm";
function parseStep(row) {
  return {
    stepNumber: Number(row.step_number),
    stepName: row.step_name,
    stepDescription: row.step_description || null,
    requiredDocuments: typeof row.required_documents === "string" ? JSON.parse(row.required_documents) : row.required_documents || [],
    estimatedDurationDays: Number(row.estimated_duration_days || 0),
    responsibleAgency: row.responsible_agency || null,
    nextStep: row.next_step || null,
    alternativeStep: row.alternative_step || null,
    filingFee: Number(row.filing_fee || 0),
    deadlineDays: row.deadline_days != null ? Number(row.deadline_days) : null,
    formNumber: row.form_number || null,
    onlinePortal: row.online_portal || null
  };
}
async function resolveProceduralPath2(claimType, jurisdiction) {
  const [rows2] = await db.execute(
    sql80`SELECT * FROM procedural_paths 
        WHERE claim_type = ${claimType} AND jurisdiction = ${jurisdiction}
        ORDER BY step_number ASC`
  );
  const steps = rows2.map(parseStep);
  if (steps.length === 0) {
    return {
      claimType,
      jurisdiction,
      steps: [],
      timeline: { totalDurationDays: 0, totalFilingFees: 0, phases: [] },
      criticalDeadlines: [],
      totalSteps: 0,
      hasAlternativePaths: false
    };
  }
  const timeline = calculateTimeline(steps);
  const criticalDeadlines = identifyCriticalDeadlines(steps);
  const hasAlternativePaths = steps.some((s) => s.alternativeStep !== null);
  return {
    claimType,
    jurisdiction,
    steps,
    timeline,
    criticalDeadlines,
    totalSteps: steps.length,
    hasAlternativePaths
  };
}
function calculateTimeline(steps) {
  let currentDay = 0;
  let totalFilingFees = 0;
  const phases = [];
  for (const step of steps) {
    const startDay = currentDay;
    const endDay = currentDay + step.estimatedDurationDays;
    phases.push({
      stepName: step.stepName,
      startDay,
      endDay,
      deadlineDays: step.deadlineDays
    });
    currentDay = endDay;
    totalFilingFees += step.filingFee;
  }
  return {
    totalDurationDays: currentDay,
    totalFilingFees,
    phases
  };
}
function identifyCriticalDeadlines(steps) {
  const deadlines2 = [];
  for (const step of steps) {
    if (step.deadlineDays != null) {
      const urgency = step.deadlineDays <= 30 ? "critical" : step.deadlineDays <= 90 ? "important" : "standard";
      deadlines2.push({
        stepNumber: step.stepNumber,
        stepName: step.stepName,
        deadlineDays: step.deadlineDays,
        description: `${step.stepName}: ${step.deadlineDays} days to complete`,
        urgency
      });
    }
  }
  deadlines2.sort((a, b) => a.deadlineDays - b.deadlineDays);
  return deadlines2;
}

// server/system-hardening-pipeline-service.ts
async function executePipeline(caseData) {
  const ecEvidence = caseData.evidence.map((e) => ({
    type: e.type,
    description: e.description,
    source: e.source || void 0,
    has_contradictions: e.has_contradictions,
    corroborated: e.corroborated
  }));
  const evidenceConfidence = await calculateEvidenceConfidence(caseData.claimType, ecEvidence);
  const cvEvidence = caseData.evidence.map((e) => ({
    type: e.type,
    description: e.description
  }));
  const claimValidation = await validateClaim(caseData.claimType, cvEvidence);
  const remedyFeasibility = await assessRemedyFeasibility(
    caseData.strategyType,
    evidenceConfidence.score,
    caseData.resources
  );
  const proceduralPath = await resolveProceduralPath2(
    caseData.claimType,
    caseData.jurisdiction
  );
  const engineOutputs = {
    evidenceConfidence,
    claimValidation,
    remedyFeasibility,
    proceduralPath
  };
  const synthesis = synthesizeResults(engineOutputs);
  const { requiredNextActions, alternativeStrategies } = ensureNoDeadEnds(
    engineOutputs,
    synthesis
  );
  const riskFlags = [
    ...remedyFeasibility.riskFlags,
    ...synthesis.verdict === "DEAD_END" ? ["no_viable_strategy"] : [],
    ...evidenceConfidence.score < 30 ? ["critically_low_evidence"] : [],
    ...claimValidation.completionPercentage < 25 ? ["minimal_legal_elements"] : []
  ];
  const viableStrategy = synthesis.verdict === "PROCEED" || synthesis.verdict === "CAUTION" ? caseData.strategyType : alternativeStrategies[0] || null;
  const overallConfidenceScore = synthesis.weightedTotal;
  const result = {
    caseId: caseData.caseId,
    claimType: caseData.claimType,
    jurisdiction: caseData.jurisdiction,
    strategyType: caseData.strategyType,
    overallConfidenceScore,
    viableStrategy,
    engineOutputs,
    synthesis,
    requiredNextActions,
    riskFlags,
    alternativeStrategies
  };
  return result;
}
function synthesizeResults(outputs) {
  const evidenceWeight = 0.4;
  const validationWeight = 0.3;
  const feasibilityWeight = 0.3;
  const evidenceScore = outputs.evidenceConfidence.score;
  const validationScore = outputs.claimValidation.completionPercentage;
  const feasibilityScore = outputs.remedyFeasibility.feasibilityScore.overall;
  const weightedTotal = Math.round(
    evidenceScore * evidenceWeight + validationScore * validationWeight + feasibilityScore * feasibilityWeight
  );
  let verdict;
  let explanation;
  if (weightedTotal >= 70 && outputs.remedyFeasibility.viable) {
    verdict = "PROCEED";
    explanation = `Strong case viability (${weightedTotal}/100). Evidence is sufficient, legal elements are largely met, and the selected strategy is feasible. Recommend proceeding with filing.`;
  } else if (weightedTotal >= 50) {
    verdict = "CAUTION";
    explanation = `Moderate case viability (${weightedTotal}/100). Some gaps exist in evidence or legal elements. Address identified gaps before proceeding.`;
  } else if (weightedTotal >= 25) {
    verdict = "INVESTIGATE";
    explanation = `Low case viability (${weightedTotal}/100). Significant evidence gaps and unmet legal elements. Focused investigation needed before any filing.`;
  } else {
    verdict = "DEAD_END";
    explanation = `Very low case viability (${weightedTotal}/100). Current evidence and resources are insufficient for the selected strategy. Consider alternative approaches.`;
  }
  return {
    evidenceWeight,
    validationWeight,
    feasibilityWeight,
    evidenceScore,
    validationScore,
    feasibilityScore,
    weightedTotal,
    verdict,
    explanation
  };
}
function ensureNoDeadEnds(outputs, synthesis) {
  const requiredNextActions = [];
  const alternativeStrategies = [];
  if (outputs.evidenceConfidence.requiredMissing.length > 0) {
    requiredNextActions.push(
      `Gather missing evidence: ${outputs.evidenceConfidence.requiredMissing.join(", ")}`
    );
  }
  if (outputs.claimValidation.missingElements.length > 0) {
    requiredNextActions.push(
      `Address missing legal elements: ${outputs.claimValidation.missingElements.join(", ")}`
    );
  }
  if (outputs.remedyFeasibility.unmetPrerequisites.length > 0) {
    requiredNextActions.push(
      `Complete prerequisites: ${outputs.remedyFeasibility.unmetPrerequisites.join(", ")}`
    );
  }
  if (outputs.proceduralPath.criticalDeadlines.length > 0) {
    const urgent = outputs.proceduralPath.criticalDeadlines.filter((d) => d.urgency === "critical");
    if (urgent.length > 0) {
      requiredNextActions.push(
        `URGENT deadlines: ${urgent.map((d) => `${d.stepName} (${d.deadlineDays} days)`).join(", ")}`
      );
    }
  }
  if (!outputs.remedyFeasibility.viable && outputs.remedyFeasibility.recommendedAlternative) {
    alternativeStrategies.push(outputs.remedyFeasibility.recommendedAlternative);
  }
  if (synthesis.verdict === "DEAD_END") {
    alternativeStrategies.push("evidence_gathering");
    alternativeStrategies.push("demand_letter");
    alternativeStrategies.push("mediation");
    requiredNextActions.push("Consider consulting with a legal aid attorney for case evaluation.");
  }
  if (requiredNextActions.length === 0) {
    requiredNextActions.push("Review procedural path and begin filing process.");
  }
  return { requiredNextActions, alternativeStrategies: [...new Set(alternativeStrategies)] };
}
async function savePipelineResult(result) {
  const [insertResult] = await db.execute(
    sql81`INSERT INTO system_hardening_pipeline 
      (case_id, evidence_confidence_score, evidence_confidence_details, claim_validation_results, remedy_feasibility_results, procedural_path_results, viable_strategy, required_next_actions, overall_confidence_score, risk_flags, alternative_strategies)
      VALUES (
        ${result.caseId},
        ${result.engineOutputs.evidenceConfidence.score},
        ${JSON.stringify(result.engineOutputs.evidenceConfidence)},
        ${JSON.stringify(result.engineOutputs.claimValidation)},
        ${JSON.stringify(result.engineOutputs.remedyFeasibility)},
        ${JSON.stringify(result.engineOutputs.proceduralPath)},
        ${result.viableStrategy},
        ${JSON.stringify(result.requiredNextActions)},
        ${result.overallConfidenceScore},
        ${JSON.stringify(result.riskFlags)},
        ${JSON.stringify(result.alternativeStrategies)}
      )`
  );
  return insertResult.insertId;
}
async function getPipelineHistory(caseId2) {
  const [rows2] = await db.execute(
    sql81`SELECT id, case_id, overall_confidence_score, viable_strategy, created_at 
        FROM system_hardening_pipeline 
        WHERE case_id = ${caseId2}
        ORDER BY created_at DESC
        LIMIT 20`
  );
  return rows2.map((r) => ({
    id: Number(r.id),
    caseId: r.case_id,
    overallConfidenceScore: Number(r.overall_confidence_score || 0),
    viableStrategy: r.viable_strategy,
    createdAt: r.created_at ? new Date(r.created_at).toISOString() : ""
  }));
}
async function getPipelineDetail2(id) {
  const [rows2] = await db.execute(
    sql81`SELECT * FROM system_hardening_pipeline WHERE id = ${id} LIMIT 1`
  );
  const row = rows2[0];
  if (!row) return null;
  const parseJSON = (val) => {
    if (!val) return {};
    return typeof val === "string" ? JSON.parse(val) : val;
  };
  return {
    caseId: row.case_id,
    claimType: "",
    jurisdiction: "",
    strategyType: "",
    overallConfidenceScore: Number(row.overall_confidence_score || 0),
    viableStrategy: row.viable_strategy,
    engineOutputs: {
      evidenceConfidence: parseJSON(row.evidence_confidence_details),
      claimValidation: parseJSON(row.claim_validation_results),
      remedyFeasibility: parseJSON(row.remedy_feasibility_results),
      proceduralPath: parseJSON(row.procedural_path_results)
    },
    synthesis: {
      evidenceWeight: 0.4,
      validationWeight: 0.3,
      feasibilityWeight: 0.3,
      evidenceScore: Number(row.evidence_confidence_score || 0),
      validationScore: 0,
      feasibilityScore: 0,
      weightedTotal: Number(row.overall_confidence_score || 0),
      verdict: Number(row.overall_confidence_score || 0) >= 70 ? "PROCEED" : Number(row.overall_confidence_score || 0) >= 50 ? "CAUTION" : Number(row.overall_confidence_score || 0) >= 25 ? "INVESTIGATE" : "DEAD_END",
      explanation: ""
    },
    requiredNextActions: parseJSON(row.required_next_actions) || [],
    riskFlags: parseJSON(row.risk_flags) || [],
    alternativeStrategies: parseJSON(row.alternative_strategies) || []
  };
}
async function getPipelineDashboard() {
  const [countRows] = await db.execute(
    sql81`SELECT COUNT(*) as cnt FROM system_hardening_pipeline`
  );
  const totalRuns = Number(countRows[0]?.cnt || 0);
  const [avgRows] = await db.execute(
    sql81`SELECT AVG(overall_confidence_score) as avg_score FROM system_hardening_pipeline`
  );
  const avgConfidenceScore = Math.round(Number(avgRows[0]?.avg_score || 0));
  const [verdictRows] = await db.execute(
    sql81`SELECT 
      CASE 
        WHEN overall_confidence_score >= 70 THEN 'PROCEED'
        WHEN overall_confidence_score >= 50 THEN 'CAUTION'
        WHEN overall_confidence_score >= 25 THEN 'INVESTIGATE'
        ELSE 'DEAD_END'
      END as verdict,
      COUNT(*) as cnt
    FROM system_hardening_pipeline
    GROUP BY verdict`
  );
  const verdictDistribution = {};
  for (const row of verdictRows) {
    verdictDistribution[row.verdict] = Number(row.cnt);
  }
  const [recentRows] = await db.execute(
    sql81`SELECT id, case_id, overall_confidence_score, viable_strategy, created_at 
        FROM system_hardening_pipeline 
        ORDER BY created_at DESC 
        LIMIT 5`
  );
  const recentRuns = recentRows.map((r) => ({
    id: Number(r.id),
    caseId: r.case_id,
    overallConfidenceScore: Number(r.overall_confidence_score || 0),
    viableStrategy: r.viable_strategy,
    createdAt: r.created_at ? new Date(r.created_at).toISOString() : ""
  }));
  return { totalRuns, avgConfidenceScore, verdictDistribution, recentRuns };
}

// server/routers/system-hardening-pipeline-router.ts
var resourceProfileSchema2 = z67.object({
  budget: z67.number(),
  timeAvailableDays: z67.number(),
  hasAttorney: z67.boolean(),
  prerequisitesMet: z67.array(z67.string())
});
var evidenceItemSchema3 = z67.object({
  type: z67.string(),
  description: z67.string().optional(),
  source: z67.string().optional(),
  has_contradictions: z67.boolean().optional(),
  corroborated: z67.boolean().optional()
});
var systemHardeningPipelineRouter = router({
  // Execute full pipeline
  execute: protectedProcedure.input(z67.object({
    caseId: z67.string(),
    claimType: z67.string(),
    jurisdiction: z67.string(),
    strategyType: z67.string(),
    evidence: z67.array(evidenceItemSchema3),
    resources: resourceProfileSchema2
  })).mutation(async ({ input }) => {
    const result = await executePipeline(input);
    return result;
  }),
  // Execute and save pipeline result
  executeAndSave: protectedProcedure.input(z67.object({
    caseId: z67.string(),
    claimType: z67.string(),
    jurisdiction: z67.string(),
    strategyType: z67.string(),
    evidence: z67.array(evidenceItemSchema3),
    resources: resourceProfileSchema2
  })).mutation(async ({ input }) => {
    const result = await executePipeline(input);
    const id = await savePipelineResult(result);
    return { id, result };
  }),
  // Get pipeline history for a case
  history: protectedProcedure.input(z67.object({ caseId: z67.string() })).query(async ({ input }) => {
    return getPipelineHistory(input.caseId);
  }),
  // Get pipeline detail by ID
  detail: protectedProcedure.input(z67.object({ id: z67.number() })).query(async ({ input }) => {
    return getPipelineDetail2(input.id);
  }),
  // Dashboard
  dashboard: protectedProcedure.query(async () => {
    return getPipelineDashboard();
  }),
  // Mission Control summary
  missionControlSummary: protectedProcedure.query(async () => {
    const dashboard = await getPipelineDashboard();
    return {
      total_runs: dashboard.totalRuns,
      avg_confidence_score: dashboard.avgConfidenceScore,
      verdict_distribution: dashboard.verdictDistribution,
      recent_runs: dashboard.recentRuns
    };
  })
});

