import { z as z69 } from "zod";

// server/engines/harm-index-service.ts
init_db();
import { sql as sql84 } from "drizzle-orm";
function classifyRisk(score) {
  if (score >= 81) return "Critical Harm Actor";
  if (score >= 61) return "High Risk Actor";
  if (score >= 41) return "Elevated Risk";
  if (score >= 21) return "Moderate Concern";
  return "Low Risk";
}
function normalizeLog(value, maxExpected) {
  if (value <= 0) return 0;
  const normalized = Math.log(value + 1) / Math.log(maxExpected + 1) * 100;
  return Math.min(100, Math.round(normalized * 100) / 100);
}
async function calculateHarmIndex() {
  const now3 = Date.now();
  const errors = [];
  let processed = 0;
  try {
    const entityCounts = await db.execute(sql84`
      SELECT normalizedEntity as entity_name, 
             COUNT(*) as complaint_count,
             COUNT(DISTINCT sourceDataset) as dataset_count
      FROM ingested_records 
      WHERE normalizedEntity IS NOT NULL AND normalizedEntity != ''
      GROUP BY normalizedEntity
      HAVING COUNT(*) >= 2
      ORDER BY COUNT(*) DESC
      LIMIT 500
    `);
    const litigationCounts = await db.execute(sql84`
      SELECT entity_name, COUNT(*) as lit_count 
      FROM litigation_registry 
      GROUP BY entity_name
    `);
    const litMap = /* @__PURE__ */ new Map();
    for (const row of litigationCounts[0]) {
      litMap.set((row.entity_name || "").toLowerCase(), Number(row.lit_count) || 0);
    }
    const signalCounts = await db.execute(sql84`
      SELECT entity_id as entity_name, COUNT(*) as signal_count
      FROM detected_signals
      WHERE signal_type = 'repeat_entity'
      GROUP BY entity_id
    `);
    const sigMap = /* @__PURE__ */ new Map();
    for (const row of signalCounts[0]) {
      sigMap.set((row.entity_name || "").toLowerCase(), Number(row.signal_count) || 0);
    }
    for (const row of entityCounts[0]) {
      const entityName = row.entity_name;
      if (!entityName) continue;
      const complaintCount = Number(row.complaint_count) || 0;
      const datasetCount = Number(row.dataset_count) || 0;
      const litigationCount = litMap.get(entityName.toLowerCase()) || 0;
      const signalCount = sigMap.get(entityName.toLowerCase()) || 0;
      const complaintScore = normalizeLog(complaintCount, 100);
      const litigationScore = normalizeLog(litigationCount, 20);
      const enforcementScore = normalizeLog(signalCount, 10);
      const geographicSpread = normalizeLog(datasetCount, 5) * 100 / 100;
      const patternAcceleration = signalCount > 0 ? Math.min(100, signalCount * 20) : 0;
      const harmScore = Math.round(
        (complaintScore * 0.25 + litigationScore * 0.25 + enforcementScore * 0.2 + geographicSpread * 0.15 + patternAcceleration * 0.15) * 100
      ) / 100;
      const riskClass = classifyRisk(harmScore);
      await db.execute(sql84`
        INSERT INTO harm_index_entities (entity_name, entity_type, first_detected, last_updated, created_at)
        VALUES (${entityName}, 'unknown', ${now3}, ${now3}, ${now3})
        ON DUPLICATE KEY UPDATE last_updated = ${now3}
      `);
      const entityResult = await db.execute(sql84`
        SELECT id FROM harm_index_entities WHERE entity_name = ${entityName} LIMIT 1
      `);
      const entityId = entityResult[0][0]?.id;
      if (!entityId) continue;
      await db.execute(sql84`
        INSERT INTO harm_index_scores 
        (entity_id, complaint_count, litigation_count, enforcement_count, 
         geographic_spread, severity_score, pattern_acceleration, 
         systemic_harm_score, risk_classification, calculated_at)
        VALUES (${entityId}, ${complaintCount}, ${litigationCount}, ${signalCount},
                ${geographicSpread}, ${complaintScore}, ${patternAcceleration},
                ${harmScore}, ${riskClass}, ${now3})
      `);
      await db.execute(sql84`
        INSERT INTO harm_index_history (entity_id, systemic_harm_score, risk_classification, timestamp)
        VALUES (${entityId}, ${harmScore}, ${riskClass}, ${now3})
      `);
      processed++;
    }
  } catch (err) {
    errors.push(err.message || "Unknown error during harm index calculation");
  }
  return { processed, errors };
}
async function getHarmIndexSummary() {
  const results = await db.execute(sql84`
    SELECT 
      e.id, e.entity_name, e.entity_type, e.industry_sector, e.jurisdiction,
      s.complaint_count, s.litigation_count, s.enforcement_count,
      s.geographic_spread, s.severity_score, s.pattern_acceleration,
      s.systemic_harm_score, s.risk_classification, s.calculated_at
    FROM harm_index_entities e
    JOIN harm_index_scores s ON s.entity_id = e.id
    WHERE s.id = (
      SELECT MAX(s2.id) FROM harm_index_scores s2 WHERE s2.entity_id = e.id
    )
    ORDER BY s.systemic_harm_score DESC
  `);
  const entities3 = results[0].map((r) => ({
    id: r.id,
    entityName: r.entity_name,
    entityType: r.entity_type || "unknown",
    industrySector: r.industry_sector,
    jurisdiction: r.jurisdiction,
    systemicHarmScore: Number(r.systemic_harm_score) || 0,
    riskClassification: r.risk_classification || "Low Risk",
    complaintCount: Number(r.complaint_count) || 0,
    litigationCount: Number(r.litigation_count) || 0,
    enforcementCount: Number(r.enforcement_count) || 0,
    geographicSpread: Number(r.geographic_spread) || 0,
    severityScore: Number(r.severity_score) || 0,
    patternAcceleration: Number(r.pattern_acceleration) || 0,
    lastUpdated: Number(r.calculated_at) || 0
  }));
  const criticalActors = entities3.filter((e) => e.systemicHarmScore >= 81).length;
  const highRiskActors = entities3.filter((e) => e.systemicHarmScore >= 61 && e.systemicHarmScore < 81).length;
  const elevatedRisk = entities3.filter((e) => e.systemicHarmScore >= 41 && e.systemicHarmScore < 61).length;
  const moderateConcern = entities3.filter((e) => e.systemicHarmScore >= 21 && e.systemicHarmScore < 41).length;
  const lowRisk = entities3.filter((e) => e.systemicHarmScore < 21).length;
  const avgScore = entities3.length > 0 ? Math.round(entities3.reduce((sum, e) => sum + e.systemicHarmScore, 0) / entities3.length * 100) / 100 : 0;
  return {
    totalEntities: entities3.length,
    criticalActors,
    highRiskActors,
    elevatedRisk,
    moderateConcern,
    lowRisk,
    avgHarmScore: avgScore,
    topEntities: entities3.slice(0, 50)
  };
}
async function getEntityHarmHistory(entityId) {
  const results = await db.execute(sql84`
    SELECT systemic_harm_score, risk_classification, timestamp
    FROM harm_index_history
    WHERE entity_id = ${entityId}
    ORDER BY timestamp ASC
  `);
  return results[0].map((r) => ({
    score: Number(r.systemic_harm_score) || 0,
    classification: r.risk_classification,
    timestamp: Number(r.timestamp)
  }));
}

// server/engines/litigation-correlation-service.ts
init_db();
init_signal_governance();
import { sql as sql85 } from "drizzle-orm";
async function runLitigationCorrelation() {
  const now3 = Date.now();
  const errors = [];
  let totalSignalsChecked = 0;
  let matchesFound = 0;
  let newLinksCreated = 0;
  let signalsBoosted = 0;
  try {
    const signals = await db.execute(sql85`
      SELECT signal_id as id, entity_id as entity, confidence_score as confidence, entity_role as entity_type, confidence_score as entity_confidence_score
      FROM detected_signals 
      WHERE signal_type = 'repeat_entity'
      ORDER BY detection_timestamp DESC
      LIMIT 500
    `);
    totalSignalsChecked = signals[0].length;
    for (const signal of signals[0]) {
      const entityName = signal.entity;
      if (!entityName) continue;
      const litMatches = await db.execute(sql85`
        SELECT id, entity_name, case_name, case_number, court, claim_type, 
               case_status, enforcement_agency, related_law
        FROM litigation_registry
        WHERE LOWER(entity_name) LIKE CONCAT('%', LOWER(${entityName}), '%')
           OR LOWER(${entityName}) LIKE CONCAT('%', LOWER(entity_name), '%')
        LIMIT 10
      `);
      if (litMatches[0].length > 0) {
        matchesFound++;
        for (const lit of litMatches[0]) {
          const nameA = entityName.toLowerCase();
          const nameB = (lit.entity_name || "").toLowerCase();
          const exactMatch = nameA === nameB;
          const confidence = exactMatch ? 0.95 : 0.7;
          const existingLink = await db.execute(sql85`
            SELECT id FROM entity_litigation_links 
            WHERE entity_id = ${signal.id} AND litigation_id = ${lit.id}
            LIMIT 1
          `);
          if (existingLink[0].length === 0) {
            const reason = exactMatch ? `Exact entity name match: "${entityName}" found in litigation registry` : `Partial entity name match: signal "${entityName}" correlates with litigation "${lit.entity_name}"`;
            await db.execute(sql85`
              INSERT INTO entity_litigation_links (entity_id, litigation_id, confidence_score, link_reason, created_at)
              VALUES (${signal.id}, ${lit.id}, ${confidence}, ${reason}, ${now3})
            `);
            newLinksCreated++;
          }
        }
        const currentConfidence = Number(signal.confidence) || 0.5;
        const boostedConfidence = Math.min(0.99, currentConfidence + 0.15);
        await updateGovernedSignal(signal.id, {
          confidenceScore: boostedConfidence,
          // @ts-ignore - caseId referenced from outer scope
          reason: `Litigation correlation boost: case ${typeof caseId !== "undefined" ? caseId : void 0}`
        });
        signalsBoosted++;
      }
    }
  } catch (err) {
    errors.push(err.message || "Unknown error during litigation correlation");
  }
  return { totalSignalsChecked, matchesFound, newLinksCreated, signalsBoosted, errors };
}
async function getEntityLitigationMatches(entityName) {
  const results = await db.execute(sql85`
    SELECT lr.id as litigation_id, lr.entity_name, lr.case_name, lr.case_number,
           lr.court, lr.claim_type, lr.case_status,
           ell.confidence_score, ell.link_reason
    FROM litigation_registry lr
    LEFT JOIN entity_litigation_links ell ON ell.litigation_id = lr.id
    WHERE LOWER(lr.entity_name) LIKE CONCAT('%', LOWER(${entityName}), '%')
       OR LOWER(${entityName}) LIKE CONCAT('%', LOWER(lr.entity_name), '%')
    ORDER BY ell.confidence_score DESC
  `);
  return results[0].map((r) => ({
    entityName: r.entity_name,
    litigation_id: r.litigation_id,
    caseName: r.case_name,
    caseNumber: r.case_number,
    court: r.court,
    claimType: r.claim_type,
    caseStatus: r.case_status,
    confidenceScore: Number(r.confidence_score) || 0,
    linkReason: r.link_reason || ""
  }));
}
async function getLitigationCorrelationSummary() {
  const totalLit = await db.execute(sql85`SELECT COUNT(*) as cnt FROM litigation_registry`);
  const totalLinks = await db.execute(sql85`SELECT COUNT(*) as cnt FROM entity_litigation_links`);
  const topCorrelated = await db.execute(sql85`
    SELECT lr.entity_name, COUNT(ell.id) as link_count, 
           MAX(ell.confidence_score) as max_confidence
    FROM litigation_registry lr
    JOIN entity_litigation_links ell ON ell.litigation_id = lr.id
    GROUP BY lr.entity_name
    ORDER BY link_count DESC
    LIMIT 20
  `);
  const recentCorrelations = await db.execute(sql85`
    SELECT ell.id, lr.entity_name, lr.case_name, ell.confidence_score, ell.link_reason, ell.created_at
    FROM entity_litigation_links ell
    JOIN litigation_registry lr ON lr.id = ell.litigation_id
    ORDER BY ell.created_at DESC
    LIMIT 20
  `);
  return {
    totalLitigationRecords: Number(totalLit[0][0]?.cnt) || 0,
    totalLinks: Number(totalLinks[0][0]?.cnt) || 0,
    topCorrelatedEntities: topCorrelated[0].map((r) => ({
      entityName: r.entity_name,
      link_count: Number(r.link_count),
      max_confidence: Number(r.max_confidence)
    })),
    recentCorrelations: recentCorrelations[0].map((r) => ({
      entityName: r.entity_name,
      caseName: r.case_name,
      confidence: Number(r.confidence_score),
      reason: r.link_reason,
      createdAt: Number(r.created_at)
    }))
  };
}

// server/engines/risk-forecast-service.ts
init_db();
import { sql as sql86 } from "drizzle-orm";
function classifyForecastRisk(score) {
  if (score >= 81) return "Systemic Crisis Risk";
  if (score >= 61) return "Escalation Likely";
  if (score >= 41) return "Emerging Risk";
  if (score >= 21) return "Watch";
  return "Stable";
}
async function generateRiskForecasts(horizonDays = 30) {
  const now3 = Date.now();
  const errors = [];
  let processed = 0;
  try {
    const entities3 = await db.execute(sql86`
      SELECT e.id, e.entity_name, e.industry_sector,
             s.systemic_harm_score, s.complaint_count, s.litigation_count,
             s.enforcement_count, s.geographic_spread, s.pattern_acceleration
      FROM harm_index_entities e
      JOIN harm_index_scores s ON s.entity_id = e.id
      WHERE s.id = (SELECT MAX(s2.id) FROM harm_index_scores s2 WHERE s2.entity_id = e.id)
      ORDER BY s.systemic_harm_score DESC
      LIMIT 200
    `);
    const thirtyDaysAgo = now3 - 30 * 24 * 60 * 60 * 1e3;
    const sixtyDaysAgo = now3 - 60 * 24 * 60 * 60 * 1e3;
    for (const entity of entities3[0]) {
      const entityName = entity.entity_name;
      const currentHarmScore = Number(entity.systemic_harm_score) || 0;
      const recentSignals = await db.execute(sql86`
        SELECT COUNT(*) as cnt FROM detected_signals 
        WHERE entity_id = ${entityName} AND detection_timestamp >= ${thirtyDaysAgo}
      `);
      const priorSignals = await db.execute(sql86`
        SELECT COUNT(*) as cnt FROM detected_signals 
        WHERE entity_id = ${entityName} AND detection_timestamp >= ${sixtyDaysAgo} AND detection_timestamp < ${thirtyDaysAgo}
      `);
      const recentCount = Number(recentSignals[0][0]?.cnt) || 0;
      const priorCount = Number(priorSignals[0][0]?.cnt) || 0;
      const signalGrowth = priorCount > 0 ? (recentCount - priorCount) / priorCount * 100 : recentCount > 0 ? 100 : 0;
      const complaintCount = Number(entity.complaint_count) || 0;
      const complaintAcceleration = Math.min(100, complaintCount * 2);
      const geoSpread = Number(entity.geographic_spread) || 0;
      const datasetSpread = await db.execute(sql86`
        SELECT COUNT(DISTINCT sourceDataset) as cnt FROM ingested_records 
        WHERE normalizedEntity = ${entityName}
      `);
      const entityConcentration = Math.min(100, (Number(datasetSpread[0][0]?.cnt) || 0) * 20);
      const enforcementCount = Number(entity.enforcement_count) || 0;
      const regulatoryGap = complaintCount > 0 ? Math.min(100, Math.max(0, (1 - enforcementCount / Math.max(1, complaintCount)) * 100)) : 0;
      const forecastScore = Math.round(
        (Math.min(100, Math.abs(signalGrowth)) * 0.3 + complaintAcceleration * 0.25 + geoSpread * 0.2 + entityConcentration * 0.15 + regulatoryGap * 0.1) * 100
      ) / 100;
      const riskCategory = classifyForecastRisk(forecastScore);
      const confidenceLevel = Math.min(0.95, 0.4 + complaintCount / 100 * 0.3 + recentCount / 10 * 0.25);
      const growthFactor = signalGrowth > 0 ? 1 + signalGrowth / 100 * 0.3 : 1;
      const predictedHarmScore = Math.min(100, Math.round(currentHarmScore * growthFactor * 100) / 100);
      await db.execute(sql86`
        INSERT INTO risk_forecasts 
        (pattern_id, forecast_date, forecast_horizon_days, predicted_signal_growth,
         predicted_pressure_index, predicted_geographic_spread, predicted_entity_count,
         risk_forecast_score, confidence_level, created_at)
        VALUES (NULL, ${now3}, ${horizonDays}, ${signalGrowth},
                ${complaintAcceleration}, ${geoSpread}, ${recentCount},
                ${forecastScore}, ${confidenceLevel}, ${now3})
      `);
      await db.execute(sql86`
        INSERT INTO entity_risk_projection 
        (entity_id, entity_name, industry_sector, current_harm_score, 
         predicted_harm_score, risk_category, projection_horizon_days, created_at)
        VALUES (${entity.id}, ${entityName}, ${entity.industry_sector},
                ${currentHarmScore}, ${predictedHarmScore}, ${riskCategory}, ${horizonDays}, ${now3})
      `);
      processed++;
    }
  } catch (err) {
    errors.push(err.message || "Unknown error during risk forecast generation");
  }
  return { processed, errors };
}
async function getRiskForecastSummary() {
  const projections = await db.execute(sql86`
    SELECT erp.id, erp.entity_name, erp.industry_sector, 
           erp.current_harm_score, erp.predicted_harm_score, erp.risk_category,
           erp.projection_horizon_days
    FROM entity_risk_projection erp
    WHERE erp.id = (
      SELECT MAX(erp2.id) FROM entity_risk_projection erp2 
      WHERE erp2.entity_name = erp.entity_name
    )
    ORDER BY erp.predicted_harm_score DESC
  `);
  const forecasts = projections[0].map((r) => ({
    patternId: null,
    entityName: r.entity_name,
    riskForecastScore: Number(r.predicted_harm_score) || 0,
    riskCategory: r.risk_category || "Stable",
    predictedSignalGrowth: 0,
    predictedPressureIndex: 0,
    predictedGeographicSpread: 0,
    predictedEntityCount: 0,
    confidenceLevel: 0
  }));
  const crisisRisk = forecasts.filter((f) => f.riskCategory === "Systemic Crisis Risk").length;
  const escalationLikely = forecasts.filter((f) => f.riskCategory === "Escalation Likely").length;
  const emergingRisk = forecasts.filter((f) => f.riskCategory === "Emerging Risk").length;
  const watch = forecasts.filter((f) => f.riskCategory === "Watch").length;
  const stable = forecasts.filter((f) => f.riskCategory === "Stable").length;
  const avgScore = forecasts.length > 0 ? Math.round(forecasts.reduce((sum, f) => sum + f.riskForecastScore, 0) / forecasts.length * 100) / 100 : 0;
  return {
    totalForecasts: forecasts.length,
    crisisRisk,
    escalationLikely,
    emergingRisk,
    watch,
    stable,
    avgForecastScore: avgScore,
    topRisks: forecasts.slice(0, 20),
    earlyWarnings: forecasts.filter((f) => f.riskForecastScore >= 80).slice(0, 10)
  };
}

// server/engines/harm-map-service.ts
init_db();
import { sql as sql87 } from "drizzle-orm";
async function generateHarmMap() {
  const now3 = Date.now();
  const errors = [];
  let nodesCreated = 0;
  let edgesCreated = 0;
  try {
    await db.execute(sql87`DELETE FROM harm_map_edges`);
    await db.execute(sql87`DELETE FROM harm_map_nodes`);
    const entities3 = await db.execute(sql87`
      SELECT e.id, e.entity_name, e.entity_type, e.industry_sector, e.jurisdiction,
             s.systemic_harm_score
      FROM harm_index_entities e
      LEFT JOIN harm_index_scores s ON s.entity_id = e.id 
        AND s.id = (SELECT MAX(s2.id) FROM harm_index_scores s2 WHERE s2.entity_id = e.id)
      ORDER BY s.systemic_harm_score DESC
      LIMIT 100
    `);
    const entityNodeMap = /* @__PURE__ */ new Map();
    for (const entity of entities3[0]) {
      const harmScore = Number(entity.systemic_harm_score) || 0;
      await db.execute(sql87`
        INSERT INTO harm_map_nodes 
        (node_type, node_label, entity_id, jurisdiction, industry_sector, harm_score, risk_score, status, created_at)
        VALUES ('entity', ${entity.entity_name}, ${entity.id}, ${entity.jurisdiction}, 
                ${entity.industry_sector}, ${harmScore}, ${harmScore}, 'active', ${now3})
      `);
      const nodeResult = await db.execute(sql87`SELECT LAST_INSERT_ID() as id`);
      const nodeId = nodeResult[0][0]?.id;
      if (nodeId) {
        entityNodeMap.set(entity.id, nodeId);
        nodesCreated++;
      }
    }
    const jurisdictions = await db.execute(sql87`
      SELECT DISTINCT jurisdiction FROM harm_index_entities 
      WHERE jurisdiction IS NOT NULL AND jurisdiction != ''
    `);
    const jurisdictionNodeMap = /* @__PURE__ */ new Map();
    for (const j of jurisdictions[0]) {
      await db.execute(sql87`
        INSERT INTO harm_map_nodes 
        (node_type, node_label, jurisdiction, harm_score, risk_score, status, created_at)
        VALUES ('jurisdiction', ${j.jurisdiction}, ${j.jurisdiction}, 0, 0, 'active', ${now3})
      `);
      const nodeResult = await db.execute(sql87`SELECT LAST_INSERT_ID() as id`);
      const nodeId = nodeResult[0][0]?.id;
      if (nodeId) {
        jurisdictionNodeMap.set(j.jurisdiction, nodeId);
        nodesCreated++;
      }
    }
    const industries = await db.execute(sql87`
      SELECT DISTINCT industry_sector FROM harm_index_entities 
      WHERE industry_sector IS NOT NULL AND industry_sector != ''
    `);
    const industryNodeMap = /* @__PURE__ */ new Map();
    for (const ind of industries[0]) {
      await db.execute(sql87`
        INSERT INTO harm_map_nodes 
        (node_type, node_label, industry_sector, harm_score, risk_score, status, created_at)
        VALUES ('industry', ${ind.industry_sector}, ${ind.industry_sector}, 0, 0, 'active', ${now3})
      `);
      const nodeResult = await db.execute(sql87`SELECT LAST_INSERT_ID() as id`);
      const nodeId = nodeResult[0][0]?.id;
      if (nodeId) {
        industryNodeMap.set(ind.industry_sector, nodeId);
        nodesCreated++;
      }
    }
    for (const entity of entities3[0]) {
      const entityNodeId = entityNodeMap.get(entity.id);
      if (!entityNodeId || !entity.jurisdiction) continue;
      const jurisdictionNodeId = jurisdictionNodeMap.get(entity.jurisdiction);
      if (!jurisdictionNodeId) continue;
      await db.execute(sql87`
        INSERT INTO harm_map_edges 
        (source_node_id, target_node_id, relationship_type, strength_score, evidence_count, created_at)
        VALUES (${entityNodeId}, ${jurisdictionNodeId}, 'shared_jurisdiction', 50, 1, ${now3})
      `);
      edgesCreated++;
    }
    for (const entity of entities3[0]) {
      const entityNodeId = entityNodeMap.get(entity.id);
      if (!entityNodeId || !entity.industry_sector) continue;
      const industryNodeId = industryNodeMap.get(entity.industry_sector);
      if (!industryNodeId) continue;
      await db.execute(sql87`
        INSERT INTO harm_map_edges 
        (source_node_id, target_node_id, relationship_type, strength_score, evidence_count, created_at)
        VALUES (${entityNodeId}, ${industryNodeId}, 'shared_industry', 50, 1, ${now3})
      `);
      edgesCreated++;
    }
    const litLinks = await db.execute(sql87`
      SELECT ell.entity_id, ell.litigation_id, ell.confidence_score,
             lr.entity_name as lit_entity
      FROM entity_litigation_links ell
      JOIN litigation_registry lr ON lr.id = ell.litigation_id
      LIMIT 200
    `);
    for (const link of litLinks[0]) {
      const sourceNode = await db.execute(sql87`
        SELECT id FROM harm_map_nodes WHERE entity_id = ${link.entity_id} LIMIT 1
      `);
      if (sourceNode[0].length === 0) continue;
      const targetNode = await db.execute(sql87`
        SELECT id FROM harm_map_nodes WHERE node_label = ${link.lit_entity} LIMIT 1
      `);
      if (targetNode[0].length === 0) continue;
      const sourceId = sourceNode[0][0].id;
      const targetId = targetNode[0][0].id;
      if (sourceId === targetId) continue;
      await db.execute(sql87`
        INSERT INTO harm_map_edges 
        (source_node_id, target_node_id, relationship_type, strength_score, evidence_count, created_at)
        VALUES (${sourceId}, ${targetId}, 'litigation_link', ${Number(link.confidence_score) * 100 || 50}, 1, ${now3})
      `);
      edgesCreated++;
    }
    const topSectors = industries[0].slice(0, 5).map((i) => i.industry_sector);
    const topEntities = entities3[0].slice(0, 5).map((e) => e.entity_name);
    await db.execute(sql87`
      INSERT INTO harm_map_snapshots 
      (snapshot_date, node_count, edge_count, top_risk_sectors, top_harm_entities, summary, created_at)
      VALUES (${now3}, ${nodesCreated}, ${edgesCreated}, 
              ${JSON.stringify(topSectors)}, ${JSON.stringify(topEntities)},
              ${`Generated ${nodesCreated} nodes and ${edgesCreated} edges`}, ${now3})
    `);
  } catch (err) {
    errors.push(err.message || "Unknown error during harm map generation");
  }
  return { nodesCreated, edgesCreated, errors };
}
async function getHarmMapData() {
  const nodes = await db.execute(sql87`
    SELECT id, node_type, node_label, entity_id, pattern_id, jurisdiction,
           industry_sector, harm_score, risk_score, status
    FROM harm_map_nodes
    ORDER BY harm_score DESC
  `);
  const edges = await db.execute(sql87`
    SELECT id, source_node_id, target_node_id, relationship_type, strength_score, evidence_count
    FROM harm_map_edges
  `);
  const snapshot = await db.execute(sql87`
    SELECT top_risk_sectors, top_harm_entities
    FROM harm_map_snapshots
    ORDER BY snapshot_date DESC LIMIT 1
  `);
  const snapshotData = snapshot[0][0];
  return {
    nodes: nodes[0].map((n) => ({
      id: n.id,
      nodeType: n.node_type,
      nodeLabel: n.node_label,
      entityId: n.entity_id,
      patternId: n.pattern_id,
      jurisdiction: n.jurisdiction,
      industrySector: n.industry_sector,
      harmScore: Number(n.harm_score) || 0,
      riskScore: Number(n.risk_score) || 0,
      status: n.status
    })),
    edges: edges[0].map((e) => ({
      id: e.id,
      sourceNodeId: e.source_node_id,
      targetNodeId: e.target_node_id,
      relationshipType: e.relationship_type,
      strengthScore: Number(e.strength_score) || 0,
      evidenceCount: Number(e.evidence_count) || 0
    })),
    summary: {
      nodeCount: nodes[0].length,
      edgeCount: edges[0].length,
      topRiskSectors: snapshotData?.top_risk_sectors ? typeof snapshotData.top_risk_sectors === "string" ? JSON.parse(snapshotData.top_risk_sectors) : snapshotData.top_risk_sectors : [],
      topHarmEntities: snapshotData?.top_harm_entities ? typeof snapshotData.top_harm_entities === "string" ? JSON.parse(snapshotData.top_harm_entities) : snapshotData.top_harm_entities : []
    }
  };
}

// server/engines/problem-interpreter-service.ts
init_db();
init_llm();
import { sql as sql88 } from "drizzle-orm";
var CLAIM_TYPES = [
  "housing_discrimination",
  "employment_discrimination",
  "consumer_fraud",
  "insurance_bad_faith",
  "medical_malpractice",
  "police_misconduct",
  "wage_theft",
  "landlord_tenant",
  "debt_collection_abuse",
  "predatory_lending",
  "environmental_harm",
  "product_liability",
  "civil_rights_violation",
  "family_law",
  "immigration",
  "workers_compensation",
  "social_security_disability",
  "veterans_benefits",
  "education_rights",
  "elder_abuse",
  "disability_discrimination",
  "retaliation",
  "whistleblower",
  "government_benefits"
];
async function startIntakeSession(userId, rawStory) {
  const now3 = Date.now();
  const systemPrompt = `You are a legal intake specialist. Analyze the user's story and identify:
1. The most likely jurisdiction (state/federal)
2. Up to 3 potential legal claim types from this list: ${CLAIM_TYPES.join(", ")}
3. For each claim type, provide confidence (0-1), reasoning, and supporting keywords from the story.

Respond in JSON format:
{
  "jurisdiction": "string",
  "claims": [
    {
      "claim_type": "string",
      "confidence": number,
      "reasoning": "string",
      "supporting_keywords": ["string"]
    }
  ]
}`;
  let jurisdictionGuess = "Unknown";
  let claimCandidates = [];
  let overallConfidence = 0;
  try {
    const response = await invokeLLM({
      messages: [
        { role: "system", content: systemPrompt },
        { role: "user", content: rawStory }
      ],
      response_format: {
        type: "json_schema",
        json_schema: {
          name: "intake_analysis",
          strict: true,
          schema: {
            type: "object",
            properties: {
              jurisdiction: { type: "string", description: "Likely jurisdiction" },
              claims: {
                type: "array",
                items: {
                  type: "object",
                  properties: {
                    claim_type: { type: "string" },
                    confidence: { type: "number" },
                    reasoning: { type: "string" },
                    supporting_keywords: { type: "array", items: { type: "string" } }
                  },
                  required: ["claim_type", "confidence", "reasoning", "supporting_keywords"],
                  additionalProperties: false
                }
              }
            },
            required: ["jurisdiction", "claims"],
            additionalProperties: false
          }
        }
      }
    });
    const parsed = JSON.parse(response.choices[0].message.content || "{}");
    jurisdictionGuess = parsed.jurisdiction || "Unknown";
    claimCandidates = (parsed.claims || []).map((c) => ({
      claimType: c.claim_type,
      confidence: c.confidence,
      reasoning: c.reasoning,
      supportingKeywords: c.supporting_keywords || []
    }));
    overallConfidence = claimCandidates.length > 0 ? claimCandidates[0].confidence : 0;
  } catch (err) {
    const storyLower = rawStory.toLowerCase();
    const keywordMap = {
      housing_discrimination: ["landlord", "eviction", "rent", "housing", "apartment", "lease", "tenant"],
      employment_discrimination: ["fired", "employer", "job", "workplace", "discrimination", "harass"],
      consumer_fraud: ["scam", "fraud", "deceived", "misrepresent", "refund", "purchase"],
      insurance_bad_faith: ["insurance", "claim denied", "coverage", "policy", "adjuster"],
      wage_theft: ["wages", "overtime", "unpaid", "paycheck", "minimum wage"],
      debt_collection_abuse: ["debt collector", "collection", "harassing calls", "credit"],
      landlord_tenant: ["landlord", "repair", "deposit", "habitability", "mold"]
    };
    for (const [claimType, keywords] of Object.entries(keywordMap)) {
      const matchCount = keywords.filter((k) => storyLower.includes(k)).length;
      if (matchCount >= 2) {
        claimCandidates.push({
          claimType,
          confidence: Math.min(0.9, matchCount * 0.2),
          reasoning: `Keyword matches: ${keywords.filter((k) => storyLower.includes(k)).join(", ")}`,
          supportingKeywords: keywords.filter((k) => storyLower.includes(k))
        });
      }
    }
    claimCandidates.sort((a, b) => b.confidence - a.confidence);
    claimCandidates = claimCandidates.slice(0, 3);
    overallConfidence = claimCandidates.length > 0 ? claimCandidates[0].confidence : 0;
  }
  await db.execute(sql88`
    INSERT INTO problem_intake_sessions 
    (user_id, raw_story, jurisdiction_guess, claim_candidates, confidence_score, status, created_at, updated_at)
    VALUES (${userId}, ${rawStory}, ${jurisdictionGuess}, 
            ${JSON.stringify(claimCandidates)}, ${overallConfidence}, 'analyzed', ${now3}, ${now3})
  `);
  const sessionResult = await db.execute(sql88`SELECT LAST_INSERT_ID() as id`);
  const sessionId = sessionResult[0][0]?.id;
  for (const claim of claimCandidates) {
    await db.execute(sql88`
      INSERT INTO interpreter_claim_matches 
      (session_id, claim_type, confidence_score, reasoning_summary, supporting_keywords, created_at)
      VALUES (${sessionId}, ${claim.claimType}, ${claim.confidence}, 
              ${claim.reasoning}, ${JSON.stringify(claim.supportingKeywords)}, ${now3})
    `);
  }
  return {
    id: sessionId,
    rawStory,
    jurisdictionGuess,
    claimCandidates,
    selectedClaim: null,
    confidenceScore: overallConfidence,
    status: "analyzed",
    createdAt: now3
  };
}
