// server/engines/case-link-service.ts
init_db();
import { sql as sql89 } from "drizzle-orm";
import crypto6 from "crypto";
async function generateShareableLink(caseId2, generatedBy, accessLevel = "summary", expiresInDays = 30, permissions = {}) {
  const now3 = Date.now();
  const token = crypto6.randomBytes(32).toString("hex");
  const expiresAt = expiresInDays ? now3 + expiresInDays * 24 * 60 * 60 * 1e3 : null;
  const perms = {
    allowEvidence: permissions.allowEvidence ?? false,
    allowNames: permissions.allowNames ?? true,
    allowFinancials: permissions.allowFinancials ?? false,
    allowDocuments: permissions.allowDocuments ?? false,
    allowPatternLinks: permissions.allowPatternLinks ?? true
  };
  await db.execute(sql89`
    INSERT INTO shareable_case_links 
    (case_id, generated_by, access_level, token, expires_at, view_count, created_at)
    VALUES (${caseId2}, ${generatedBy}, ${accessLevel}, ${token}, ${expiresAt}, 0, ${now3})
  `);
  const linkResult = await db.execute(sql89`SELECT LAST_INSERT_ID() as id`);
  const linkId = linkResult[0][0]?.id;
  await db.execute(sql89`
    INSERT INTO case_share_permissions 
    (case_id, allow_evidence, allow_names, allow_financials, allow_documents, allow_pattern_links, created_at)
    VALUES (${caseId2}, ${perms.allowEvidence}, ${perms.allowNames}, ${perms.allowFinancials}, 
            ${perms.allowDocuments}, ${perms.allowPatternLinks}, ${now3})
  `);
  return {
    id: linkId,
    caseId: caseId2,
    token,
    accessLevel,
    expiresAt,
    viewCount: 0,
    createdAt: now3,
    lastViewedAt: null,
    permissions: perms
  };
}
async function accessSharedCase(token, viewerIp = null, viewerUserAgent = null) {
  const now3 = Date.now();
  const linkResult = await db.execute(sql89`
    SELECT id, case_id, access_level, expires_at, view_count
    FROM shareable_case_links
    WHERE token = ${token}
    LIMIT 1
  `);
  const link = linkResult[0][0];
  if (!link) return { error: "Invalid or expired link" };
  if (link.expires_at && Number(link.expires_at) < now3) {
    return { error: "This link has expired" };
  }
  const permResult = await db.execute(sql89`
    SELECT allow_evidence, allow_names, allow_financials, allow_documents, allow_pattern_links
    FROM case_share_permissions
    WHERE case_id = ${link.case_id}
    ORDER BY created_at DESC LIMIT 1
  `);
  const perm = permResult[0][0] || {};
  const permissions = {
    allowEvidence: !!perm.allow_evidence,
    allowNames: perm.allow_names !== false,
    allowFinancials: !!perm.allow_financials,
    allowDocuments: !!perm.allow_documents,
    allowPatternLinks: perm.allow_pattern_links !== false
  };
  const caseResult = await db.execute(sql89`
    SELECT name, description, pipelineType, domain
    FROM cases WHERE id = ${link.case_id} LIMIT 1
  `);
  const caseData = caseResult[0][0];
  if (!caseData) return { error: "Case not found" };
  let findings7 = [];
  if (link.access_level !== "summary") {
    const findingsResult = await db.execute(sql89`
      SELECT id, title, severity, status, summary
      FROM findings WHERE caseId = ${link.case_id}
      ORDER BY severity DESC LIMIT 20
    `);
    findings7 = findingsResult[0].map((f) => ({
      title: f.title,
      severity: f.severity,
      status: f.status,
      summary: permissions.allowNames ? f.summary : "[Redacted]"
    }));
  }
  let entitiesData = [];
  if (permissions.allowNames) {
    const entitiesResult = await db.execute(sql89`
      SELECT name, type, description FROM entities 
      WHERE caseId = ${link.case_id} LIMIT 30
    `);
    entitiesData = entitiesResult[0].map((e) => ({
      name: e.name,
      type: e.type,
      description: e.description
    }));
  }
  await db.execute(sql89`
    INSERT INTO shareable_case_views (link_id, viewer_ip, viewer_user_agent, viewer_type, viewed_at)
    VALUES (${link.id}, ${viewerIp}, ${viewerUserAgent}, 'external', ${now3})
  `);
  await db.execute(sql89`
    UPDATE shareable_case_links 
    SET view_count = view_count + 1, last_viewed_at = ${now3}
    WHERE id = ${link.id}
  `);
  return {
    caseName: caseData.name,
    caseDescription: caseData.description,
    claimType: caseData.pipelineType,
    jurisdiction: caseData.domain,
    accessLevel: link.access_level,
    permissions,
    findings: findings7,
    entities: entitiesData,
    timeline: []
  };
}
async function getCaseShareLinks(caseId2) {
  const results = await db.execute(sql89`
    SELECT id, case_id, access_level, token, expires_at, view_count, created_at, last_viewed_at
    FROM shareable_case_links
    WHERE case_id = ${caseId2}
    ORDER BY created_at DESC
  `);
  return results[0].map((r) => ({
    id: r.id,
    caseId: r.case_id,
    token: r.token,
    accessLevel: r.access_level,
    expiresAt: r.expires_at ? Number(r.expires_at) : null,
    viewCount: Number(r.view_count) || 0,
    createdAt: Number(r.created_at),
    lastViewedAt: r.last_viewed_at ? Number(r.last_viewed_at) : null,
    permissions: { allowEvidence: false, allowNames: true, allowFinancials: false, allowDocuments: false, allowPatternLinks: true }
  }));
}
async function revokeShareableLink(linkId) {
  await db.execute(sql89`
    UPDATE shareable_case_links SET expires_at = ${Date.now() - 1e3} WHERE id = ${linkId}
  `);
  return true;
}
async function getShareAnalytics(caseId2) {
  const now3 = Date.now();
  const links = await db.execute(sql89`
    SELECT id, expires_at, view_count FROM shareable_case_links WHERE case_id = ${caseId2}
  `);
  const totalLinks = links[0].length;
  const activeLinks = links[0].filter((l) => !l.expires_at || Number(l.expires_at) > now3).length;
  const totalViews = links[0].reduce((sum, l) => sum + (Number(l.view_count) || 0), 0);
  const recentViews = await db.execute(sql89`
    SELECT sv.viewed_at, sv.viewer_type, sv.viewer_ip, scl.access_level
    FROM shareable_case_views sv
    JOIN shareable_case_links scl ON scl.id = sv.link_id
    WHERE scl.case_id = ${caseId2}
    ORDER BY sv.viewed_at DESC
    LIMIT 20
  `);
  return {
    totalLinks,
    activeLinks,
    totalViews,
    recentViews: recentViews[0].map((v) => ({
      viewedAt: Number(v.viewed_at),
      viewerType: v.viewer_type,
      accessLevel: v.access_level
    }))
  };
}

// server/engines/attorney-match-service.ts
init_db();
import { sql as sql90 } from "drizzle-orm";
async function findMatchingAttorneys(request) {
  const now3 = Date.now();
  const attorneys = await db.execute(sql90`
    SELECT id, name, firm_name, bar_number, jurisdiction, practice_areas,
           years_experience, accepts_contingency, accepts_pro_bono, accepts_new_clients,
           contact_email, website
    FROM attorney_registry
    WHERE accepts_new_clients = TRUE
    ORDER BY years_experience DESC
  `);
  const matches = [];
  for (const row of attorneys[0]) {
    const practiceAreas = row.practice_areas ? typeof row.practice_areas === "string" ? JSON.parse(row.practice_areas) : row.practice_areas : [];
    const attorney = {
      id: row.id,
      name: row.name,
      firmName: row.firm_name,
      barNumber: row.bar_number,
      jurisdiction: row.jurisdiction,
      practiceAreas,
      yearsExperience: Number(row.years_experience) || 0,
      acceptsContingency: !!row.accepts_contingency,
      acceptsProBono: !!row.accepts_pro_bono,
      acceptsNewClients: !!row.accepts_new_clients,
      contactEmail: row.contact_email,
      website: row.website
    };
    if (request.needsContingency && !attorney.acceptsContingency) continue;
    if (request.needsProBono && !attorney.acceptsProBono) continue;
    const claimNormalized = request.claimType.toLowerCase().replace(/_/g, " ");
    const practiceMatch = practiceAreas.some((pa) => {
      const paNorm = pa.toLowerCase().replace(/_/g, " ");
      return paNorm.includes(claimNormalized) || claimNormalized.includes(paNorm) || paNorm.split(" ").some((w) => claimNormalized.includes(w));
    });
    const practiceMatchScore = practiceMatch ? 85 + Math.min(15, attorney.yearsExperience) : practiceAreas.length > 0 ? 20 : 10;
    const jurisdictionMatch = attorney.jurisdiction && request.jurisdiction && (attorney.jurisdiction.toLowerCase() === request.jurisdiction.toLowerCase() || attorney.jurisdiction.toLowerCase().includes(request.jurisdiction.toLowerCase()) || request.jurisdiction.toLowerCase().includes(attorney.jurisdiction.toLowerCase()));
    const jurisdictionMatchScore = jurisdictionMatch ? 90 : attorney.jurisdiction?.toLowerCase().includes("federal") ? 50 : 20;
    let damagesMatchScore = 50;
    if (request.estimatedDamages) {
      if (request.estimatedDamages > 1e5 && attorney.yearsExperience >= 10) damagesMatchScore = 90;
      else if (request.estimatedDamages > 25e3 && attorney.yearsExperience >= 5) damagesMatchScore = 80;
      else if (request.estimatedDamages <= 25e3) damagesMatchScore = 70;
      else damagesMatchScore = 40;
    }
    const patternMatchScore = practiceMatch ? 80 : 30;
    const matchScore = Math.round(
      (practiceMatchScore * 0.35 + jurisdictionMatchScore * 0.3 + damagesMatchScore * 0.2 + patternMatchScore * 0.15) * 100
    ) / 100;
    matches.push({
      attorney,
      matchScore,
      practiceMatchScore,
      jurisdictionMatchScore,
      damagesMatchScore,
      patternMatchScore
    });
    await db.execute(sql90`
      INSERT INTO attorney_case_match 
      (case_id, attorney_id, match_score, practice_match_score, jurisdiction_match_score,
       damages_match_score, pattern_match_score, created_at)
      VALUES (${request.caseId}, ${attorney.id}, ${matchScore}, ${practiceMatchScore},
              ${jurisdictionMatchScore}, ${damagesMatchScore}, ${patternMatchScore}, ${now3})
    `);
  }
  matches.sort((a, b) => b.matchScore - a.matchScore);
  return matches.slice(0, 10);
}
async function addAttorney(attorney) {
  const now3 = Date.now();
  await db.execute(sql90`
    INSERT INTO attorney_registry 
    (name, firm_name, bar_number, jurisdiction, practice_areas, years_experience,
     accepts_contingency, accepts_pro_bono, accepts_new_clients, contact_email, website, created_at)
    VALUES (${attorney.name}, ${attorney.firmName}, ${attorney.barNumber}, ${attorney.jurisdiction},
            ${JSON.stringify(attorney.practiceAreas)}, ${attorney.yearsExperience},
            ${attorney.acceptsContingency}, ${attorney.acceptsProBono}, ${attorney.acceptsNewClients},
            ${attorney.contactEmail}, ${attorney.website}, ${now3})
  `);
  const result = await db.execute(sql90`SELECT LAST_INSERT_ID() as id`);
  return result[0][0]?.id;
}
