async function getMatchAnalytics() {
  const totalAttorneys = await db.execute(sql90`SELECT COUNT(*) as cnt FROM attorney_registry`);
  const totalMatches = await db.execute(sql90`SELECT COUNT(*) as cnt FROM attorney_case_match`);
  const avgScore = await db.execute(sql90`SELECT AVG(match_score) as avg FROM attorney_case_match`);
  const outcomes = await db.execute(sql90`
    SELECT 
      COUNT(*) as total,
      SUM(CASE WHEN contact_made = TRUE THEN 1 ELSE 0 END) as contacted,
      SUM(CASE WHEN representation_accepted = TRUE THEN 1 ELSE 0 END) as accepted
    FROM attorney_outcomes
  `);
  const outcomeRow = outcomes[0][0] || {};
  const total = Number(outcomeRow.total) || 0;
  return {
    totalAttorneys: Number(totalAttorneys[0][0]?.cnt) || 0,
    totalMatches: Number(totalMatches[0][0]?.cnt) || 0,
    avgMatchScore: Number(avgScore[0][0]?.avg) || 0,
    contactRate: total > 0 ? (Number(outcomeRow.contacted) || 0) / total * 100 : 0,
    acceptanceRate: total > 0 ? (Number(outcomeRow.accepted) || 0) / total * 100 : 0
  };
}

