async function detectRepeatLitigationPatterns() {
  const signals = [];
  const ninetyDaysAgo = new Date(Date.now() - 90 * 24 * 60 * 60 * 1e3).toISOString().split("T")[0];
  const repeatDefendants = await db.select({
    defendantName: federalLitigationCases.defendantName,
    caseCount: sql94`COUNT(*)`.as("case_count"),
    courts: sql94`COUNT(DISTINCT ${federalLitigationCases.courtName})`.as("courts"),
    caseTypes: sql94`GROUP_CONCAT(DISTINCT ${federalLitigationCases.caseType})`.as("case_types")
  }).from(federalLitigationCases).where(and37(
    sql94`${federalLitigationCases.defendantName} IS NOT NULL`,
    // @ts-ignore pre-existing type mismatch
    gte8(federalLitigationCases.filingDate, ninetyDaysAgo)
  )).groupBy(federalLitigationCases.defendantName).having(sql94`COUNT(*) >= 3`);
  for (const def of repeatDefendants) {
    if (!def.defendantName) continue;
    signals.push({
      signalType: "repeat_litigation_pattern",
      entity: def.defendantName,
      description: `${def.defendantName} named as defendant in ${def.caseCount} lawsuits across ${def.courts} courts in 90 days`,
      confidence: Math.min(95, 50 + def.caseCount * 8),
      metadata: {
        caseCount: def.caseCount,
        courts: def.courts,
        caseTypes: def.caseTypes,
        windowDays: 90
      }
    });
  }
  return signals;
}
async function detectClassActions() {
  const signals = [];
  const classActions = await db.select().from(federalLitigationCases).where(sql94`(
      LOWER(${federalLitigationCases.caseType}) LIKE '%class action%'
      OR LOWER(${federalLitigationCases.natureOfSuit}) LIKE '%class action%'
      OR LOWER(${federalLitigationCases.caseType}) LIKE '%multi-district%'
      OR LOWER(${federalLitigationCases.caseType}) LIKE '%mdl%'
    )`).orderBy(desc27(federalLitigationCases.filingDate)).limit(50);
  for (const ca of classActions) {
    const entity = ca.defendantName || ca.plaintiffName || "Unknown";
    signals.push({
      signalType: "class_action_filed",
      entity,
      description: `Class action filed: ${ca.plaintiffName || "Plaintiffs"} v. ${ca.defendantName || "Defendant"} in ${ca.courtName || "federal court"}`,
      confidence: 85,
      metadata: {
        caseId: ca.caseId,
        courtName: ca.courtName,
        natureOfSuit: ca.natureOfSuit,
        filingDate: ca.filingDate,
        sourceUrl: ca.sourceUrl
      }
    });
  }
  return signals;
}
async function detectCaseOutcomes() {
  const signals = [];
  const settlements = await db.select().from(federalLitigationCases).where(sql94`LOWER(${federalLitigationCases.caseStatus}) LIKE '%settl%'`).orderBy(desc27(federalLitigationCases.filingDate)).limit(30);
  for (const s of settlements) {
    signals.push({
      signalType: "case_settlement",
      entity: s.defendantName || s.plaintiffName || "Unknown",
      description: `Case settled: ${s.plaintiffName || "Plaintiff"} v. ${s.defendantName || "Defendant"} \u2014 ${s.courtName || "court"}`,
      confidence: 75,
      metadata: { caseId: s.caseId, courtName: s.courtName, caseStatus: s.caseStatus }
    });
  }
  const dismissals = await db.select().from(federalLitigationCases).where(sql94`LOWER(${federalLitigationCases.caseStatus}) LIKE '%dismiss%'`).orderBy(desc27(federalLitigationCases.filingDate)).limit(30);
  for (const d of dismissals) {
    signals.push({
      signalType: "case_dismissed",
      entity: d.defendantName || d.plaintiffName || "Unknown",
      description: `Case dismissed: ${d.plaintiffName || "Plaintiff"} v. ${d.defendantName || "Defendant"} \u2014 ${d.courtName || "court"}`,
      confidence: 70,
      metadata: { caseId: d.caseId, courtName: d.courtName, caseStatus: d.caseStatus }
    });
  }
  return signals;
}
async function getLitigationStats() {
  const [stats] = await db.select({
    totalCases: sql94`COUNT(*)`.as("total_cases"),
    uniqueDefendants: sql94`COUNT(DISTINCT ${federalLitigationCases.defendantName})`.as("unique_defendants"),
    uniqueCourts: sql94`COUNT(DISTINCT ${federalLitigationCases.courtName})`.as("unique_courts"),
    uniqueJurisdictions: sql94`COUNT(DISTINCT ${federalLitigationCases.jurisdiction})`.as("unique_jurisdictions")
  }).from(federalLitigationCases);
  return stats;
}
async function getRecentFilings(limit = 20) {
  return db.select().from(federalLitigationCases).orderBy(desc27(federalLitigationCases.filingDate)).limit(limit);
}
async function getCasesByDefendant(defendantName) {
  return db.select().from(federalLitigationCases).where(sql94`${federalLitigationCases.defendantName} LIKE ${`%${defendantName}%`}`).orderBy(desc27(federalLitigationCases.filingDate));
}
async function getCaseOutcomeBreakdown() {
  return db.select({
    caseStatus: federalLitigationCases.caseStatus,
    count: sql94`COUNT(*)`.as("count")
  }).from(federalLitigationCases).where(sql94`${federalLitigationCases.caseStatus} IS NOT NULL`).groupBy(federalLitigationCases.caseStatus).orderBy(desc27(sql94`count`));
}
async function runLitigationSignalDetection() {
  const [repeat, classActions, outcomes] = await Promise.all([
    detectRepeatLitigationPatterns(),
    detectClassActions(),
    detectCaseOutcomes()
  ]);
  return [...repeat, ...classActions, ...outcomes];
}

