// server/engines/systemic-risk-forecast.ts
init_db();
init_schema();
import { eq as eq66, desc as desc45, sql as sql112, and as and53, isNotNull as isNotNull2 } from "drizzle-orm";
function classifyRiskLevel(score) {
  if (score >= 80) return "critical";
  if (score >= 60) return "high";
  if (score >= 40) return "elevated";
  if (score >= 20) return "moderate";
  return "low";
}
function assignScenarioLabel(riskLevel, drivers) {
  if (riskLevel === "critical") {
    if (drivers.includes("enforcement_silence")) return "Regulatory Collapse";
    if (drivers.includes("complaint_acceleration")) return "Consumer Crisis";
    if (drivers.includes("litigation_surge")) return "Legal Cascade";
    return "Systemic Failure";
  }
  if (riskLevel === "high") {
    if (drivers.includes("trend_acceleration")) return "Accelerating Harm";
    if (drivers.includes("geographic_spread")) return "Contagion Risk";
    return "Escalation Warning";
  }
  if (riskLevel === "elevated") return "Watch Zone";
  if (riskLevel === "moderate") return "Early Signal";
  return "Baseline";
}
var RISK_WEIGHTS = {
  complaintVolume: 0.2,
  complaintAcceleration: 0.15,
  litigationVolume: 0.15,
  enforcementActivity: 0.15,
  trendPressure: 0.2,
  geographicSpread: 0.15
};
function calculateRiskScore(inputs) {
  const normalized = {
    complaintVolume: Math.min(100, inputs.complaintVolume * 2),
    complaintAcceleration: Math.min(100, inputs.complaintAcceleration * 10),
    litigationVolume: Math.min(100, inputs.litigationVolume * 5),
    enforcementActivity: inputs.enforcementActivity > 0 ? Math.min(100, 30 + inputs.enforcementActivity * 15) : 0,
    trendPressure: Math.min(100, inputs.trendPressure),
    geographicSpread: Math.min(100, inputs.geographicSpread * 10)
  };
  let score = 0;
  for (const [key2, weight] of Object.entries(RISK_WEIGHTS)) {
    score += normalized[key2] * weight;
  }
  return Math.min(100, Math.round(score));
}
async function forecastPatternRisk(patternId, windowDays = 90) {
  const patterns3 = await db.select().from(patternRegistry).where(eq66(patternRegistry.id, patternId)).limit(1);
  const pattern = patterns3[0];
  const signals = await db.select().from(detectedSignals).where(and53(eq66(detectedSignals.patternTypeId, patternId), isNotNull2(detectedSignals.signalId)));
  const trends = await db.select().from(trendPressureMetrics).where(eq66(trendPressureMetrics.patternId, patternId)).orderBy(desc45(trendPressureMetrics.calculatedAt)).limit(1);
  const complaintSignals = signals.filter((s) => (s.signalType || "").includes("repeat_entity") || (s.signalType || "").includes("complaint"));
  const litigationSignals = signals.filter((s) => (s.signalType || "").includes("litigation"));
  const enforcementSignals = signals.filter((s) => (s.signalType || "").includes("enforcement"));
  const jurisdictions = new Set(signals.map((s) => s.jurisdictionScope).filter(Boolean));
  const now3 = Date.now();
  const thirtyDaysAgo = now3 - 30 * 864e5;
  const sixtyDaysAgo = now3 - 60 * 864e5;
  const recentSignals = signals.filter((s) => s.detectionTimestamp >= thirtyDaysAgo);
  const olderSignals = signals.filter((s) => s.detectionTimestamp >= sixtyDaysAgo && s.detectionTimestamp < thirtyDaysAgo);
  const acceleration = olderSignals.length > 0 ? (recentSignals.length - olderSignals.length) / olderSignals.length : recentSignals.length > 0 ? 1 : 0;
  const riskInputs = {
    complaintVolume: complaintSignals.length,
    complaintAcceleration: acceleration,
    litigationVolume: litigationSignals.length,
    enforcementActivity: enforcementSignals.length,
    // @ts-ignore pre-existing type mismatch
    trendPressure: trends[0]?.pressureScore || 0,
    geographicSpread: jurisdictions.size
  };
  const riskScore = calculateRiskScore(riskInputs);
  const riskLevel = classifyRiskLevel(riskScore);
  const drivers = [];
  if (riskInputs.complaintVolume > 10) drivers.push("complaint_volume");
  if (acceleration > 0.5) drivers.push("complaint_acceleration");
  if (riskInputs.litigationVolume > 2) drivers.push("litigation_surge");
  if (riskInputs.enforcementActivity === 0 && riskInputs.complaintVolume > 5) drivers.push("enforcement_silence");
  if (riskInputs.trendPressure > 60) drivers.push("trend_acceleration");
  if (jurisdictions.size > 3) drivers.push("geographic_spread");
  const scenarioLabel = assignScenarioLabel(riskLevel, drivers);
  const escalationDays = riskScore >= 80 ? Math.round(windowDays * 0.3) : riskScore >= 60 ? Math.round(windowDays * 0.6) : riskScore >= 40 ? windowDays : null;
  const predictedEscalationDate = escalationDays ? now3 + escalationDays * 864e5 : null;
  const nowTs = Date.now();
  await db.delete(systemicRiskForecasts).where(
    and53(
      eq66(systemicRiskForecasts.forecastScope, "pattern"),
      eq66(systemicRiskForecasts.scopeId, patternId),
      eq66(systemicRiskForecasts.forecastWindowDays, windowDays)
    )
  );
  await db.insert(systemicRiskForecasts).values({
    forecastScope: "pattern",
    scopeId: patternId,
    scopeName: pattern?.patternName || `Pattern #${patternId}`,
    scopeType: pattern?.patternType || null,
    // @ts-ignore pre-existing type mismatch
    jurisdiction: pattern?.jurisdiction || null,
    forecastWindowDays: windowDays,
    riskScore,
    riskLevel,
    forecastType: "pattern_risk",
    scenarioLabel,
    primaryDrivers: JSON.stringify(drivers),
    confidenceScore: Math.min(100, 40 + signals.length * 3),
    predictedEscalationDate,
    createdAt: nowTs,
    updatedAt: nowTs
  });
  const [forecast] = await db.select().from(systemicRiskForecasts).where(and53(
    eq66(systemicRiskForecasts.forecastScope, "pattern"),
    eq66(systemicRiskForecasts.scopeId, patternId),
    eq66(systemicRiskForecasts.forecastWindowDays, windowDays)
  )).orderBy(desc45(systemicRiskForecasts.id)).limit(1);
  if (forecast) {
    for (const [key2, value] of Object.entries(riskInputs)) {
      await db.insert(forecastInputs).values({
        forecastId: forecast.id,
        inputType: key2,
        inputName: key2.replace(/([A-Z])/g, " $1").trim(),
        inputValue: value,
        weight: RISK_WEIGHTS[key2] || 0,
        createdAt: nowTs
      });
    }
    await db.insert(riskForecastHistory).values({
      // @ts-ignore pre-existing type mismatch
      forecastId: forecast.id,
      riskScore,
      riskLevel,
      capturedAt: nowTs,
      changeReason: "Initial forecast generation"
    });
  }
  return forecast;
}
async function forecastEntityRisk(entityName, windowDays = 90) {
  const signals = await db.select().from(detectedSignals).where(and53(eq66(detectedSignals.entityId, entityName), isNotNull2(detectedSignals.signalId)));
  const jurisdictions = new Set(signals.map((s) => s.jurisdictionScope).filter(Boolean));
  const now3 = Date.now();
  const thirtyDaysAgo = now3 - 30 * 864e5;
  const recentSignals = signals.filter((s) => s.detectionTimestamp >= thirtyDaysAgo);
  const olderSignals = signals.filter((s) => s.detectionTimestamp < thirtyDaysAgo);
  const acceleration = olderSignals.length > 0 ? (recentSignals.length - olderSignals.length) / olderSignals.length : recentSignals.length > 0 ? 1 : 0;
  const riskInputs = {
    complaintVolume: signals.filter((s) => (s.signalType || "").includes("repeat") || (s.signalType || "").includes("complaint")).length,
    complaintAcceleration: acceleration,
    litigationVolume: signals.filter((s) => (s.signalType || "").includes("litigation")).length,
    enforcementActivity: signals.filter((s) => (s.signalType || "").includes("enforcement")).length,
    trendPressure: Math.min(100, signals.length * 5),
    geographicSpread: jurisdictions.size
  };
  const riskScore = calculateRiskScore(riskInputs);
  const riskLevel = classifyRiskLevel(riskScore);
  const drivers = [];
  if (riskInputs.complaintVolume > 5) drivers.push("complaint_volume");
  if (acceleration > 0.3) drivers.push("complaint_acceleration");
  const scenarioLabel = assignScenarioLabel(riskLevel, drivers);
  const nowTs = Date.now();
  await db.delete(systemicRiskForecasts).where(
    and53(
      eq66(systemicRiskForecasts.forecastScope, "entity"),
      eq66(systemicRiskForecasts.scopeName, entityName),
      eq66(systemicRiskForecasts.forecastWindowDays, windowDays)
    )
  );
  await db.insert(systemicRiskForecasts).values({
    forecastScope: "entity",
    scopeId: null,
    scopeName: entityName,
    scopeType: "entity",
    jurisdiction: null,
    forecastWindowDays: windowDays,
    riskScore,
    riskLevel,
    forecastType: "entity_risk",
    scenarioLabel,
    primaryDrivers: JSON.stringify(drivers),
    confidenceScore: Math.min(100, 30 + signals.length * 4),
    predictedEscalationDate: null,
    createdAt: nowTs,
    updatedAt: nowTs
  });
  const [forecast] = await db.select().from(systemicRiskForecasts).where(and53(
    eq66(systemicRiskForecasts.forecastScope, "entity"),
    eq66(systemicRiskForecasts.scopeName, entityName),
    eq66(systemicRiskForecasts.forecastWindowDays, windowDays)
  )).orderBy(desc45(systemicRiskForecasts.id)).limit(1);
  return forecast;
}
async function compareForecastWindows(scope, scopeId, scopeName) {
  const whereClause = scopeId ? and53(eq66(systemicRiskForecasts.forecastScope, scope), eq66(systemicRiskForecasts.scopeId, scopeId)) : and53(eq66(systemicRiskForecasts.forecastScope, scope), eq66(systemicRiskForecasts.scopeName, scopeName));
  return db.select().from(systemicRiskForecasts).where(whereClause).orderBy(systemicRiskForecasts.forecastWindowDays);
}
async function generateForecastReport(scope, scopeId, scopeName) {
  const forecasts = await compareForecastWindows(scope, scopeId, scopeName);
  const forecastEntries = forecasts.map((f) => ({
    windowDays: f.forecastWindowDays,
    riskScore: f.riskScore || 0,
    riskLevel: f.riskLevel || "low",
    scenarioLabel: f.scenarioLabel,
    drivers: (() => {
      try {
        return JSON.parse(f.primaryDrivers || "[]");
      } catch {
        return [];
      }
    })(),
    confidenceScore: f.confidenceScore || 0,
    predictedEscalationDate: f.predictedEscalationDate ? new Date(f.predictedEscalationDate).toISOString().split("T")[0] : null
  }));
  const maxRisk = Math.max(...forecastEntries.map((f) => f.riskScore), 0);
  const maxLevel = classifyRiskLevel(maxRisk);
  const summary = forecastEntries.length > 0 ? `${scopeName}: Peak risk score ${maxRisk}/100 (${maxLevel}) across ${forecastEntries.length} forecast windows. ${forecastEntries.filter((f) => f.riskScore >= 60).length} windows at high/critical risk.` : `${scopeName}: No forecasts generated yet.`;
  return {
    scope,
    scopeName,
    forecasts: forecastEntries,
    summary,
    generatedAt: (/* @__PURE__ */ new Date()).toISOString()
  };
}
async function getForecastStats() {
  const [total] = await db.select({ count: sql112`COUNT(*)` }).from(systemicRiskForecasts);
  const [critical] = await db.select({ count: sql112`COUNT(*)` }).from(systemicRiskForecasts).where(eq66(systemicRiskForecasts.riskLevel, "critical"));
  const [high] = await db.select({ count: sql112`COUNT(*)` }).from(systemicRiskForecasts).where(eq66(systemicRiskForecasts.riskLevel, "high"));
  const [avgRisk] = await db.select({ avg: sql112`AVG(${systemicRiskForecasts.riskScore})` }).from(systemicRiskForecasts);
  return {
    totalForecasts: total?.count || 0,
    criticalForecasts: critical?.count || 0,
    highRiskForecasts: high?.count || 0,
    avgRiskScore: Math.round(avgRisk?.avg || 0)
  };
}
async function listForecasts(scope, limit = 50) {
  const query = scope ? db.select().from(systemicRiskForecasts).where(eq66(systemicRiskForecasts.forecastScope, scope)) : db.select().from(systemicRiskForecasts);
  return query.orderBy(desc45(systemicRiskForecasts.riskScore)).limit(limit);
}

// server/engines/public-alerting.ts
init_db();
init_schema();
import { eq as eq67, desc as desc46, sql as sql113, and as and54, gte as gte19 } from "drizzle-orm";
async function createSubscription(params) {
  const now3 = Date.now();
  await db.insert(alertSubscriptions).values({
    userId: params.userId,
    subscriptionType: params.subscriptionType,
    targetId: params.targetId || null,
    targetScope: params.targetName,
    alertFrequency: params.alertFrequency || "immediate",
    isPaused: 0,
    createdAt: now3,
    updatedAt: now3
  });
  const [sub] = await db.select().from(alertSubscriptions).where(and54(
    eq67(alertSubscriptions.userId, params.userId),
    eq67(alertSubscriptions.targetScope, params.targetName),
    eq67(alertSubscriptions.subscriptionType, params.subscriptionType)
  )).orderBy(desc46(alertSubscriptions.id)).limit(1);
  return sub;
}
async function listUserSubscriptions(userId) {
  return db.select().from(alertSubscriptions).where(and54(eq67(alertSubscriptions.userId, userId), eq67(alertSubscriptions.isPaused, 0))).orderBy(desc46(alertSubscriptions.createdAt));
}
async function toggleSubscription(subscriptionId, isActive) {
  await db.update(alertSubscriptions).set({ isPaused: isActive ? 0 : 1, updatedAt: Date.now() }).where(eq67(alertSubscriptions.id, subscriptionId));
}
async function deleteSubscription(subscriptionId) {
  await db.delete(alertSubscriptions).where(eq67(alertSubscriptions.id, subscriptionId));
}
async function checkAlertTriggers() {
  const activeSubs = await db.select().from(alertSubscriptions).where(eq67(alertSubscriptions.isPaused, 0));
  const newEvents = [];
  const now3 = Date.now();
  const oneDayAgo = new Date(now3 - 864e5);
  const oneDayAgoMs = now3 - 864e5;
  for (const sub of activeSubs) {
    let shouldTrigger = false;
    let message = "";
    let riskScore = 0;
    if (sub.subscriptionType === "entity") {
      const newSignals = await db.select({ count: sql113`COUNT(*)` }).from(detectedSignals).where(and54(
        eq67(detectedSignals.signalType, sub.targetScope ?? ""),
        gte19(detectedSignals.detectionTimestamp, oneDayAgo)
      ));
      const signalCount = newSignals[0]?.count || 0;
      if (signalCount > 0) {
        shouldTrigger = true;
        message = `Entity scope "${sub.targetScope}" has ${signalCount} new signals`;
        riskScore = Math.min(100, signalCount * 10);
      }
    }
    if (sub.subscriptionType === "industry") {
      const newSignals = await db.select({ count: sql113`COUNT(*)` }).from(detectedSignals).where(and54(
        eq67(detectedSignals.datasetId, sub.industry ?? ""),
        gte19(detectedSignals.detectionTimestamp, oneDayAgo)
      ));
      const signalCount = newSignals[0]?.count || 0;
      if (signalCount > 0) {
        shouldTrigger = true;
        message = `Industry "${sub.industry}" has ${signalCount} new signals`;
        riskScore = Math.min(100, signalCount * 5);
      }
    }
    if (sub.subscriptionType === "jurisdiction") {
      const newSignals = await db.select({ count: sql113`COUNT(*)` }).from(detectedSignals).where(and54(
        eq67(detectedSignals.jurisdictionScope, sub.jurisdiction ?? ""),
        gte19(detectedSignals.detectionTimestamp, oneDayAgo)
      ));
      const signalCount = newSignals[0]?.count || 0;
      if (signalCount > 0) {
        shouldTrigger = true;
        message = `Jurisdiction "${sub.jurisdiction}" has ${signalCount} new signals`;
        riskScore = Math.min(100, signalCount * 5);
      }
    }
    if (shouldTrigger) {
      const recentEvent = await db.select().from(alertEvents).where(and54(
        eq67(alertEvents.subscriptionId, sub.id),
        gte19(alertEvents.createdAt, oneDayAgoMs)
      )).limit(1);
      if (!recentEvent[0]) {
        await db.insert(alertEvents).values({
          subscriptionId: sub.id,
          alertType: sub.subscriptionType,
          triggerSource: sub.targetScope,
          riskScore,
          riskLevel: riskScore >= 70 ? "critical" : riskScore >= 40 ? "warning" : "info",
          severity: riskScore >= 70 ? "critical" : riskScore >= 40 ? "warning" : "info",
          message,
          createdAt: now3
        });
        const [evt] = await db.select().from(alertEvents).where(eq67(alertEvents.subscriptionId, sub.id)).orderBy(desc46(alertEvents.id)).limit(1);
        if (evt) newEvents.push(evt);
      }
    }
  }
  return newEvents;
}
async function processEventsToDelivery() {
  const undelivered = await db.select().from(alertEvents).where(sql113`${alertEvents.sentAt} IS NULL`).orderBy(alertEvents.createdAt).limit(50);
  const deliveries = [];
  const now3 = Date.now();
  for (const evt of undelivered) {
    const [sub] = await db.select().from(alertSubscriptions).where(eq67(alertSubscriptions.id, evt.subscriptionId)).limit(1);
    if (!sub) continue;
    await db.insert(alertDeliveryLog).values({
      alertId: evt.id,
      // alertFrequency is the closest available column; alertChannel does not exist in the schema.
      channel: sub.alertFrequency || "immediate",
      recipient: sub.userId,
      status: "delivered",
      sentAt: now3
    });
    await db.update(alertEvents).set({ sentAt: now3 }).where(eq67(alertEvents.id, evt.id));
    const [delivery] = await db.select().from(alertDeliveryLog).where(eq67(alertDeliveryLog.alertId, evt.id)).orderBy(desc46(alertDeliveryLog.id)).limit(1);
    if (delivery) deliveries.push(delivery);
  }
  return deliveries;
}
async function getUserNotifications(userId, limit = 50) {
  const subs = await db.select().from(alertSubscriptions).where(eq67(alertSubscriptions.userId, userId));
  if (subs.length === 0) return [];
  const subIds = subs.map((s) => s.id);
  const events2 = await db.select().from(alertEvents).orderBy(desc46(alertEvents.createdAt)).limit(limit * 2);
  return events2.filter((e) => e.subscriptionId && subIds.includes(e.subscriptionId)).slice(0, limit);
}
async function markNotificationRead2(eventId) {
  await db.update(alertEvents).set({ sentAt: Date.now() }).where(eq67(alertEvents.id, eventId));
}
async function getAlertingStats() {
  const [totalSubs] = await db.select({ count: sql113`COUNT(*)` }).from(alertSubscriptions);
  const [activeSubs] = await db.select({ count: sql113`COUNT(*)` }).from(alertSubscriptions).where(eq67(alertSubscriptions.isPaused, 0));
  const [totalEvents] = await db.select({ count: sql113`COUNT(*)` }).from(alertEvents);
  const [pendingDeliveries] = await db.select({ count: sql113`COUNT(*)` }).from(alertDeliveryLog).where(eq67(alertDeliveryLog.status, "pending"));
  return {
    totalSubscriptions: totalSubs?.count || 0,
    activeSubscriptions: activeSubs?.count || 0,
    totalEvents: totalEvents?.count || 0,
    pendingDeliveries: pendingDeliveries?.count || 0
  };
}

