async function reconnectKnowledgeEntries() {
  const result = {
    sector: "knowledge",
    table: "knowledge_entries",
    recordsCreated: 0,
    skipped: 0,
    errors: []
  };
  try {
    const [existing] = await db.select({ count: sql128`COUNT(*)` }).from(knowledgeEntries);
    if (existing.count > 0) {
      result.skipped = existing.count;
      return result;
    }
    let moduleId = 1;
    const modules = await db.select().from(knowledgeModules);
    if (modules.length > 0) {
      moduleId = modules[0].id;
    }
    const programs = await db.select().from(registryPrograms);
    const workflows = await db.select().from(registryWorkflows);
    const now3 = Date.now();
    for (const p of programs.slice(0, 200)) {
      try {
        await db.insert(knowledgeEntries).values({
          moduleId,
          entryId: `program-${p.id}`,
          entryName: p.name || p.programName || "Unknown Program",
          category: p.category || p.domain || "general",
          domain: p.domain || "general",
          payload: JSON.stringify({
            type: "program",
            sourceTable: "registry_programs",
            sourceId: p.id,
            description: p.description,
            stateCode: p.stateCode
          }),
          createdAt: now3
        });
        result.recordsCreated++;
      } catch (e) {
        result.errors.push(`program-${p.id}: ${e.message}`);
      }
    }
    for (const w of workflows) {
      try {
        await db.insert(knowledgeEntries).values({
          moduleId,
          entryId: `workflow-${w.id}`,
          entryName: w.name || w.workflowName || "Unknown Workflow",
          category: "workflow",
          domain: w.domain || "general",
          payload: JSON.stringify({
            type: "workflow",
            sourceTable: "registry_workflows",
            sourceId: w.id,
            steps: w.steps
          }),
          createdAt: now3
        });
        result.recordsCreated++;
      } catch (e) {
        result.errors.push(`workflow-${w.id}: ${e.message}`);
      }
    }
  } catch (e) {
    result.errors.push(e.message);
  }
  return result;
}
