      ingested_records: irRows[0]?.cnt ?? 0,
      detected_signals: dsRows[0]?.cnt ?? 0,
      signal_flow_logs: sflRows[0]?.cnt ?? 0,
      world_nodes: wnRows[0]?.cnt ?? 0,
      canonical_remedy_paths: rpRows[0]?.cnt ?? 0,
