    if (invite.invite_status === "exhausted") throw new TRPCError17({ code: "BAD_REQUEST", message: "This invite has reached its usage limit" });
    if (invite.expires_at < Date.now()) throw new TRPCError17({ code: "BAD_REQUEST", message: "This invite has expired" });
    if (invite.use_count >= invite.max_uses) throw new TRPCError17({ code: "BAD_REQUEST", message: "This invite has reached its usage limit" });
    await redeemInvite(invite.id, ctx.user.id, invite.target_role, invite.target_plan);
