function sessionMiddleware(req, res, next) {
  const cookies = parseCookies(req.headers.cookie);
  const sessionCookie = cookies.get(COOKIE_NAME);
  if (!sessionCookie) {
    req.session = null;
    next();
    return;
  }
  sdk.verifySession(sessionCookie).then((session) => {
    if (!session) {
      console.log("[SessionMiddleware] Session verification failed");
      req.session = null;
      next();
      return;
    }
    req.session = {
      openId: session.openId,
      appId: session.appId,
      name: session.name,
      user: {
        email: null
        // Will be populated by context.ts
      }
    };
    console.log("[SessionMiddleware] Session verified:", {
      openId: session.openId,
      name: session.name
    });
    next();
  }).catch((error) => {
    console.error("[SessionMiddleware] Error:", error);
    req.session = null;
    next();
  });
}
function parseCookies(cookieHeader) {
  const cookies = /* @__PURE__ */ new Map();
  if (!cookieHeader) return cookies;
  cookieHeader.split(";").forEach((cookie) => {
    const [name, value] = cookie.split("=");
    if (name && value) {
      cookies.set(name.trim(), decodeURIComponent(value.trim()));
    }
  });
  return cookies;
}

