async function setupVite(app, server) {
  const serverOptions = {
    middlewareMode: true,
    hmr: { server },
    allowedHosts: true
  };
  const vite = await createViteServer({
    ...vite_config_default,
    configFile: false,
    server: serverOptions,
    appType: "custom"
  });
  app.use(vite.middlewares);
  app.use("*", async (req, res, next) => {
    const url = req.originalUrl;
    try {
      const clientTemplate = path5.resolve(
        import.meta.dirname,
        "../..",
        "client",
        "index.html"
      );
      let template = await fs4.promises.readFile(clientTemplate, "utf-8");
      template = template.replace(
        `src="/src/main.tsx"`,
        `src="/src/main.tsx?v=${nanoid()}"`
      );
      const page2 = await vite.transformIndexHtml(url, template);
      res.status(200).set({ "Content-Type": "text/html" }).end(page2);
    } catch (e) {
      vite.ssrFixStacktrace(e);
      next(e);
    }
  });
}
function serveStatic(app) {
  const candidates = [
    path5.resolve(import.meta.dirname, "public"),
    path5.resolve(import.meta.dirname, "../..", "dist", "public"),
    path5.resolve(process.cwd(), "dist", "public"),
    path5.resolve(process.cwd(), "public")
  ];
  let distPath = candidates[0];
  for (const candidate of candidates) {
    if (fs4.existsSync(path5.join(candidate, "index.html"))) {
      distPath = candidate;
      break;
    }
  }
  console.log(`[Static] Serving from: ${distPath} (exists: ${fs4.existsSync(distPath)}, has index.html: ${fs4.existsSync(path5.join(distPath, "index.html"))})`);
  if (!fs4.existsSync(distPath)) {
    console.error(
      `Could not find the build directory: ${distPath}, make sure to build the client first`
    );
  }
  app.use(express5.static(distPath, {
    setHeaders: (res, filePath) => {
      if (filePath.endsWith(".html")) {
        res.setHeader("Cache-Control", "no-cache, no-store, must-revalidate");
      }
    }
  }));
  app.use("*", (_req, res) => {
    res.setHeader("Cache-Control", "no-cache, no-store, must-revalidate");
    res.sendFile(path5.resolve(distPath, "index.html"));
  });
}

